window.__D("text/torat-chaim/c028",{"p":[[2300550348,"בצירוף שם הוי' באלקים כו', הענין הוא דגם בעשי' דמע\"ב הי' גם שם הוי' באלקים רק שהי' בהעלם והתלבשות בשם אלקים המעלימו, כי א\"א לבחי' השתלשלו' דחו\"ב ומדות ומח' ודבור בסוף מעשה כ\"א ע\"י ד' אותיות דשם הוי' ע\"י צמצום [דשם אלקי'] כו', רק שבשבת נתגלה שם הוי' מלבוש וצמצום דשם אלקי' (כמ\"ש בס' הקבלה בענין ך\"ו כל\"ח<sup data-n=\"905\">150</sup> שזהו בקיעת האור דשם הוי' באלקי' כו' כמ\"ש שבת להוי'<sup data-n=\"906\">151</sup> דוקא ולא נז' שבת לאלקים כי שם אלקי' עיקר העושה מע\"ב מטעם הנ\"ל וד\"ל).\n<b>והנה</b><sup data-n=\"907\">152</sup> כתיב כי בו <span data-k=\"pg\">780</span> ּ שבת כו' אשר ברא אלקים לעשות וארז\"ל לעשות לתקן<sup data-n=\"908\">153</sup> כו', וכמו\"כ באדה\"ר בג\"ע אמר לעבדה ולשמרה לעבדה זה רמ\"ח מ\"ע ולשמרה שס\"ה ל\"ת<sup data-n=\"909\">154</sup>, וגם כאן לעשות לתקן היינו לתקן לי' מאמרות דכל ו' ימי החול הוא בתשובה ומע\"ט כידוע דשבת אותיות תשב<sup data-n=\"910\">155</sup> כו'. וזהו דוקא בגמר כל מלאכתו ששבת מכל מלאכה כו' אשר ברא אלקי' לעשות לתקן כדי לתקן שבחי' התיקון הזה דתשובה ומע\"ט היינו בחי' או\"ח בהעלא' התענוג מכל אשר עשה בוי\"ו ימ\"ב כנ\"ל במ\"ש וירא אלקי' את כל אשר עשה והנה טוב מאד בלי גבול<sup data-n=\"911\">156</sup> כלל. והטעם הוא לפי שענין התשובה הוא היפוך הרע לטוב בלב נשבר ונדכה כמו תשב אנוש עד דכא<sup data-n=\"912\">157</sup> כו', וזהו עיקר ענין הבירורים דק\"נ לאהפכא חשוכא לנהורא<sup data-n=\"913\">158</sup> ומרירו למיתקא שזהו גדול יותר גם מתומ\"צ כמארז\"ל דבמקום שבע\"ת עומדי'<sup data-n=\"914\">159</sup> אין צ\"ג יכולים לעמוד כלל וכמ\"ש בזהר דבע\"ת משכין לקדב\"ה בחילא יתיר<sup data-n=\"915\">160</sup> דהיינו בנקודת הרצון שבעומק הלב בביטול כל [העצמות] מכל וכל בכל כחו (כראב\"ד שיצא נשמתו בבכי'<sup data-n=\"916\">161</sup> וכה\"ג נתן דצוציתא<sup data-n=\"917\">162</sup> ), וגם מע\"ט שהן המצות שנמשך רצה\"ע בדברים גשמיי' דק\"נ כו' שזהו בירור דעה\"ד טו\"ר בסו\"מ וע\"ט הכל הוא ענין הבירורים<sup data-n=\"918\">163</sup> דרפ\"ח כו' בכל וי\"ו ימי החול שזה עלה בתחלת המח' והרצון הפשוט בפנימי' כוונת המאציל להאציל ולברוא מאין ליש בכל אשר עשה בי' מאמרות למעלה ולמטה כו', משום דנעוץ תחב\"ס כו' וסוף מעשה בבירורים דרפ\"ח כו' הוא שעלה במח' תחלה בבחי' או\"ח בתענוג גדול הרבה ביותר מן התענוג ורצון שירד בחכ' דמע\"ב מאין והעלם דכתר לחו\"ב ומדות ומח' ודיבור כנ\"ל. וזהו לעשות לתקן דלעשות כל מע\"ב בחו\"ב ומדות כו' רק בשביל לתקן ע\"י תשובה ומע\"ט שהוא בחי' או\"ח דתענוג הגדול יותר שעלה במח' תחלה",[["905","150","<b>בענין ך\"ו כל\"ח</b>: ראה גם לעיל קמד, א. וש\"נ."],["906","151","<b>שבת להוי'</b>: יתרו כ, י. ועוד."],["907","152","<b>והנה</b>: ב: נרשם כאן פ\"ח. ראה לעיל הערה 119."],["908","153","<b>לעשות לתקן</b>: ראה ב\"ר פי\"א, ו וברש\"י שם. לעיל פ' בשלח קלט, ד בשם הע\"ח. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תתסח. דברים ח\"ד ע' א'רט. סה\"מ תרצ\"ז ע' 214."],["909","154","<b>לעבדה ולשמרה. . רמ\"ח מ\"ע. . שס\"ה ל\"ת</b>: בראשית ב, טו. ראה זהר בראשית כז, א. תרומה קסה, ב. הנסמן במאמרי אדה\"א בראשית ע' עג. קונטרסים ע' שי."],["910","155","<b>דשבת אותיות תשב</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'קפ. וש\"נ. תו\"ח נח נה, ב ובהערה 20."],["911","156","<b>מאד בלי גבול</b>: ראה אגה\"ק סי\"ז. הנסמן לעיל פ' וארא סא, ב הערה 69."],["912","157","<b>תשב אנוש עד דכא</b>: תהלים צ, ג."],["913","158","<b>לאהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["914","159","<b>דבמקום שבע\"ת עומדי'</b>: ראה ברכות לד, ב. לעיל פ' שמות מא, א. וש\"נ."],["915","160","<b>דבע\"ת. . בחילא יתיר</b>: ראה זהר ח\"ש קכט, ב. לעיל לז, א. וש\"נ."],["916","161","<b>כראב\"ד שיצא נשמתו בבכי'</b>: ע\"ז יז, א. ראה סה\"מ תרמ\"ו ע' יט."],["917","162","<b>נתן דצוציתא</b>: ראה שבת נו, ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'שעז. הנחות תקע\"ז ע' ריג. ש\"א מ, א ובהערה 1. לקמן פ' תצוה שמו, ב. פקודי תנו, ג."],["918","163","<b>המצות. . הוא ענין הבירורים</b>: ראה מאמרי אדה\"ז על ענינים ע' רכה ואילך. ע' רנג ואילך. ע' רסו ואילך."]]],[2300550371,"כנ\"ל. וזהו שבת אותיות תשב שזהו [תשובה] תשוב ה\"א, ויש בשבת ב' מדרגות שבת תתאה בעלי' חכמה שבי' מאמרות חכ' בסוף ובחי' שבת עילאה גם בעליי' דחכ' בראש כנ\"ל והן ב' מיני תשובה תשו\"ע ותשובה תתאה כידוע. וזהו וירא אלקי' והנה טוב מאד מאד דוקא להיות שעונג הראשון שהי' ברצון וחכ' דמע\"ב בראש ובסוף לא נק' טוב מאד, אך אחר כלות וימ\"ב שנעשה ונתקן בתשובה ומע\"ט כנ\"ל הוא שנק' טוב מאד בלי גבול [ל]היותו עולה בעונג העצמי שהוא בלתי מוגבל כלל שהוא ע\"י תשובה דוקא, וראי' לזה ממ\"ש טוב זה מלאך חיים מאד זה מה\"מ<sup data-n=\"919\">164</sup> כשנהפך מרע לטוב ע\"י תשובה הנק' טוב מאד בלי גבול שגם צ\"ג במע\"ט שנק' חיים וטוב אין יכולים לעמוד שם כנ\"ל וד\"ל. ואמנם<sup data-n=\"920\">165</sup> גם ע\"י המצות בדברים גשמי' דק\"נ שמתברר הטוב מן הרע זהו ג\"כ בחי' התיקון למע\"ב שע\"ז אמר ג\"כ וירא אלקי' את כל אשר עשה שזהו מה שישראל עושין מצות כל ימות החול והנה טוב מאד לפי שא\"א למצות בלי תשובה דתכלית חכ' תשובה ומע\"ט<sup data-n=\"921\">166</sup> כידוע וד\"ל. וזהו ושמרו בנ\"י את השבת לעשות את השבת כו', וכן בדברות האחרונו' אמר שמור את יום השבת כו' וזכרת כי עבד היית כו' <span data-k=\"pg\">שצ</span> ּ ע\"כ צוך ה' [אלקיך] לעשות את יום השבת שישראל הן העושים את יום השבת בעלי' דאו\"ח הנ\"ל ע\"י תשובה ומע\"ט שלהם כל ימות החול כו' וד\"ל.\n[ה] <b>אך</b> הנה באמת יש להבין איך יתכן לומר שישראל בתשובה ומע\"ט שלהם עושים את השבת כמ\"ש לעשות לתקן והלא שבת כבר מיקדשא וקיימא מוי\"ו ימ\"ב בשבת בראשית הראשון דכתי' ויברך כו' ויקדש אותו כו' וכל שבת נק' שבת בראשית לפי שמחדש בכל יום [מחדש] מע\"ב ושובת ונח ביום הז' כידוע, א\"כ איך נאמר שישראל עושין לשבת כו'. ואמנם הנה יש להקדים תחלה ענין א' והוא מ\"ש חכמות בחוץ תרונה<sup data-n=\"922\">167</sup> ואמר בזהר חכמות ב' חכמות ח\"ע וח\"ת<sup data-n=\"923\">168</sup>, ח\"ע דאתמשך בח\"ת ועל שניהם יחד דוקא אמר דחכמות ח\"ע וח\"ת בחוץ דוקא תרונה ברינה ושיר והיינו בתכלית הבירורים דק\"נ שנק' חוץ כמ\"ש אמצאך בחוץ אשקך<sup data-n=\"924\">169</sup> כו' כידוע דבחכ' אתברירו<sup data-n=\"925\">170</sup> בחכ' דתורה ומצות דוקא כו' כנ\"ל וד\"ל.\n<b>ולהבין</b> ביאור הדברים, הנה ידוע דבחי' ח\"ע היינו בחי' עצמות חכמתו ית' שבתורה שנק' חכים ולא בחכ'",[["919","164","<b>טוב זה מלאך חיים מאד זה מה\"מ</b>: בראשית א, לא. יל\"ש שם (רמז טז). זהר בהקדמה יד, א. בד: (ו)טוב מאד זה מה\"מ — ראה ב\"ר פ\"ט, י. ראה הנסמן לעיל פ' בא קכג, ג."],["920","165","<b>ואמנם</b>: ב: נרשם כאן פ\"ט. ראה לעיל הערה 152."],["921","166","<b>דתכלית חכ' תשובה ומע\"ט</b>: ברכות יז, א. ראה גם לעיל פ' וארא סה, ד ובהנסמן שם."],["922","167","<b>חכמות בחוץ תרונה</b>: משלי א, כ."],["923","168","<b>חכמות בחוץ. . ח\"ע וח\"ת</b>: ראה זהר תולדות קמא, ב. מאמרי אדה\"א בראשית ע' קכג. וש\"נ."],["924","169","<b>אמצאך בחוץ אשקך</b>: שה\"ש ח, א."],["925","170","<b>דבחכ' אתברירו</b>: ראה זהר (היכלות) פקודי רנד, סע\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה־ שמות ח\"ב ע' שכא. לקמן פ' תשא שפד, ד."]]],[2300550390,"ידיעא<sup data-n=\"926\">171</sup>, ופי' ולא בחכ' ידיעא שאינ[ה] מוגבלת בבחי' אור וכלי כמ\"ש לתבונתו אין מספר<sup data-n=\"927\">172</sup> (ויש בזה ב' מדרגות, א' בחי' חכ' דאצי' שנק' אור אבא והוא הבא בהתלבשות בנגלה שבתורה. והב' בחי' ח\"ס שנק' תעלומות חכ'<sup data-n=\"928\">173</sup> והוא בחי' פנימיות התורה (כמשי\"ת). והיינו בבחי' חכ'<sup data-n=\"929\">174</sup> דא\"ס עצמו שהוא בבחי' א\"ס ממש ומתצמצם ביותר<sup data-n=\"930\">175</sup> בקו\"ח ונק' חכ' דא\"ק כו' עד חכ' שבמל' דאצי' שכולם בחכ' עשית שנק' חכמה תתאה שבי' מאמרות עד חכ'<sup data-n=\"931\">176</sup> דמל' דעשי' כו'<sup data-n=\"932\">177</sup>. והנה<sup data-n=\"933\">178</sup> ארז\"ל דנובלות חכ' שלמעלה תורה<sup data-n=\"934\">179</sup> (ונובלות בינה שלמעלה שכינה<sup data-n=\"935\">180</sup> ) דהיינו מבחי' חכים ולא בחכ' ידיעא הנ\"ל נמשך בחי' הנובלות ומותרות והוא חכ' שבתורה הנגלית לנו, וזה פלא גדול מאד שהרי התורה קדמה לעולם<sup data-n=\"936\">181</sup> כמ\"ש ואהי' אצלו אמון<sup data-n=\"937\">182</sup> כו' וכתיב בה ה' קנני ראשית דרכו<sup data-n=\"938\">183</sup> כו' איך תקרא בשם נובלות דחש\"מ.\n<b>אך</b> [הנה] הענין הוא כידוע דלשבח דוקא קאמר<sup data-n=\"939\">184</sup> להיות שבח\"ע יש ב' מדרגות פנימי' וחיצוני' ובחי' החיצוני' שבה היא התורה שלנו שבאה בדברים גשמיי' דוקא שזה בא מכח החיצוני' ונובלות דחש\"מ העצמי הנ\"ל, והיינו מה שיש בכח הח\"ע דתוה\"ק לבא ולירד למטה מטה בבחי' החיצוני' כדי לברר בירורים דעה\"ד טו\"ר דק\"נ כי ידוע דבחכ' אתברירו דוקא כל הרפ\"ח כו'. והיינו בחי' חכ' שבתורה הנגלית לנו שמתלבש[ת] בדברים גשמיי' לברר ולהבדיל בין טמא לטהור כו' שזהו ע\"פ בחי' ח\"ע הפנימי' ועצמ[י]ת דוקא רק שירד האור [ו]שפע דח\"ע למטה להיות בבחי' נובלות חכ' שלמעלה<sup data-n=\"940\">185</sup> וחיצוני'. וזהו שאמר נובלות חש\"מ תורה ולרבותא קאי<sup data-n=\"941\">186</sup> דגדול כח הזה שנמשך מחכ' שלמעלה דתורה הקדומה למטה ביותר לברר לעה\"ד משום דסוף מעשה עבמח\"ת [יותר] מגוף ח\"ע הקדומה הפנימיות (כמו מי שכח חכמתו עמדה לו<sup data-n=\"942\">187</sup> לתקן דבר מה שגדול כח זה מעצם חכמתו כמ\"ש במ\"א). וכמו\"כ במצות מעשיות בדברים גשמיי' ברמ\"ח מ\"ע ע\"פ משפט חכ' שבתורה ה\"ז בחי' ירידת אור דח\"ע שבתורה הקדומה (וז\"ש ואהי' אצלו אמון אומנא<sup data-n=\"943\">188</sup> לתקן כמ\"ש לעשות לתקן בל\"ת <span data-k=\"pg\">782</span> ּ שעשועי' ברמ\"ח מ\"ע). וכמו שאנו רואים בענין חכמה שבמצות ציצית ותפילין וכה\"ג שזהו למעלה הרבה גם ממקור החכ' דמע\"ב כמו ל\"ב חוטין בציצית שהן ל\"ב נ\"ח<sup data-n=\"944\">189</sup> שנמשכים מבחי' מקיף היותר עליון שנק' לבושי' כתלג<sup data-n=\"945\">190</sup> כו' שזהו למעלה [הרבה] גם מבחי' סובב הכללי דמע\"ב כו' וד\"ל. וכה\"ג במצות תפילין שהן ד' מוחין דבחי' המקיפי' בבליטה ע\"ג",[["926","171","<b>חכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה (יז, ב)."],["927","172","<b>לתבונתו אין מספר</b>: תהלים קמז, ה."],["928","173","<b>תעלומות חכ'</b>: איוב יא, ו. ראה גם לעיל פ' שמות לג, א. וש\"נ."],["929","174","<b>חכ'</b>: גד: ח\"ס."],["930","175","<b>ביותר</b>: בגד: ויורד."],["931","176","<b>חכ'</b>: גד: מל'."],["932","177","<b>כו'</b>: כנצ\"ל: כו')."],["933","178","<b>והנה</b>: ב: נרשם כאן פ\"י. ראה לעיל הערה 165."],["934","179","<b>דנובלות חכ' שלמעלה תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["935","180","<b>ונובלות בינה שלמעלה שכינה</b>: ראה ע\"ח שער הכלללים ספ\"א. הנסמן לעיל ג, ב."],["936","181","<b>התורה קדמה לעולם</b>: פסחים נד, א."],["937","182","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["938","183","<b>ה' קנני ראשית דרכו</b>: משלי ח, כב."],["939","184","<b>דלשבח. . קאמר</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'רכ ואילך. וש\"נ. תו\"ח נח סג, ב ובהערה 26."],["940","185","<b>חכ' שלמעלה</b>: בד: ליתא."],["941","186","<b>קאי</b>: שם: קאמר."],["942","187","<b>מי שכח חכמתו עמדה לו</b>: ראה גם תו\"ח ח\"ש קלא, א. קלג, ד."],["943","188","<b>ואהי' אצלו אמון אומנא</b>: ב\"ר בתחלתו."],["944","189","<b>ל\"ב חוטין. . ל\"ב נ\"ח</b>: ראה זח\"ג (תוספת) שא, א. מאמרי אדה\"א בראשית ע' שצד. וש\"נ."],["945","190","<b>לבושי' כתלג</b>: דניאל ז, ט."]]],[2300550407,"הראש דז\"א כענין הקב\"ה מניח תפילין<sup data-n=\"946\">191</sup> ומתעטף בטלית<sup data-n=\"947\">192</sup> כו'. וכה\"ג יובן בכל המצות בקרבנות באופני ההעלאה וההמשכה הכל במשפט החכ' דתורה שירד מאור הפנימי' דח\"ע הקדומה בדברים גשמיי' בבהמה וצאן גשמי, וגם צומח ודומם גשמי כמו מצות החשן ואפוד דכהן גדול שנקבעו בהם אבנים גשמיי' בי\"ב אבנים הנקובים<sup data-n=\"948\">193</sup> אודם פטדה וברקת<sup data-n=\"949\">194</sup> כו' שהם וישפה<sup data-n=\"950\">195</sup> שיתקנו<sup data-n=\"951\">196</sup> בהם שמות השבטים, וכתי' ונשא אהרן כו' לפני ה' לזכרון<sup data-n=\"952\">197</sup> כו' שהוא ענין המשכת חסדים באורות העליוני' שמשם ימשיך אהרן כה\"ג מקור כל חסד לבנ\"י בכל שבט ושבט בשמות הנחקקים [באבן] מלפני עצמות אור המאציל ממש כו', הרי נתלבשה חכמה זו באבנים גשמיי' ובמעשה דחשן ואפוד [כו']. וכה\"ג יובן בכל מעשה המצות בדברים גשמיי' דדצח\"[ם] הגשמי' שזהו רק מבחי' ירידה דאור ח\"ע דתורה הקדומה הנ\"ל, וע\"כ נק' חכמה זו שבנגלה דתורה בשם בחי' חכ' תתאה דוקא להיותה מתלבשת למטה מטה בעולם הפירוד בדברים גשמיים דנוגה דעשיי' לאהפכא חשוכא כו' בסו\"מ דל\"ת ובבירור הטוב הגנוז במעשה המצות ברמ\"ח מ\"ע שכ\"ז רק ענין ההעלאה ובירורים דחכ' תתאה דתו' דוקא וד\"ל.\n<b>וזהו</b><sup data-n=\"953\">198</sup> שאמר חכמות בחוץ דוקא תרונה דהיינו [כ]שנמשך החכמה דתורה למטה ממש בק\"נ שנק' חוץ לברר ולהבדיל בין טו\"ר בסו\"מ וע\"ט כנ\"ל אז תרונה ברינה ושיר על שלימות דחכ' שהוברר הכל משום דנעוץ תחב\"ס דוקא, שאין רבותא כלל בח\"ע הפנימי' שגנוז ונעלם בהיכלות הפנימי' בטעמי מצות וסודות התורה רק הרבותא הוא בנובלות דחש\"מ דוקא שיצא לחוץ בהיכלות דנוגה דעשי' לבררם זהו העושה שלימות גם בפנימי' דח\"ע (מטעם הנ\"ל). וע\"כ חכמות בחוץ ב' חכמות משום דגם ח\"ע יורדת ומתלבשת בח\"ת לברר בירורים דק\"נ כו', ועי\"ז נשלמת גם היא ואע\"פ שח\"ע נותן כח ועוז ל[ח]\"ת לברר אבל אחר שלימות הבירור דח\"ת נעשה שלימות בח\"ע על ידה דוקא. וזהו תושבע\"פ שתעלה למעלה מתושב\"כ לע\"ל כמ\"ש א\"ח עט\"ב<sup data-n=\"954\">199</sup> כו' וכמו שאמר דבינה יתירה ניתנה באשה<sup data-n=\"955\">200</sup> כו' שהוא תושבע\"פ יותר מבאיש שהוא תושב\"כ (כמשי\"ת) וז\"ש חכמות בחוץ ח\"ע וח\"ת שניהם יחד בחוץ דוקא תרונה וד\"ל.\n[ו<sup data-n=\"956\">201</sup> ] והנה החכ' נק' ראשית לשון נוקבא כמו בראשית ברא בחוכמתא וכן ה' קנני ראשית דרכו וכתיב ראשית",[["946","191","<b>הקב\"ה מניח תפילין</b>: ברכות ו, א."],["947","192","<b>ומתעטף בטלית</b>: ראה ר\"ה יז, ב. מאמרי אדה\"א שמות ח\"ב ע' שסו. וש\"נ."],["948","193","<b>הנקובים</b>: ב: הטובות. ד: הנחקקים."],["949","194","<b>אודם פטדה וברקת</b>: תצוה כח, יז."],["950","195","<b>שהם וישפה</b>: תצוה שם, כ."],["951","196","<b>שיתקנו</b>: בד: שנחקק(ים)."],["952","197","<b>ונשא אהרן. . לזכרון</b>: תצוה כח, כט [ושם: לזכרון לפני ה']."],["953","198","<b>וזהו</b>: ב: נרשם כאן פי\"א. ראה לעיל הערה 178."],["954","199","<b>א\"ח עט\"ב</b>: משלי יב, ד."],["955","200","<b>דבינה יתירה ניתנה באשה</b>: ראה נדה מה, ב. לעיל פ' שמות י, ב הערה 458."],["956","201","<b>ו</b>: ב: נרשם כאן פי\"ב. ראה לעיל הערה 198."]]],[2300550424,"חכ' וגם החכמה נק' ראש חכמה בראש כמ\"ש ראש דברך אמת<sup data-n=\"957\">202</sup> כו'. והענין הוא כידוע דראש לשון דכר וראשית לשון נוק' והוא מפני שיש ב' מדרגות בחכמה, א' כשנק' חכמה בחי' נוק' בחי' מקבל כאשר כבר באה בגילוי ממקורה מאין ליש וכמ\"ש והחכ' מאין תמצא שתמצא במציאת חכ' ממש בבחי' יש [ובאה] מאין והעלם דעצמו' המאציל בדרך עו\"ע. <span data-k=\"pg\">שצא</span> ּ והב' מקור הנובע כל שכל וחכמה שנק' משכיל ההיולי (בחי' ח\"ס) נק' ראש שמשפיע בגילוי מאין והעלם החכ' ליש שנק' ראשית. והיינו ב' מדרגות דח\"ע וח\"ת הנ\"ל דבחי' ראש דח\"ע לא בא לגילוי בדבור כלל, ובחי' ראשית דחכ' בחי' מקבל מראש הוא בא בגילוי בחכמה שבדבור וחכמה דמע\"ב הוא בראשית דחכ' שבא בי' מאמרות [ליש]. ומ\"ש חכמות בחוץ דח\"ע אתמשך בח\"ת היינו ראש דחכ' שנק' מקור המשפיע כל חכמה מאין ליש כנ\"ל וזהו הבא בהתלבשות בבירורים דעה\"ד כו' במ\"ע ול\"ת שנק' נובלות חש\"מ שבבחי' ראש דוקא וד\"ל. ואמנם בחי' פנימי' התענוג שהוא מקור גם לבחי' ראש דח\"ע שיורד בתו\"מ שלמטה הוא הנק' אש\"ר בהיפוך אותיות רא\"ש<sup data-n=\"958\">203</sup> וזהו אשר קדשנו במצותיו<sup data-n=\"959\">204</sup> אשר זה לשון תענוג המופלא ביותר וגם הוא ענין אשר[י]<sup data-n=\"960\">205</sup> המאושר כמו ותומכיה מאושר<sup data-n=\"961\">206</sup> כו' ראוה בנות ויאשרוה<sup data-n=\"962\">207</sup> כו' היינו הנבחר מהכל (והוא ענין פנימית אור התענוג העליון שבי\"מ<sup data-n=\"963\">209</sup> למעלה שהוא מקור ושרש גם לבחי' ראש דח\"ע שנק'<sup data-n=\"964\">208</sup> ח\"ס שהוא כמו כח המשכיל ההיולי כנ\"ל). וכמו שאנו רואים למטה בנפש האדם גם שנק' נפש השכלי[ת]<sup data-n=\"965\">210</sup> להשכיל כל שכל מהעלם לגילוי מ\"מ לא בכל פעם יש כח בכח השכל להשכיל רק מצד בחי' העונג העצמי ופנימי' שהוא מקור להיות כח ועוז בכח השכל להשכיל כל שכל. וראי' לזה ממה שאנו רואים שכאשר ישכיל אדם ויחדש איזה שכל הרי יתענג בו בנפשו ביותר עד שיאירו פניו מרוב חדוה כמו ר' אבוה מצא תוספתא חדתא וצהבו פניו<sup data-n=\"966\">211</sup> כמ\"ש חכמת אדם תאיר פניו<sup data-n=\"967\">212</sup> כידוע, ולכאו' אין חיבור ושייכות לתענוג עם השכל כלל אלא מפני שחידוש השכל גם במקורו בא מכח העונג<sup data-n=\"968\">213</sup> שבעצמות הנפש שהוא מקור מוצא לעורר לכח המשכיל שיחדש חידושים דחכמה מאין ליש כו', והוא בחי' יסוד המים ולחלוחית שבעונג הרוחני שבנפש שהוא מקור המוליד ומצמיח להשכיל השכלות שיחודשו מכח המשכיל (וזהו דמוח החכ' קר ולח<sup data-n=\"969\">214</sup> כו'), וע\"כ יתענג בנפשו כשיחדש שכל חדש דוקא כי זה העונג הוא מקורו הראשון שהשפיע לכח המשכיל שיחדש שכל זה כו'. וא\"כ הרי",[["957","202","<b>ראש דברך אמת</b>: תהלים קיט, קס. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תנד."],["958","203","<b>אש\"ר. . רא\"ש</b>: ראה זהר בראשית טו, סע\"א. מאמרי אדה\"ז תקס\"ט כאן (ס\"ע לז). תו\"א כאן (ע, רע\"ב). מאמרי אדה\"א הנחות תקע\"ז ע' ה. וש\"נ."],["959","204","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות."],["960","205","<b>אשר. . תענוג. . אשר[י]</b>: ויצא ל, יג. ראה ת\"ז ת\"ל (עד, ב). תל\"ט (עט, א). מאמרים שנסמנו בהערה 203. לקו\"ת בשלח א, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תשנט. דברים ח\"ד ע' א'שכה. נ\"ך ע' שכז ובהנסמן בהנ\"ל."],["961","206","<b>ותומכיה מאושר</b>: משלי ג, יח."],["962","207","<b>ראוה בנות ויאשרוה</b>: שה\"ש ו, ט."],["963","209","<b>שבי\"מ</b>: בד: שבמצו'."],["964","208","<b>(והוא. . שנק'</b>: בד: והוא. . (שנק'."],["965","210","<b>נפש השכלי[ת]</b>: ראה גם לעיל פ' בא קא, ג. וש\"נ."],["966","211","<b>ר' אבוה. . וצהבו פניו</b>: ראה ירושלמי שבת פ\"ח, ה\"א. לעיל פ' בשלח קעח, ב. וש\"נ."],["967","212","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["968","213","<b>שחידוש השכל. . מכח העונג</b>: ראה גם מאמרי אדה\"ז תקס\"ט כאן (ע' לז). תו\"א כאן (ע, א). שע\"ת קכז, א ובהערה 1."],["969","214","<b>דמוח החכ' קר ולח</b>: ראה גם לעיל פ' שמות כז, ג. וש\"נ."]]],[2300550440,"יובן דגם בחי' ראש דח\"ע שהוא ח\"ס בחי' מקבל הוא מבחי' העונג העצמי שברצון העליון שבמצות שהוא מקור גם לכח החכ' [ש]למעלה (וזה כמו בחי' גבורות דע\"י שמלובש בח\"ס<sup data-n=\"970\">215</sup> כו'), וזהו אשר קדשנו כו' אשר בחי' התענוג העליון שלמעלה מראש דח\"ע (כמו אהי' אשר אהי'<sup data-n=\"971\">216</sup> בעוה\"ב בשכר המצות). וזהו פי' ברכת המצות ברוך אתה הוי' אלקינו הוא יחו\"ע שבחו\"ב דאצי' עד מלך העולם הוא בחי' יחו\"ת דמל' דאצי' וכנ\"ל בפי' חכמות בחוץ כו', ואמנם כ\"ז נמשך מבחי' אש\"ר שבמצות שהוא פנימי' התענוג העליון שברצה\"ע שבמצותיו כו' לפי שסוף מעשה עלה במח' תחלה<sup data-n=\"972\">217</sup> ועי\"ז נשלם גם בחי' ראש וראשית דח\"ע מטעם הנ\"ל וד\"ל.\n<b>ומעתה</b><sup data-n=\"973\">218</sup> הנה יובן מ\"ש לעשות לתקן כו' מה שישראל עושין את השבת ע\"י התיקון <span data-k=\"pg\">784</span> ּ בוי\"ו ימי החול במעשה המצות כנ\"ל אעפ\"י ששבת כבר מיקדשא וקיימא מוי\"ו ימ\"ב הראשוני' כו'. דהנה מבואר למעלה בשרש השבת שהוא בבחי' החכ' שנק' קדש מלה בגרמי' דוקא, והוא ע\"י בחי' שביתה דחכמה דמע\"ב כשעלה בבחי' אין דכתר כמ\"ש והחכ' מאין ממש כו' (והוא בחי' ח\"ס) שזהו בחי' ח\"ע שנק' ראש [בחי'] דכר כנ\"ל. ולכך הדיבור של חול אסור בשבת כמ\"ש ודבר דבר [לפי] שח\"ת [חכ' ש]בי' מאמרו' דדבור העליון עולה בליל שבת למעלה בח\"ע שלמעלה מגילוי החכ' מאין ליש, ששם אמר סייג לחכמה שתיקה<sup data-n=\"974\">219</sup> דוקא שהשתיקה מורה על עלי' החכמה שבכלי המוח למעלה לקבל ממקור כח השכל<sup data-n=\"975\">220</sup> המשכיל כל שכל כו' ע\"כ לא יכול לדבר גם בדבר חכמה דאיידי דטריד למבלע<sup data-n=\"976\">221</sup> כו', והוא סייג לחכמה הגלוי' להיות מקור להתחדשו' החכ' מאין ליש כמ\"ש במ\"א דכל או\"ח גורם חידוש ממקור שעולה לשם<sup data-n=\"977\">222</sup> והן חכ' חדשה לוי\"ו ימי החול שאחר השבת כו', [ו]כל זה מפני שהשבת שרשו בפנימי' דח\"ע שנק' קדש העליון כמ\"ש ויקדש אותו כו'. אך הנה עכ\"ז יש יתרון מעלה במצות מעשיות שישראל עושין בחול יותר משרש השבת עד שמחמת[ם] דוקא [יעשו] ליום השבת כו', והוא מפני שיש במצות מבחי' הפנימי' התענוג העליון שברצה\"ע שנק' אשר שהוא מקור לראש דפנימי' ח\"ע הנ\"ל וממשיכים אותו בח\"ע ע\"י המצות ואז נק' ח\"ע בשבת בשם קדש העליון (במעלה יתירה מעצם קדושתו). וראי' לזה מן העד\"ן שזהו ע\"י בחי' המשכת פנימי' הענג העליון בחכ'<sup data-n=\"978\">223</sup> הנ\"ל אזי גם החכ' נק' עדן<sup data-n=\"979\">224</sup> וכמו ונהר יוצא מעדן<sup data-n=\"980\">225</sup> [שפי' עדן] זהו",[["970","215","<b>גבורות דע\"י שמלובש בח\"ס</b>: ראה ע\"ח (שער א\"א) שי\"ג, פ\"ו-ז."],["971","216","<b>אהי' אשר אהי'</b>: שמות ג, יד."],["972","217","<b>שסוף מעשה עלה במח' תחלה</b>: ע\"פ פיוט לכה דודי."],["973","218","<b>ומעתה</b>: ב: נרשם כאן פי\"ג. ראה לעיל הערה 201."],["974","219","<b>סייג לחכמה שתיקה</b>: אבות פ\"ג, מי\"ג. ראה גם לעיל פ' שמות מז, ג. לקמן פ' תצוה שמז, ג. פקודי תנ, ג."],["975","220","<b>השכל</b>: בד: ליתא."],["976","221","<b>דאיידי דטריד למבלע</b>: ראה חולין קח, ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצה. תו\"ח נח סג, ג הערה 44."],["977","222","<b>דכל או\"ח גורם חידוש. . לשם</b>: ראה גם לעיל פ' בשלח ריט, א."],["978","223","<b>בחכ'</b>: בד: בח\"ע."],["979","224","<b>החכ' נק' עדן</b>: נסמן לעיל פ' בשלח קמא, ב."],["980","225","<b>ונהר יוצא מעדן</b>: בראשית ב, י."]]],[2300550455,"בחי' כלי קיבול לאור התענוג העליון והוא חכמה בראש הנ\"ל שהוא בחי' מקבל מעצם התענוג הפשוט (וכמשל הנ\"ל בכח המשכיל שמקבל כח ועוז<sup data-n=\"981\">226</sup> ואור מעצם כח התענוג שבנפש כו'), ע\"כ נק' גם החכמה עדן לפי שמקבל מעונג העליון וממשיך התענוג שמקבל בנהר זה שיוצא מעדן העליון (והוא התענוג המורגש גם בהשגה והבנה דבחי' בינה שנק' הסבר כו' כנשמות שנהנין ומרגישים בתענוג מורגש בהשגתם כו') ונהר זה יוצא מעדן להשקות את הגן<sup data-n=\"982\">227</sup> לנשמות שבגן בכל שבת דוקא כמ\"ש וקראת לשבת ענג כו'. ומטעם זה גזרו אומר דיפה שעה אחת<sup data-n=\"983\">228</sup> בתשובה ומע\"ט בעוה\"ז [דוקא] מכל חיי העוה\"ב אע\"פ שעוה\"ב הוא שכר המצות, כי העוה\"ב הוא בחי' עדן שאינו אלא פנימי' החכ' שמקבל מעונג העצמי שזהו רק הארה בעלמא מה שיוכלו הנשמות ליהנות מעדן העליון כמ\"ש בעדן עין לא ראתה<sup data-n=\"984\">229</sup> כו' ויש ב' מיני עדן<sup data-n=\"985\">230</sup> א' עדן העליון בח\"ע ועדן התחתון בח\"ת, וז\"ש היושבת בגנים<sup data-n=\"986\">231</sup> כו' וע\"כ<sup data-n=\"987\">232</sup> א' ונחל עדניך תשקם<sup data-n=\"988\">233</sup> כו'. אבל ע\"י מעשה המצות ותשובה שיש בזה מפנימי' ועצמות התענוג כמו שהוא למעלה [ממש] טרם שמאיר בח\"ע כו' שלמעלה הוא הרבה מעונג זה הפרטי שנמשך בח\"ע הנק' עדן שאינו רק חלק א' מצומצם והארה בעלמא שנמשך משעשועי המלך בעצמו<sup data-n=\"989\">234</sup> כו' וכמ\"ש ואהי' אצלו שעשועים<sup data-n=\"990\">235</sup> כו' וכן אמר [ואני] תורתך שעשעתי<sup data-n=\"991\">236</sup> שנמשך בתורה מקצת דמקצת מבחי' השעשועי' העצמי' כו' וד\"ל. וא\"כ הרי <span data-k=\"pg\">שצב</span> ּ יובן מזה ג\"כ דמעשה המצות בחול דוקא מפני שממשיכים לבחי' עונג העליון<sup data-n=\"992\">237</sup> העצמי ממש שנק' אשר כנ\"ל הרי ממנו דוקא יבא בחי' המשכות עונג בפרט גם לבחי' ח\"ע שנק' קדש דשבת שהוא עיקר בחי' השבת, וזהו שאמר לעשות לתקן דוקא שע\"י התיקון דמעשה המצות בחול הוא שעושים וממשיכים לעונג העליון העצמי שיומשך גם בעונג דח\"ע שהוא קדושת השבת וכמ\"ש וקראת לשבת עונג מחדש שלמעלה הרבה מקדושה שנתקדש מכבר כו' וד\"ל.\n[ז<sup data-n=\"993\">238</sup> ] וזהו זכור את יום השבת לקדשו כו', פי' זכור עם י\"ה עולה רמ\"ח מ\"ע שע\"י רמ\"ח מ\"ע שישראל עושין בחול עי\"ז יזכרו [לקדש] את יום השבת ואע\"ג דקדושת שבת כבר מיקדשא וקיימא מוי\"ו ימ\"ב כמ\"ש ויקדש אותו וקדושה זו לא תליא בישראל כלל כנ\"ל, [מ\"מ] ע\"י המצות שישראל עושין בחול",[["981","226","<b>ועוז</b>: בד: ליתא."],["982","227","<b>את הגן</b>: שם: ליתא."],["983","228","<b>דיפה שעה אחת</b>: אבות פ\"ד, מי\"ז [ושם: יפה — ראה גם לעיל פ' שמות ט, א. וש\"נ]."],["984","229","<b>בעדן עין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["985","230","<b>ב' מיני עדן</b>: ראה גם מאמרי אדה\"ז תקס\"ט כאן (ע' לח)."],["986","231","<b>היושבת בגנים</b>: שה\"ש ח, יג."],["987","232","<b>וע\"כ</b>: בד: וע\"ז."],["988","233","<b>ונחל עדניך תשקם</b>: תהלים לו, ט."],["989","234","<b>משעשועי המלך בעצמו</b>: נסמן לקמן פ' תרומה שיח, ב."],["990","235","<b>ואהי' אצלו שעשועים</b>: משלי ח, ל [בדילוג]."],["991","236","<b>[ואני] תורתך שעשעתי</b>: תהלים קיט, ע [ושם אני וכ\"ה בב — ראה מאמרי אדה\"א שמות ח\"א ע' קנה. תו\"ח נח סב, ג. תולדות קנט, ד]."],["992","237","<b>העליון</b>: בד: ליתא."],["993","238","<b>ז</b>: ב: נרשם כאן פי\"ד. ראה לעיל הערה 218."]]],[2300550470,"שממשיכים לבחי' פנימי' ועצמות התענוג העליון כמו שהוא עי\"ז מקדשי' לשבת בקדושת עונג העליון העצמי כמ\"ש וקראת לשבת ענג העצמי (שנק' עתיקא קדישא או עתיקא סתימא'<sup data-n=\"994\">239</sup> כו'), ומ\"ש ויקדש אותו היינו ע\"י<sup data-n=\"995\">240</sup> רק בחי' הארת העונג הפרטי שבא ונמשך לבחי' הח\"ע שנק' עדן כנ\"ל וד\"ל. ובזה<sup data-n=\"996\">241</sup> יתורץ הקושיא הנ\"ל איך יתכן בזה שיצוה כאן זכור כו' מאחר שקדושת שבת כבר מיקדשא בקדש דחכמה בבחי' אין<sup data-n=\"997\">242</sup> כו' וד\"ל. אך הנה עדיין יש להבין ענין זכור ושמור בדבור א' נאמרו איך יכול להיות התכללות דו\"ה עם זכרי דמ\"ע עם י\"ה בשמור דל\"ת כו' וההפרש בין זכור לזכרי כנ\"ל.\n<b>הנה</b> יש להקדים עוד ענין אחד בשרש המנוחה דשבת כמ\"ש ששת ימים תעבוד ועשית<sup data-n=\"998\">243</sup> כו', פי' תעבוד עבודה זו הוא ענין תיקון בדבר מה לתקן ולעשות כלי כמו עורות עבודים<sup data-n=\"999\">244</sup> כו'. והענין הוא כידוע דעיקר התיקון בימות החול הוא בבירורים דק\"נ במצות מעשיות הנעשים בדברים גשמי' שנעשה תיקון כמו עיבוד העורות להיות בחי' כלי לעלות למעלה ולשכון בזה קדושה העליונה כמ\"ש במ\"א בענין עובד אלקים<sup data-n=\"1000\">245</sup> שעובד ומתקן לבחי' הכלים<sup data-n=\"1001\">246</sup> כו' הוא הטבע<sup data-n=\"1002\">247</sup> כמו שונה פרקו ק\"א פעמים<sup data-n=\"1003\">248</sup> יותר מכפי טבעו שהוא לאכפייא לסט\"א ולאהפכא חשוכא כו'. והוא ענין תפלת החול בכלל שנק' עבודה שבלב<sup data-n=\"1004\">249</sup> במקום קרבן<sup data-n=\"1005\">250</sup> שנק' עבודה ע\"ג המזבח כידוע, והענין הוא דכמו העלא[ה ד]קרבן [בהמה] ע\"ג המזבח הוא בהקרבת חלב ודם כו' שנעשה רק<sup data-n=\"1006\">251</sup> לריח ניחוח כו', כך בתפלה שנושא את נפשו הבהמי' ומקריבה לפני ה' כשזובח יצרו לבטל כל רצון זר שהי' מקושר שם רק לה' לבדו בהתפעלות האהבה דכל לבבך כו', א\"כ ה\"ז העלאה ובירור מכל אשר נפל בק\"נ בכל אשר נמשך נפשו הבהמי' גם ביגיעתו בעסקו במו\"מ בהתקשרות הרצון ביותר יעלה הכל אל ה' בעבודה שבלב בק\"ש ותפלה ע\"י התגברות התפעלות האהבה שבלב לה' אחד לבדו כו', ונק' העלאה זו בשם קרבן שהוא הבירור מכל אשר נפל בק\"נ ע\"י האדם גם מה שאכל לתיאבון יהופך בחי' העלאה למעלה כהקרבת חלב ודם בבהמה גשמי'. ולכך נק' התפלה בשם עבודה כמ\"ש בזהר דלית פולחנא כפולחנא דרחימותא<sup data-n=\"1007\">252</sup> <span data-k=\"pg\">786</span> ּ כו' שהתפעלות האהבה האלקי' הרוחני' שבלב שנק' פולחנא לפי שמתקן דבר שנפל בק\"נ להעלותו למעלה כו' וכל בחי' תיקון בדבר המקולקל כו' נק' עבודה כו'",[["994","239","<b>עתיקא קדישא או עתיקא סתימא'</b>: ראה זהר בשלח נב, ב. סג, ב. שה\"א סא, ב ובהערה 29."],["995","240","<b>ע\"י</b>: בד: ליתא."],["996","241","<b>ובזה</b>: ב: נרשם כאן פט\"ו. ראה לעיל הערה 238."],["997","242","<b>אין</b>: ב: עדן."],["998","243","<b>ששת ימים תעבוד ועשית</b>: יתרו כ, ט. ואתחנן ה, יג."],["999","244","<b>עורות עבודים</b>: ראה שבת מט, ב. מאמרי אדה\"ז תקס\"ט כאן (ע' לח) ובהנסמן במ\"מ לשם. מאמרי אדה\"א ויקרא ח\"ב ע' תתלח. וש\"נ. שה\"א לח, ב ובהערה 8."],["1000","245","<b>עובד אלקים</b>: ראה מאמרי אדה\"ז תקס\"ד ע' לח. אתהלך לאזניא ס\"ע קפו ואילך. ש\"א יט, א (ספמ\"ה) ורע\"ב."],["1001","246","<b>הכלים</b>: בד: אלקי'."],["1002","247","<b>אלקי'. . הטבע</b>: נסמן לקמן רעא, ג."],["1003","248","<b>שונה פרקו ק\"א פעמים</b>: ראה חגיגה ט, ב. תניא פט\"ו ובמ\"מ הגהות והע\"ק לשם."],["1004","249","<b>תפלת. . עבודה שבלב</b>: ראה תענית ב, א. לעיל פ' בשלח קסב, א הערה 13."],["1005","250","<b>תפלת. . במקום קרבן</b>: ראה ברכות כו, א-ב. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג. וש\"נ. לקמן פ' תרומה שו, א. וש\"נ."],["1006","251","<b>רק</b>: בד: ליתא."],["1007","252","<b>דלית פולחנא כפולחנא דרחימותא</b>: ראה זהר ואתחנן רסז, א. בשלח נה, ב. לקו\"ת שלח מב, ג."]]],[2300550485,"וד\"ל. וזהו ששת ימים תעבוד כו', פי' וי\"ו ימי החול תעבוד בעבודה שבלב בתפילה להעלות הכל מלמטה למעלה מכל אשר נפל בק\"נ בדברים גשמיי' ובמצות גשמיי'<sup data-n=\"1008\">253</sup> וכל תפלות החול מעלין הכל בהעלאה ובירור ועולין כולם ונכללים בשבת, וזהו זכור עם י\"ה [גימ'] רמ\"ח מ\"ע שהוא כללות העבודה דוי\"ו ימי החול שיעלו למעלה ליכלל בי\"ה להיות מזה תוס' קדושה העליונה בקדושת השבת שכבר קדוש מוי\"ב כנ\"ל וד\"ל. אך הנה כל ההעלאה גורם ההמשכה מלמעלה למטה וגם כאן כל בחי' העלאה דעבודה וי\"ו ימי החול בתפלה ומצות גורם בחי' הירידה וההמשכה בשבת והיינו מה שנמשך פנימי' התענוג העליון ברמ\"ח מ\"ע בחול הוא שמתגלה בשבת והוא זכרי עם ו\"ה כו'.\n[ח<sup data-n=\"1009\">254</sup> ] וביאור הענין הנה ידוע דבמארז\"ל במ\"ש ועתה ישראל מה<sup data-n=\"1010\">255</sup> כו' א\"ת מה אלא מאה<sup data-n=\"1011\">256</sup> והן מאה ברכות שחייב אדם לברך בכל יום<sup data-n=\"1012\">257</sup>, והענין הוא כידוע בפי' ברכה דאיהו ברוך ואיהי ברכה<sup data-n=\"1013\">258</sup> שזהו בחי' ההמשכה והשפעה מבחי' סוכ\"ע לבחי' ממכ\"ע<sup data-n=\"1014\">259</sup> שזהו הוי' אלקים<sup data-n=\"1015\">260</sup> שחייב אדם להמשיך בכל יום במאה ברכות שמברך כו', והוא בחי' הגילוי מן ההעלם משם הוי' דאצי' לאלקים בצרופי אותיות שנמשך לבי\"ע. וזהו א\"ת מה אלא מאה<sup data-n=\"1016\">261</sup> שזהו בחי' המל' שמוסתר בבי\"ע אלא מאה שהן ע\"ס דאצי' שכאו\"א כלול מיו\"ד<sup data-n=\"1017\">262</sup> שעולה מאה, [ו]כידוע דבחי' המל' נק' אחת<sup data-n=\"1018\">263</sup> לגבי מספר י\"ס דז\"א שכלולים כאו\"א מיו\"ד שהן מאה ברכות שנמשך מע\"ס דכתר<sup data-n=\"1019\">264</sup> שנמצא זהו רק חלק א' ממאה ונק' תרומות מעשר שהוא מעשר מן המעשר<sup data-n=\"1020\">265</sup> כידוע (כי בנין המל' נעשה מבחי' המל' דכל ספירה<sup data-n=\"1021\">266</sup> דז\"א דהיינו ממל' דחסד דז\"א [נ]בנה חסד שבמל' וכן ממל' דגבורה דז\"א נבנה גבורה שבמל' וכה\"ג בכל הע\"ס דמל' בכל בנין המל' כמ\"ש בע\"ח, ולפ\"ז הרי כל הע\"ס דמל' אינו רק חלק העשירות דז\"א וכמ\"ש בזהר דמל' עשיראה דכולהו<sup data-n=\"1022\">267</sup> כו'. וכמו\"כ מבחי' המל' לבי\"ע לא נמשך רק מבחי' המל' דכל ספי' שבמל' כמו ממל' דחסד דמל' ומל' דגבורה דמל' וכה\"ג, ובכלל נק' מל' שבמל' לפי שאין ההמשכה מבחי' המל' בבי\"ע רק מן חלק העשירי שבה ונמצא זה החלק הנמשך ובא בבי\"ע נק' מעשר מן המעשר לגבי מאה ברכות דז\"א כו', לפי שבחי' המל' נק' מעשר וממה שנמשך ממל' בבי\"ע נק' מעשר מן המעשר שזהו חלק א'",[["1008","253","<b>גשמיי'</b>: בד: מעשיות."],["1009","254","<b>ח</b>: ב: נרשם כאן פט\"ז. ראה לעיל הערה 241."],["1010","255","<b>ועתה ישראל מה</b>: עקב י, יב."],["1011","256","<b>א\"ת מה אלא מאה</b>: ראה רי\"ף ורא\"ש ספ\"ט דברכות. מאמרי אדה\"א דברים ח\"א ע' קכז. וש\"נ."],["1012","257","<b>מאה ברכות שחייב אדם לברך בכל יום</b>: מנחות מג, ב."],["1013","258","<b>דאיהו ברוך ואיהי ברכה</b>: זהר תרומה קסב, א. (רע\"מ) ואתחנן רסד, ב."],["1014","259","<b>סוכ\"ע. . ממכ\"ע</b>: זהר (רע\"מ) פינחס רכה, א."],["1015","260","<b>סוכ\"ע לבחי' ממכ\"ע. . הוי' אלקים</b>: [בד: אלקינו]: ראה גם לעיל פ' וארא עג, ב. וש\"נ."],["1016","261","<b>אלא מאה</b>: בד: ליתא."],["1017","262","<b>ע\"ס. . שכאו\"א כלול מיו\"ד</b>: ראה ע\"ח (שער פרקי הצלם) שכ\"ד, פ\"א."],["1018","263","<b>המל' נק' אחת</b>: במאמרי אדה\"ז תקס\"ט כאן (ע' לט): כמ\"ש [שה\"ש ו, ט] אחת היא יונתי."],["1019","264","<b>מאה ברכות. . מע\"ס דכתר</b>: ראה גם לעיל פ' שמות מח, ד. וש\"נ."],["1020","265","<b>תרומות מעשר. . מעשר מן המעשר</b>: קרח יח, כו."],["1021","266","<b>בנין המל'. . מבחי' המל' דכל ספירה</b>: ראה ע\"ח (שער מיעוט הירח) של\"ו, פ\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תשצה. וש\"נ. שעה\"י קמא, ב ובהערה 41."],["1022","267","<b>דמל' עשיראה דכולהו</b>: ראה זהר פינחס רנג, רע\"ב."]]],[2300550500,"ממאה לבד כו' (וכמ\"ש בזהר בפ' תרומה מאי תרומה ארמותא להוי'<sup data-n=\"1023\">268</sup> כו' והיינו תרומה תר\"[ו] מ\"ה<sup data-n=\"1024\">269</sup> לרומם לבחי' המל' שנק' מ\"ה לשם הוי' דז\"א והיינו שלא תקרא מה אלא מאה שהן מאה ברכות דז\"א. ותרומה גדולה שבישראל הוא תרי ממאה<sup data-n=\"1025\">270</sup> כי בחי' כתר שבכתר<sup data-n=\"1026\">271</sup> נמשך חלק א' מחמשים להיות כתר לז\"א שהוא תרי ממאה שערים שהן ה\"ח וה\"ג דבינה שכוללים מאה שערים כמ\"ש ביצחק וימצא מאה שערים<sup data-n=\"1027\">272</sup> והן מאה ברכות דז\"א כנ\"ל, אבל תרומת מעשר אינו אלא א' ממאה כו').\n<b>והנה</b><sup data-n=\"1028\">273</sup> וי\"ו ימי החול הוא בחי' ההעלא' מלמטלמ\"ע מבירורים <span data-k=\"pg\">שצג</span> ּ דנוגה כנ\"ל שנק' תרומות מעשר שעולה הכל בהעלאת מ\"נ בבחי' המל' שנק' מעשר כו' (וזהו<sup data-n=\"1029\">274</sup> זכור עם י\"ה עולה<sup data-n=\"1030\">275</sup> רמ\"ח שעולה בי\"ה וכן שמור בי\"ה והוא יחו\"ת דאתייחדת לתתא כמו לעילא כו'), אבל תכלית הכוונה בהעלאה זאת הוא בשביל המשכה אח\"כ לברך ולהמשיך ק' ברכות דהוי' דז\"א בבי\"ע כנ\"ל בענין א\"ת מה אלא מאה כו' [שזהו זכרי עם ו\"ה גימ' רמ\"ח שהן רמ\"ח אברים דז\"א ונמשכים למטה בבי\"ע בק' ברכות כנ\"ל] (וזכרי עם ו\"ה<sup data-n=\"1031\">276</sup> עולה רנ\"ב והן רנ\"ב אברים דאשה<sup data-n=\"1032\">277</sup> כי נוסף בה ד' אברים צירים ודלתות כו'. וזהו בינה יתירה שבאשה יותר מבאיש מצד דאו\"א תקינו לה כמ\"ש ויבן ה' אלקים את הצלע<sup data-n=\"1033\">278</sup> שזהו י\"ה דחו\"ב עם זכר\"י שהן י\"ס דאבא שבמל', וזהו שא\"ח [תהי'] עט\"ב והוא תושבע\"פ מל' קרינן לה<sup data-n=\"1034\">279</sup> למעלה מזכרי עם ו\"ה שברמ\"ח מ\"ע דז\"א כו') (וההפרש שבין זכור לזכרי הנה ידוע דעיקר שכר<sup data-n=\"1035\">280</sup> השבת הוא בבחי' זכרון ד[אור] אבא, והיינו זכור בוי\"ו להמשיך מוחין דאבא בוי\"ו דז\"א. וזהו זכור את יום השבת לקדשו בבחי' זכרון דאבא כמ\"ש בקידוש ושבת קדשו באהבה וברצון<sup data-n=\"1036\">281</sup> הנחילנו זכרון למע\"ב כו'. אבל זכרי ביו\"ד הוא בו\"ה בקול ודבור בהמשכות [דז\"א] במל' שזכרי הוא בבחי' הזמן דבחי' נוק' כמשמעות הפשוט זה זכרי לדו\"ר ודו\"ר<sup data-n=\"1037\">282</sup> ). וזהו ענין התורה שבא בקול ודיבור בוי\"ו וה\"א שזהו ג\"כ זכרי ביו\"ד דאור החכמה שבא בו\"ה בקול ודבור דתורה דאוריי' מח\"ע נפקת<sup data-n=\"1038\">283</sup> ובא בדבור דוקא ונק' דא\"ח<sup data-n=\"1039\">284</sup> כו' והמצות ג\"כ בבחי' ו\"ה. ונמצא דוי\"ו ימי החול שעושין ישראל מצות ועוסקים בתורה שהוא יחוד די\"ה בו\"ה וגם ע\"י התשובה מרע שהוא בי\"ה עם שמי כו' הרי עי\"ז נעשה יום השבת,",[["1023","268","<b>מאי תרומה ארמותא להוי'</b>: ראה זהר תרומה קמז, א."],["1024","269","<b>תרומה תר\"[ו] מ\"ה</b>: ראה גם מאמרי אדה\"ז תקס\"ט כאן (ע' לט)."],["1025","270","<b>ותרומה. . תרי ממאה</b>: ראה תרומות פ\"ד, מ\"ג. זהר ויקהל ר, א. (רע\"מ) קרח קעט, א. בלק קפח, ב."],["1026","271","<b>כתר שבכתר</b>: ב: חסר. ד: נש\"ב. מאמרי אדה\"ז תקס\"ט כאן (ס\"ע לט) מת\"ת דאימא כתר א' לזו\"נ."],["1027","272","<b>וימצא מאה שערים</b>: תולדות כו, יב [בדילוג]."],["1028","273","<b>והנה</b>: ב: נרשם כאן פי\"ז. ראה לעיל הערה 254."],["1029","274","<b>שנק'. . (וזהו</b>: בד: (שנק'. . וזהו."],["1030","275","<b>עולה</b>: בד: ליתא."],["1031","276","<b>ו\"ה</b>: בד: י\"ה."],["1032","277","<b>רנ\"ב אברים דאשה</b>: בכורות מה, א."],["1033","278","<b>דאו\"א תקינו לה. . ויבן. . הצלע</b>: ראה זהר בראשית מח, ב. מט, א. בראשית ב, כב."],["1034","279","<b>תושבע\"פ מל' קרינן לה</b>: ת\"ז בהקדמה (יז, א)."],["1035","280","<b>שכר</b>: בד: שורש."],["1036","281","<b>באהבה וברצון</b>: שם: ליתא."],["1037","282","<b>זה זכרי לדו\"ר וד\"ור</b>: שמות ג, ט [ושם: וזה]."],["1038","283","<b>דאוריי' מח\"ע נפקת</b>: זהר בשלח סב, א. יתרו פה, א. (רע\"מ) משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["1039","284","<b>דא\"ח</b>: ב: דברי אלקים חיים."]]],[2300550514,"להמשיך בחי' יחוד עליון בקדושת השבת למעלה הרבה מקדושתו שנתקדש מכבר בוי\"ו ימ\"ב הראשונים מטעם הנ\"ל דבתומ\"צ ותשובה יש מפנימי' התענוג העצמי שלמעלה מענג שבחכמה שזהו קדושה דשבת, וע\"כ אמר זכור את יום השבת לקדשו בקדושה יתירה באמצעית העבודה דימות החול דוקא בתומ\"צ ותשובה וד\"ל.\n<b>וגם</b> בזה יתורץ מ\"ש זכור ושמור בד\"א נאמרו דשמור הוא בל\"ת כנ\"ל והוא בבחי' שמי עם י\"ה דשם הוי' ושמירה זו בוי\"ו ימי החול מל\"ת הוא לשמור [לשבת] לקדשו בתוס' קדושה ונכלל בדבור אחד עם זכור שהוא ג\"כ עם י\"ה שהוא גימט' רמ\"ח מ\"ע למהוי אחד באחד<sup data-n=\"1040\">285</sup> דהיינו ב' פעמים י\"ה כמ\"ש יהי' ה' אחד ושמו אחד דגם שמור לנוק' הוא בי\"ה כמו בזכור לדכורא שיהי' יחו\"ת ויחו\"ע שוין כו'<sup data-n=\"1041\">286</sup> ומתורץ כל הקושיות הנ\"ל וד\"ל. (וגם מ\"ש הטעם בדברות האחרונות וזכרת כי עבד היית כו' ע\"כ צוך לעשות את יום השבת כו' וכמ\"ש בקידוש זכרון למע\"ב תחלה כו' זכר ליצ\"מ כו', לפי שע\"י יצ\"מ שנהפך מחשך לאור ומאפילה כו' ע\"כ צוך לעשות ליום השבת להמשיך בו קדושה יתירה מעצם קדושתו בוימ\"ב מטעם הנ\"ל. אבל בדברות הראשונות היו למעלה מעה\"ד כו' שהי' חירות ממה\"מ<sup data-n=\"1042\">287</sup> כו' ע\"כ בירך ה' כו', והציווי דזכור הוא ע\"י רמ\"ח מ\"ע דזכור עם י\"ה עולה רמ\"ח כו' ולא הזכיר יצ\"מ כלל כנ\"ל וד\"ל.",[["1040","285","<b>למהוי אחד באחד</b>: זהר תרומה קלה, סע\"א."],["1041","286","<b>כו'</b>: בד: כנ\"ל."],["1042","287","<b>חירות ממה\"מ</b>: ראה שמו\"ר רפל\"ב. פמ\"א, ז. זהר בראשית לז, ב."]]],[2300550044,"<b>שבת פ' יתרו בעזר\"ה</b>\n<span data-k=\"pg\">788</span> ּ<b>זהר</b> (דס\"ז ע\"ב בתחלת פ' יתרו), ת\"ח ברזא דשמא<sup data-n=\"1043\">1</sup> קדישא<sup data-n=\"1044\">2</sup> איהו מלך וכהן דמשמש תחותי' ברזא דקדושה בין לעילא בין לתתא, אית מלך לעילא דאיהו רזא דקדש הקדשי' ואיהו מלך עילאה ותחותי' אית כהן רזא דאור קדמאה דקא משמש קמי' ודא אקרי כהן גדול לסטרא דימינא. אית מלך לתתא דאיהו כגוונא דההוא מלך עילאה ואיהו מלך על כולא לתתא, ותחותי' אית כהן דמשמש לי' רזא דמיכאל כהנא רבה. דאיהו לימינא, ודאי בסט' דקדושה אית מלך וכהן ודא איהו רזא דמהימנותא שלימתא ע\"כ,",[["1043","1","<b>זהר.. ת\"ח ברזא דשמא קדישא</b>: מאמר זה הוא הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז שנאמר ליל ש\"ק פ' יתרו תקס\"ז במאהליב. הנחה אחרת נדפסה במאמרי אדה\"ז הנחות הר\"פ ע' טז. ועם הגהות וכו' בביאורי הזהר להצ\"צ כרך א ע' רלח. כרך ב ע' תשפג-תשפז. ראה גם המאמר שנדפס לאח\"ז. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["1044","2","<b>ברזא דשמא קדישא</b>: לשון הזהר בשינויים קלים. וראה גם במאמר שנדפס לאח\"ז."]]],[2300550076,"והנה תחלה יש להבין פי' המלות של זה המאמר במ\"ש ברזא דשמא קדישא איהו מלך כו', דהנה סתם שמא קדישא הוא בחי' מל' דא\"ס, וגם ע\"ס דאצי' הנמשכי' ממל' דא\"ס נק' בחי' שם בלבד על היות בחי' מל' דא\"ס ג\"כ רק בחי' שם בלבד מעצמו' הא\"ס, וידוע דבחי' מל' דא\"ס שרש לי\"ס דאצי' ע\"כ נק' גם הי\"ס שמא קדישא. והיינו שאמר ברזא דשמא קדישא דהיינו בחי' מל' דא\"ס שנק' רזא דשמא קדישא איהו מלך וכהן דמשמש תחותי' כו', פי' איהו מלך היינו בחי' בינ\"ה דאצי' שהיא בחי' גילוי האור מאין ליש.\n<b>ומ\"ש</b> בין לעילא בין לתתא היינו בין בעולם האצי' שהוא לעילא ובין בבי\"ע שהוא לתתא אית מלך וכהן, בחי' מלך היינו בחי' המשפיע וכהן הוא המשכת את המלך לגרום את ירידת השפע מן המשפיע עד\"מ המשרת את המלך שמביא כל עבדיו לפניו ואין מלך בלא עם<sup data-n=\"1045\">3</sup> כידוע, וכמ\"ש ברוב עם הדרת מלך<sup data-n=\"1046\">4</sup>, א\"כ ע\"י המשרת הזה נעשה מלך על עם כי המשרת מביא את העם לפניו ואזי נק' מלך עליהם ובלתי הבאתו לא היו העם נמצאים לפני המלך ולא הי' נק' מלך כשיושב לבדו. וכך הוא למעלה בענין ירידת אור השפע מן המאציל באצי' הנה בחי' בינה נק' מלך להיותה מאיר ובא בבחי' גילוי אור וכמ\"ש אלקים חיים ומלך עולם<sup data-n=\"1047\">5</sup> עולם זה הוא עולם הנאצל ומלך של זה העולם הוא בחי' בינה שנק' אלקים חיי\"ם<sup data-n=\"1048\">6</sup> כידוע. ובחי' כהן דמשמש תחותי' היינו בחי' חסד דאצי' דהיינו בחי' אהבה אשר היא בבחי' תענוגי' ונק' אהב\"ה בתענוגי', ולהיות כי בחי' החכ' הוא בבחי' העלם עדיין ואינו מושג כידוע ע\"כ אין העונג נרגש בחכ' אבל בבינה<sup data-n=\"1049\">7</sup> שהוא מושג ע\"כ האהבה שנולדה מההשגה יש בו הארת העונג. וע\"כ יש במדה זו כח ועוז להמשיך גם לב אחרים הנפרדים כענין דוגמת דברים היוצאים מן הלב שפועלים אהבה בלב זולתו כמים הפנים<sup data-n=\"1050\">8</sup> כו', וזהו ענין העלאה מלמטה למעלה שהרי האהבה שנמשכי' בה הנפרדים למעלה הוא בא בדרך העלאה מלמטה למעלה. ואמנם כדי שיהי' אור אהבה זו בהם מלמטה למעלה לזה נמשך כח ועוז להם מלמעלה למטה, והוא בחי' אהבה העליונה של המשפיע אל המקבל וכמ\"ש אהבת עולם אהבתיך<sup data-n=\"1051\">9</sup> ע\"כ משכתי\"ך חסד אהבת עולם היינו חסד זה דמשפיע שיורד מלמעלה למטה כדי להמשיך את המקבל אליו בהתפעלו' אהבה מלמטה למעלה, <span data-k=\"pg\">שצד</span> ּ וזה הי' מדריגת אהרן הכהן שנא' בו בהעלותך את הנרות<sup data-n=\"1052\">10</sup> וכמ\"ש במ\"א שהי' בכחו להעלות כללות נ\"י באהבה מלמטה ע\"י המשכת אהבה שהמשיך בהן מלמעלה",[["1045","3","<b>ואין מלך בלא עם</b>: נסמן לעיל רנו, ד."],["1046","4","<b>ברוב עם הדרת מלך</b>: משלי יד, כח."],["1047","5","<b>אלקים חיים ומלך עולם</b>: ברכת יוצר."],["1048","6","<b>בינה שנק' אלקים חיי\"ם</b>: ראה זהר יתרו סח, ב ובהגהות הרח\"ו שם. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'קסח־ קונטרסים ע' תקמ."],["1049","7","<b>אין העונג נרגש בחכ' אבל בבינה</b>: ראה הנסמן להלן בהערה 16."],["1050","8","<b>כמים הפנים</b>: משלי כז, יט."],["1051","9","<b>אהבת עולם אהבתיך</b>: ירמי' לא, ב [ושם: ואהבת — ראה הנסמן לעיל פ' וארא סב, ג]."],["1052","10","<b>בהעלותך את הנרות</b>: בהעלותך ח, ב. ראה מאמרי אדה\"ז תקס\"ב ח\"א ס\"ע רטז ואילך. מאמרי אדה\"א במדבר ח\"ג ס\"ע תתפג ואילך ובהנסמן בריש המאמר שם."]]],[2300550108,"למטה בימין מקרבת וע\"כ הי' רודף שלום<sup data-n=\"1053\">11</sup> כו'. וכך הוא למעלה בבחי' חסד דז\"א שנק' אהבת עול\"ם כו' שמושך אהבה וחסד בכל פרטי חלקי האורות דאצי' שעי\"ז יוכלו לעלות ולידבק במאציל באהבה מלמטה למעלה, וזהו שנק' כהן דמשמש תחותי' עד\"מ המשרת שמביא כל העם לפני המלך ע\"י שמושכם באהבה כו' ואז יתגלה מלך עליהם ונק' מלך להשפיע כו' ואם לא הכהן הזה לא הי' נק' מלך. וז\"ש והוכן בחס\"ד כסא<sup data-n=\"1054\">12</sup>, פי' כסא המלך היינו שהמלך יורד ומשפיל א\"ע לישב עלי' למלך והוכ\"ן הכס\"א הזה בחס\"ד דוקא דהיינו ע\"י כהן המשרת שמביא את העם כו' להיות נק' מלך על עם כו', ואין מלך בלא כהן ואין כהן בלא מלך משום דאין המלך מתפשט במלוכה רק ע\"י הכהן ואין לכהן עבודה להביא העם רק לפני המלך כו' וע\"כ בין לעילא בין לתתא אית מלך וכהן דמשמש תחותי' משום דהא בהא תליא ושניהם ענין א' הוא וד\"ל.\n<b>וזהו</b> שאמר אית מלך לעילא ברזא דקדש הקדשי', פי' בחי' בינה דאצי' נק' קדש הקדשי\"ם<sup data-n=\"1055\">13</sup> לפי שחו\"ב נק' קדשי\"ם<sup data-n=\"1056\">14</sup> ובחי' כת\"ר נק' קד\"ש הקדש\"י'<sup data-n=\"1057\">15</sup> כידוע, ולהיות שהתגלות העונג העליון דע\"י הוא בבינה<sup data-n=\"1058\">16</sup> דוקא להיות מושג כידוע וכנ\"ל, ע\"כ אמר דמלך לעילא הוא ברזא דקדש הקדשי' ומבחי' בינה דוקא מתפשטת גילוי אור השפע לכל האצי' כידוע. וכהן דמשמש תחותי' רזא דאור קדמאה דאקרי כה\"ג פי' אור האהבה והחסד שנולד ראשון מאור הבינה, ומה שנק' כה\"ג היינו לפי שעולם האצי' כולו מקבל הימנו בחי' המשכת אהבה וחסד כל חד וחד לפום שיעורא דילי'<sup data-n=\"1059\">17</sup> והוא כוללם יחד, וע\"כ נק' כהן גדול לפי שגדולת התפשטו' חסדו מאיר בכל האצי' כולו מראש ועד סוף והוא לסטר ימינא דוקא כי הרי ימין מקרבת<sup data-n=\"1060\">18</sup> וחח\"נ הוא קו הימין<sup data-n=\"1061\">19</sup> כידוע וד\"ל.\n<b>אך</b> הנה כ\"ז בבחי' האצי' דשם אמרו דאיהו וחיוהי וגרמוהי חד<sup data-n=\"1062\">20</sup> הכל בבחי' א\"ס, אבל למטה בבי\"ע שהן עולמות הנפרדים יש מאין בבחי' גבול אית מלך וכהן גם שם. אבל הכהן דשם הוא בבחי' גבול והוא בחי' חסד דבריאה רזא דמיכאל כהנא רבה שהוא המקריב נשמות ע\"ג המזבח<sup data-n=\"1063\">21</sup> כידוע, פי' מזבח היינו",[["1053","11","<b>רודף שלום</b>: אבות פ\"א, מי\"ב."],["1054","12","<b>והוכן בחס\"ד כסא</b>: ישעי' טז, ה."],["1055","13","<b>בינה. . קדש הקדשי\"ם</b>: ראה ביאוה\"ז כאן (ע' תשפד). קהלת יעקב מערכת קדש קדשים השני."],["1056","14","<b>שחו\"ב נק' קדשי\"ם</b>: ראה פרדס (שער ערה\"כ) שכ\"ג, מערכת קדש. רמ\"ז לזהר כאן. לקמן רעג, ד."],["1057","15","<b>כתר נק' קד\"ש הקדש\"י'</b>: ראה גם פרדס שם. מאו\"א מערכת קדש ס\"ז. לקמן שם. אוה\"ת בלק ע' תתקנה."],["1058","16","<b>שהתגלות העונג. . דע\"י הוא בבינה</b>: ראה תו\"ח לך פא, ב ואילך. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' ד. לעיל פ' שמות לג, ד ובהערה 332."],["1059","17","<b>כל חד. . שיעורא דילי'</b>: ראה הקדמת התניא ע\"פ הזהר וירא קג, רע\"ב."],["1060","18","<b>ימין מקרבת</b>: סוטה מז, א."],["1061","19","<b>וחח\"נ הוא קו הימין</b>: ראה זהר (רע\"מ) בהעלותך קנג, ב. פרדס (שער סדר עמידתן) ש\"ו, פ\"א. מאמרי אדה\"א בראשית ע' ריז. וש\"נ."],["1062","20","<b>דאיהו וחיוהי וגרמוהי חד</b>: ראה ת\"ז בהקדמה (ג, ב). ראה גם מאמרי אדה\"ז על מארז\"ל ע' רצב (כמא' אליהו ז\"ל). מאמרי אדה\"א ויקרא ח\"ב ע' תנג בהערה."],["1063","21","<b>דמיכאל. . המקריב נשמות ע\"ג המזבח</b>: ראה גם לעיל ה, א. וש\"נ."]]],[2300550140,"בחי' מל'<sup data-n=\"1064\">22</sup> דאצי' כידוע, והנשמות ומלאכי' שנבראו יש מאין המלאך הזה מקריבן למעלה מן המזבח דהיינו לאשתאבא בגופא דמלכא<sup data-n=\"1065\">24</sup> שהוא בחי' ז\"א. והיינו ע\"י בחי' המשכת אהבה שממשיך בכל הניצוצי' בזאת הוא מעלה אותם לידבק באצי' באהבה כענין הנ\"ל באהבה רבה דאהרן שהי' ממשיך בכנ\"י כו', ונק' מיכאל כהנא רבה זה בשם כהן דמשמש להאי מלך דלתתא כי על ידו יומשך בחי' מלך דלתתא כי אין מלך בלא עם כנ\"ל בביאור כהן ומלך דאצי'. ובחי' מלך דלתתא היינו בחי' מל' דאצי'<sup data-n=\"1066\">23</sup> שמתפשט בבי\"ע להיות מלך על עם נפרד יש מאין כו' והוא ממש כגוונא דההוא מלך עילאה שהוא בחי' בינה דאצי', אלא שבחי' בינ\"ה היא בחי' גילוי להאיר באצי' ובחי' מל' הוא בחי' הגילוי להוות בריא' יש בע\"ג כו'. וכמ\"כ בחי' מיכאל זה דהיינו חסד דבריאה הוא ממש כדוגמת כהן גדול <span data-k=\"pg\">790</span> ּ דאצי' שנק' אור קדמאה כי להביא ולהעלות הנברא לגבי הבורא הוא ענין א' כמו להביא הנאצל לגבי המאציל כו', וגם מיכאל זה לסטר ימינא דוקא וכמ\"ש והוכן בחסד כסא וכסא זה יתפרש על בחי' כסא דמל' דאצי' שנק' כס\"א הכבוד<sup data-n=\"1067\">25</sup> כידוע וד\"ל.\n<b>ומה</b> שאמר ודא איהו רזא דמהימנותא שלימתא כי כל בחי' היחודי' העליוני' בין באורות דאצי' שנק' מהימנותא עילאה ובין בי\"ס דבי\"ע שנק' מהימנותא תתאה הכל נעשה ע\"י בחי' הכהן הזה שנק' מיכאל למטה ואור קדמאה למעלה להיותו בחי' ממוצע לחבר המקבל אל המשפיע, וכמו אהרן כה\"ג שנק' שושבינא דמטרוניתא<sup data-n=\"1068\">26</sup> לחבר הכלה אל החתן שהוא בחי' יחוד דזו\"נ ואין היחוד אלא ע\"י הנשמות שעולין ע\"י כהן זה. ונמצא הכהן הזה עושה בחי' שלימו' העליונה בכל האורות העליוני' דאבי\"ע להיות נק' מהימנותא שלימתא דוקא כידוע דעיקר השלימות הוא ביחודי' דדכר ונוק' דוקא וכמ\"ש במ\"א ע\"פ זכר ונקבה כו'<sup data-n=\"1069\">27</sup> ויקרא שמם אד\"ם ויברך אות\"ם<sup data-n=\"1070\">28</sup> אלקי'<sup data-n=\"1071\">29</sup> כו' לפי שהברכה היא מעצמו' המאציל והיא אינה באה רק כשיש יחוד דדכר ונוק' למטה וד\"ל.\n<b>בסטרא</b> אחרא<sup data-n=\"1072\">30</sup> אית מלך וכהן, מלך דאקרי מלך זקן וכסיל<sup data-n=\"1073\">31</sup> ותחותיה אית כהן דמשמש ואקרי כהן און ודא הוא",[["1064","22","<b>מזבח היינו בחי' מל'</b>: בביאוה\"ז כאן (ע' רמב): כמ\"ש במאו\"א מם סנ\"ד. במאמרי אדה\"ז תקס\"ו ע' רמג: מלכות דאצי'. . מזבח עילא'. . כמ\"ש בזוהר ע\"פ אש תמיד תוקד על המזבח. וראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשכט ובהנסמן במ\"מ לשם. לקמן פ' ויקהל שפז, א. תכ, ג."],["1065","24","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' מה. תו\"ח בראשית מ, ב הערה 25."],["1066","23","<b>מזבח. . מל' דאצי'. . מלך דלתתא. . מל' דאצי'</b>: ראה ביאוה\"ז כאן (ע' רמב. ע' תשפה)."],["1067","25","<b>כסא דמל'. . כס\"א הכבוד</b>: ראה מאו\"א מערכת כסא סכ\"ב."],["1068","26","<b>אהרן. . שושבינא דמטרוניתא</b>: ראה זהר (רע\"מ) ויקרא כ, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קג. שמות ח\"ב ע' שטו וע' שמ. לעיל פ' וארא עב, ג. עז, ב ואילך."],["1069","27","<b>זכר ונקבה כו'</b>: תיבות אלו ניתוספו בין השיטין."],["1070","28","<b>זכר. . ויקרא. . ויברך אות\"ם אלקי'</b>: בראשית ה, ב [ושם: זכר. . ויברך אותם ויקרא את שמם אדם, וכנראה שהוא חיבור שני כתובים — בראשית ה, ב. א, כח]."],["1071","29","<b>זכר. . ויקרא. . ויברך אות\"ם אלקי'</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' שח. מאמרי אדה\"א שמות ח\"ב ס\"ע ת ואילך."],["1072","30","<b>בסטרא אחרא</b>: המשך לשון הזהר יתרו שם בשינויים. וראה גם במאמר שנדפס לאח\"ז."],["1073","31","<b>מלך זקן וכסיל</b>: קהלת ד, יג."]]],[2300550172,"רזא דכתיב ויאמר אפרים אך עשרתי<sup data-n=\"1074\">32</sup> מצאתי און לי בגין דחילא דא שלטא על ההוא עובדא דעבד ירבעם ובדא אצלח, רזא דמלה כד האי מלך וכהן אתכפיין ואתברו כדין כל סטרין אחרנין אתכפיין ואודן לי' לקוב\"ה כדין כתי' ונשגב ה' לבדו<sup data-n=\"1075\">33</sup> כו', ורזא דא ממש עבד קוב\"ה בארעא דתבר מלך זקן וכסיל דא הוא פרעה ומשום דאמר למשה לא ידעתי את הוי'<sup data-n=\"1076\">34</sup> כו' בעא קוב\"ה דיתייקר שמי' כמה דאיהו יקירא לעילא, כיון דאלקי לי' ולעמיה אתא ואודי לקוב\"ה, לבתר אתבר ואתכפייא ההוא כהן און יתרו<sup data-n=\"1077\">35</sup> דמשמש תחותיה ואודי לקוב\"ה ואמר ברוך ה' אשר הציל<sup data-n=\"1078\">36</sup> כו' עתה ידעתי<sup data-n=\"1079\">37</sup> כי גדול ה' מכל האלקי' כו', ע\"כ.\n<b>הנה</b> להבין ענין המאמר בכהן און דיתרו כו' תחלה יש להקדים שרש ענין הע\"ז וענין הקרבנו' לע\"ז וכמבואר בכתובי' הרבה עבודת ההקטרה שהיו מקטירים לבעל ולאשירה וכמו הקרבנות דבלק ובלעם<sup data-n=\"1080\">38</sup> בפר ואיל במזבח כו' וכמ\"ש ויזבחו את זבחיהם לשעירים<sup data-n=\"1081\">39</sup> כו' והיו מקריבים גם פרים וכבשים ועופות כדוגמת הקרבנות דקדושה שהיו מקריבין ע\"ג המזבח בבהמ\"ק. ויובן שרש ענין הקטרת והקרבת הפרים והכבשים לע\"ז בדוגמא שיש בקדושה העליונה בקרבנות ע\"ג המזבח דקדושה מאחר דאת זלע\"ז עשה האלקי'<sup data-n=\"1082\">40</sup> הרי הקליפה נדמה לקדושה כקוף בפני אדם<sup data-n=\"1083\">41</sup> כידוע. והנה בקדושה האלקי' הי' הקרבן מצוה להעלות דם וחיות הבהמה הטהורה ע\"ג המזבח כמו הפר ששרשו למעלה נמשך מבחי' פני שור<sup data-n=\"1084\">42</sup> מהשמאל<sup data-n=\"1085\">43</sup> שבמרכבה העליונה דקדושה שממנו מסתעף ונמשך כל חיות הבהמו' הגשמיי' למטה כידוע, ובהעלות החיות מן הפר הגשמי הנה הוא עולה עד מקור חוצבו בפני שור הזה ורוח אייתי רוח ואמשיך רוח<sup data-n=\"1086\">44</sup> כידוע בהעלות המקבל לשרשו הוא מושך רוח המשפיע אליו להוסיף בו חיות ושפע כו'. וכך ע\"י העלאת <span data-k=\"pg\">שצה</span> ּ חיות הפרים והכבשים מפני שמוסיפין כח ועוז במקור חוצבם שהוא בחי' פני שור הנ\"ל עי\"ז גורמים שיומשך אח\"כ תוס' ברכה ושפע מפני שור למטה, והוא הטעם שהקרבנות נק' מזון למרכבה העליונה, ועד\"ז גם בחי' פני שור הז\"ה נעשה קרבן והעלאה למעלה לגבי מל' דאצי' כו'. וכן עד\"ז יובן בקרבנות העופות שהם מבחי' פני נש\"ר<sup data-n=\"1087\">45</sup> כו', ואר\"י' דאכי\"ל קרבנין<sup data-n=\"1088\">46</sup> היינו מפני שהוא בחי' פני ארי' להימין<sup data-n=\"1089\">47</sup> שבמרכבה המעלה אותם למעלה ע\"כ הוא מוציא מהם החיו\"ת הגשמי ומקשר אותם לגבי מקור חוצבם הראשון שהוא אש דשכינה שע\"ג המזבח כמ\"ש אש תמיד<sup data-n=\"1090\">48</sup> תוקד ע\"ג המזבח ונק' אש של מעלה כו'. וע\"ד הזה אשר",[["1074","32","<b>ויאמר אפרים אך עשרתי</b>: הושע יב, ט."],["1075","33","<b>ונשגב ה' לבדו</b>: ישעי' ב, יא. יז."],["1076","34","<b>לא ידעתי את הוי'</b>: שמות ה, ב."],["1077","35","<b>כהן און יתרו</b>: ראה זהר יתרו סח, א."],["1078","36","<b>ברוך ה' אשר הציל</b>: יתרו יח, י."],["1079","37","<b>עתה ידעתי</b>: יתרו שם, יא."],["1080","38","<b>הקרבנות דבלק ובלעם</b>: בלק כג, א. ב. יד. כט. ל."],["1081","39","<b>ויזבחו את זבחיהם לשעירים</b>: אחרי יז, ז [ושם: ולא יזבחו עוד]."],["1082","40","<b>דאת זלע\"ז עשה האלקי'</b>: נסמן לעיל רנא, ג."],["1083","41","<b>כקוף בפני אדם</b>: ראה זהר תרומה קמח, ב."],["1084","42","<b>הפר ששרשו. . פני שור</b>: נסמן לעיל רסג, ג."],["1085","43","<b>פני שור מהשמאל</b>: יחזקאל א, י."],["1086","44","<b>ורוח אייתי רוח ואמשיך רוח</b>: נסמן לעיל רנא, א."],["1087","45","<b>העופות. . פני נש\"ר</b>: ראה אוה\"ח אחרי יז, יד."],["1088","46","<b>ואר\"י' דאכי\"ל קרבנין</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שה\"א עט, ב הערה 13."],["1089","47","<b>פני ארי' להימין</b>: יחזקאל שם."],["1090","48","<b>אש תמיד</b>: צו ו, ו."]]],[2300550204,"בקדושה האלקי' יובן גם במנגד לקדושה שנדמה כקוף כנ\"ל שנק' אלקי' אחרים מבחי' אחוריי' דמל' דקדושה שעושה ג\"כ ע\"ד הזה והוא השרש של הקטרת והקרבת הקרבנות לע\"ז שנק' אלקי' אחרים, כי כמו שיש בחי' מרכבה בקדושה כך יש בחי' מרכבה טמאה<sup data-n=\"1091\">49</sup> בהיכלות דקליפות והיינו שרש חיות כל בהמות וחיות הטמאות<sup data-n=\"1092\">50</sup> ככלב וחזיר וסוס וכיוצא כידוע ששרשן מג\"ק הטמאות לגמרי.\n<b>ויובן</b> זה ע\"ד הפשוט שהרי אנו רואים מה שיולדו בהמות טמאות מזווג זכר ונקבה טמאים הרי הוא כדוגמא שיולדו בהמות טהורות מזווג זכר ונקבה טהורים, ובהמה נלמד מאדם, שישראל נק' אדם<sup data-n=\"1093\">51</sup> כו' ובפירוש אמרו דג' שותפין יש<sup data-n=\"1094\">52</sup> כו'. והרי עיקר כח המוליד נפש חדשה מזוג זכר ונקבה הוא הקב\"ה דהיינו מאורו' אשר בסט' דקדושה בי\"ס דבי\"ע כו', כי הזכר בפ\"ע אינו מוליד ולא הנוק' בפ\"ע ובמה שמתייחדים יולידו נפש, אין זה אלא מכח האלקי' המתלבש בהם כשמתייחדי' יחד כו', וע\"כ הנפש דוקא נמשך מלמעלה אבל הגופי' נמשכי' מן האב והאם. וכיוצא בזה בנפשות אוה\"ע הגופים נמשכים מן האב והאם והנפש נמשך בהיחוד של זכר ונקבה באוה\"ע מסט' דקליפה אשר באורות דבי\"ע דקליפה כו' שהן ג' קליפו' הטמאות<sup data-n=\"1095\">53</sup> כידוע, וכמו\"כ בבהמות הטמאות שנולד ביחודם נפש החי נמשך ג\"כ מהיכלות דקליפה מבחי' מרכבה הטמאה דשם כו'. והכלל הוא לפי שאת זלעו\"ז ממש עשה האלקי' וכמו שיש ע' נפש בישראל<sup data-n=\"1096\">54</sup> מסט' דקדושה כך יש ע' שרים<sup data-n=\"1097\">55</sup> דקליפה כמ\"ש יצב גבולות עמים<sup data-n=\"1098\">56</sup> למספר בנ\"י, וכל שר מע' השרים יש לו חלק מיוחד בארץ כולל חלקי דצח\"מ שמשפיע להן מרב טובו וחסדו והיינו דוקא כשמקריבין ומקטירין לו זבח ומנחה מבהמה וחי' השייך לו וכפי אופן העלאת חיו' הקרבן שנכלל במקור חוצבו דקליפה כך הוא ממשיך משם שפע חדשה משום דרוח אייתי רוח כו', וע\"ד שנולדי' נפשות ובהמות הטמאו' ביחוד זכר ונקבה טמאי' כנ\"ל וכן בהיפך כאשר ימות נפש הטמאה או בהמה הטמאה הנה תסתלק למקור חוצבה<sup data-n=\"1099\">57</sup> בקליפה כו'. וא\"כ הרי גם ההעלא' דחיות בקרבן של בהמה הטמאה להיותה עולה ונכללת במרכבה הטמא' הרי [בהכרח] שגורמת ירידת אור ושפע חדשה למטה, וכנ\"ל בענין קרבנו' דקדושה, וזהו שרש ענין הקרבנו' לע\"ז שהיו מקריבין לאותו כוכב אשר ידוע שהוא שייך אל אותה ההעלאה שמעלין בקרבן ידוע, וכפי אופן שהיו רוצין לקבל",[["1091","49","<b>מרכבה טמאה</b>: ראה גם תו\"א מג\"א צב, ד. ש\"א פה, ב."],["1092","50","<b>שרש חיות כל בהמות וחיות הטמאות</b>: ראה ע\"ח (שער ק\"נ) שמ\"ט, פ\"ג. תניא ספ\"ו."],["1093","51","<b>שישראל נק' אדם</b>: נסמן לעיל רסב, א הערה 285."],["1094","52","<b>דג' שותפין יש</b>: נדה לא, א."],["1095","53","<b>בנפשות אוה\"ע. . ג' קליפו' הטמאות</b>: ראה ע\"ח (שם) שמ\"ט, פ\"ג. תניא פ\"א."],["1096","54","<b>ע' נפש בישראל</b>: ויגש מו, כז."],["1097","55","<b>ע' שרים</b>: נסמן לעיל רנד, ב."],["1098","56","<b>יצב גבולות עמים</b>: ראה גם שע\"ת עד, א ובהערה 3."],["1099","57","<b>ימות נפש. . תסתלק למקור חוצבה</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' קפד. אג\"ק כ\"ק אדמו\"ר מהר\"ש ע' צב ואילך."]]],[2300550236,"מכוכבי' ומזלו' דקליפה כך היו מקריבין קרבן כדי לעורר אותו השרש והמקור בקליפ' השייך לאותה ההשפעה דוקא ולא היו מקריבין אלא דוקא בדוגמא לאותו הכוכב כי רוח אייתי רוח כו'. וזהו שאמרו עובדי הבעל<sup data-n=\"1100\">58</sup> ומאז חדלנו לקטר<sup data-n=\"1101\">59</sup> למלכ\"ת השמי\"ם <span data-k=\"pg\">792</span> ּ חסרנו כל כו' לפי שהקטרתם הי' הכל בחי' העלאה למעלה בכחו' דקליפה ליתן להן כח ועוז עי\"ז כנ\"ל במרכבה דקדושה ועי\"ז היו ממשיכי' מהם רב טוב ושפע גשמי' בחלקי דצח\"מ והיו יודעין להקריב לכל שר ושר פרטי כפי מדרגתו למעלה כו'. אמנם בדרך כלל כל הע' שרים הן כלולי' בז' מדות<sup data-n=\"1102\">60</sup> בלבד והן הכנעני והחתי<sup data-n=\"1103\">61</sup> כו' רק שנחלקי' כאו\"א לי' כידוע ואח\"כ מתחלקי' עוד לרבבות מדרגות עד שיש ריבוא רבבות התחלקות בכמה מיני ע\"ז כמו שאמרו ז\"ל באברהם שהי' לומר ד' מאה פרקי' במס' דע\"ז<sup data-n=\"1104\">62</sup> כו' וד\"ל.\n<b>והנה</b> יתרו הי' כומר לע\"ז הגדול מכל הכומרים דהיינו שהי' כולל כל הכומרים לפי שהי' יודע לעבוד העלאות הקרבנות לכל ריבוי התחלקות המדריגות דקליפ' לכאו\"א ההעלאה השייך לו דוקא, ודרך כלל הי' יודע להעלות קרבן לכל הע' שרים דקליפה לכאו\"א כפי הראוי לו בכדי להמשיך ממנו אור ושפע חדשה כו' לפי שפרעה הי' מולך בכל הארץ<sup data-n=\"1105\">63</sup> כידוע והי' כולל ע' שרים כולם ע\"כ יתרו שהי' לו לכהן עובד ע\"ז הי' כולל כל הקרבת ע\"ז ששייך לכללות הע' שרים כו', וכאשר הי' יתרו מקריב ומעלה מכל מיני העלאות הכוללי' כל הע' שרים הרי ודאי שהי' יכול להמשיך מכולם יחד כו'. והנה בסט' דקדושה הוא ענין מיכאל כהנא רבא הנ\"ל שבכחו להעלות כל הניצוצי' דקדושה ומקריבין ע\"ג המזבח דקדושה כנ\"ל שהוא ממשיך עי\"ז להיות מלך על עם מבחי' מל' דאצי' דקדושה כמבואר למעלה, לפי שהוא היודע איך להעלות ההעלאו' ולהמשיך ההמשכות ובכלל ממשיך הוא בחי' מל' דקדושה וכנ\"ל באריכות ממשל המשרת את המלך כו'. וכך בסט' דקליפה הרי יתרו בהקרבת והעלאות קרבנותיו בכללות לכללות הע' שרים דקליפה הי' ממשיך עי\"ז בחי' מל' דקליפה שנק' מלך זקן וכסיל כו', כי אין מלך בלא כהן וכנ\"ל במלך וכהן דקדושה כו'. וע\"כ נק' יתרו כהן און והוא כדוגמא ממש דכהן דקדושה שנק' מיכאל כהנא רבא הנ\"ל, וזהו כללות ענין המאמר במ\"ש בתחלת המאמר דבסט\"א אית מלך וכהן כו' וד\"ל.",[["1100","58","<b>עובדי הבעל</b>: וכ\"ה לקמן ערב א. ובמאמרי אדה\"ז הנחות הר\"פ כאן (ר\"ע יז): הנשים המקטרות."],["1101","59","<b>ומאז חדלנו לקטר</b>: ירמי' מד, יח [ושם: ומן אז. בדילוג — ראה לעיל פ' בשלח קסה, ב. וש\"נ]."],["1102","60","<b>הע' שרים. . בז' מדות</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' עב. תו\"ח נח סד, ד ובהערה 50. מאמרי אדה\"א דברים ח\"ג ע' תשמט. ח\"ד ע' א'תפט."],["1103","61","<b>בז' מדות. . הכנעני והחתי</b>: ראה גם לקמן פ' תצוה שסה, א. מאמרי אדה\"א קונטרסים ע' רמא. וש\"נ. ש\"א סא, ב ובהערה 20."],["1104","62","<b>ד' מאה פרקי' במס' דע\"ז</b>: ע\"ז יד, ב. זח\"ב (תוספות) ערה, סע\"ב. ז\"ח (ס\"ת) יתרו לז, ג."],["1105","63","<b>שפרעה הי' מולך בכל הארץ</b>: מכילתא בשלח יד, ה. זהר שמות ו, רע\"ב."]]],[2300550267,"<b>ולהבין</b> ביאור פרטי דברי המאמר והטעם שנק' מלך זקן וכסיל דוקא, הנה יש להבין תחלה שרש ענין פרע\"ה ומה שאמר לא ידעתי את הוי'. וגם להבין שרש ענין הי' מכות לאיזה טעם היו. דהנה פי' פרע\"ה הוא ענין עור\"ף<sup data-n=\"1106\">64</sup> כידוע, ושרש הענין הוא כי יש ג' מוחין בגלגלתא הנקראי' חב\"ד כידוע, והנה מוח החכ' ומוח הבינה עומדי' בגלגלתא שניהם זה אצל זה ומוח הדעת עומד למולם ונגדם לצד העורף שבראש כמבואר זה גם בספרי הטבע<sup data-n=\"1107\">65</sup>, והעורף הוא המכסה למוח הדעת ומלבישו ומעלימו ונמצא מוח הדעת הוא עומד בין ב' מוחין חו\"ב ובין העורף כו', וידוע שהעורף הוא הנק' אחוריי' כי הוא עומד מול הפנים שבראש ממש כמ\"ש כי פנו אלי עורף ולא פנים<sup data-n=\"1108\">66</sup> כו' וכידוע. והנה ידוע בענין מקור שרש כל הקליפו' שהן מז' מלכין קדמאין דתהו שמתו כמ\"ש ואלה המלכים<sup data-n=\"1109\">67</sup> אשר מלכו בארץ אדו\"ם לפני מלוך מלך לבנ\"י כו', והרי ידוע דמלך הראשון שהוא בלע בן בעור הוא בחי' <span data-k=\"pg\">שצו</span> ּ הדעת<sup data-n=\"1110\">68</sup> שהוא מקור המדות<sup data-n=\"1111\">69</sup> ולהיותו מתפשט בקליפה נק' בלע לפי שמכסה ומסתיר בחי' מוח הדעת דקדושה והוא בחי' העורף המכסה מוח הדעת כנ\"ל, ובלע מלשון ולא יבאו לראות כבלע את הקדש<sup data-n=\"1112\">70</sup> כו' מפני שמבליע ומעלים את אור הדעת דקדושה ונעשה שרש המדות הרעות דקליפה למטה כו'. כי הנה השכחה הוא היסח הדעת ובהיסח הדעת מן המדות ממילא אין למדות חיות ואור מן השכל ונופלים בגסות והגשמה. וזהו השמר לך פן תשכח<sup data-n=\"1113\">71</sup> את ה' כו' מפני שהשכח\"ה שרש לכל הרע שבז' מדות לפי שהדעת הוא המתפשט במדות להחיותם כידוע ובהיסח הדעת מהם ממילא יפול הנופל כו', וזהו ישראל לא יד\"ע כו' הוי גוי חוטא<sup data-n=\"1114\">72</sup> כו' וכמ\"ש במ\"א. וזהו הי' שרש פרעה למעלה בבחי' עורף דקליפה שנק' אלקי' אחרים לפי שעומד באחוריי' דמוח הדעת דקדושה ומעלימו ומסתירו כנ\"ל, וע\"כ אמר פרעה למשה לא ידעתי את הוי' לפי ששרשו הי' בבחי' מלך הראשון שנק' בלע הוא המבליע ומכסה מוח הדעת דקדושה ע\"כ אין לו בחי' הדעת בהוי', כי עיקר שם הוי' שבמדות דקדושה הוא ע\"י מוח הדעת המתפשט בהן וע\"כ לא השיג והכיר רק בשם אלק\"י' כמשי\"ת בסמוך.\n<b>והנה</b> ידוע דעיקר השבירה לא הי' רק במדות<sup data-n=\"1115\">73</sup> בלבד והן ז' המלכים שמתו שהוא בחי' ז\"ת בלבד, אבל בבחי' ג\"ר לא הי' בחי' שבירה<sup data-n=\"1116\">*74</sup> כלל כי חכמה ובינה לא נשברו רק בחי'",[["1106","64","<b>פרע\"ה. . עור\"ף</b>: ראה לקו\"ת להאריז\"ל ר\"פ שמות. הנסמן לעיל יט, ב."],["1107","65","<b>ג' מוחין. . בספרי הטבע</b>: במאמרי אדה\"ז הנחות הר\"פ כאן (ע' יז) מציין לס' שבילי אמונה נתיב ד שביל א. ראה גם לעיל פ' שמות כג, ד. וש\"נ."],["1108","66","<b>כי פנו אלי עורף ולא פנים</b>: ירמי' ב, כז."],["1109","67","<b>מז' מלכין קדמאין. . ואלה המלכים</b>: וישלח לו, לא. ראה זהר (אד\"ר) נשא קכח, א. קלה, א. תו\"ח תולדות קנג, ב הערה 39."],["1110","68","<b>בלע בן בעור. . הדעת</b>: וישלח לו, לב. ראה גם לעיל מב, ב. וש\"נ."],["1111","69","<b>הדעת שהוא מקור המדות</b>: ראה ע\"ח (שער הנסירה) שכ\"ט, פ\"ז בהגה. תניא ספ\"ג. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשלט ואילך. לקמן פ' ויקהל תיא, ג."],["1112","70","<b>ובלע. . ולא יבאו לראות כבלע את הקדש</b>: במדבר ד, כ. ראה גם לעיל מב, ב. וש\"נ."],["1113","71","<b>השמר לך פן תשכח</b>: ואתחנן ו, יב. עקב ח, יא."],["1114","72","<b>ישראל לא יד\"ע. . הוי גוי חוטא</b>: ישעי' א, ג. ד. ראה גם שע\"ת פא, ב ואילך. מאמרי אדה\"א הנחות תקע\"ז ע' רנו. וש\"נ."],["1115","73","<b>השבירה. . במדות</b>: ראה ע\"ח (שער דרושי הנקודות) ש\"ח, פ\"ב. מאמרי אדה\"א דברים ח\"א ע' ח. וש\"נ."],["1116","*74","<b>ג\"ר לא הי' בחי' שבירה</b>: ראה גם לקמן פ' תצוה שסג, א. ויקהל תכא, ג."]]],[2300550297,"אחוריי' שבהם נפלו<sup data-n=\"1117\">74</sup> כו', ואמנם במדות הי' השבירה ועיקר השבירה הוא בדעת שהרי האהבה הרעה לא תתעורר בלתי הדעת כענין אין קישוי אלא לדע\"ת<sup data-n=\"1118\">75</sup> כו' שהדעת מתפשט במדות להחיותם והיינו באחוריי' דדעת שהוא השכח\"ה כנ\"ל. וע\"כ נק' פרעה כסיל לפי שאין בו מהארת החכ' אחר שהחכ' לא נפלה כלל בשבירת הכלים וכמ\"ש ימות\"ו ולא בחכ'<sup data-n=\"1119\">76</sup> כו' לכך ממילא נק' כסי\"ל וכמ\"ש וכסי\"ל לא יבין<sup data-n=\"1120\">77</sup> לא יחפוץ כסיל<sup data-n=\"1121\">78</sup> כו' כי מאחר ששרש יניקתו אינו מתחיל רק מאחוריי' דדעת שנפל בשבירה כנ\"ל. והטעם שנק' זק\"ן לפי שנא' ואלה המלכים אשר מלכו לפני מלוך מלך לבני ישראל וידוע שמלך זה הנק' ישראל הוא בחי' התיקו\"ן ואמנם בחי' מלך הראשון דתהו הנק' בלע בן בעור הרי קדם במלכותו הרבה לפני מלוך מלך דתיקון ע\"כ ממילא נק' בלע זה בשם מלך זקן להיותו זקן הרבה ממלך ישראל דבחי' התיקון, אבל נק' מלך זקן וכסיל על אשר אין בו מבחי' החו\"ב כלל מטעם הנ\"ל דבג\"ר לא הי' שבירה כלל. והמופת לזה שאין בחי' חכמ\"ה בקליפות שהרי בחי' השבירה נק' מית\"ה<sup data-n=\"1122\">79</sup> וכמ\"ש וימלוך וימ\"ת<sup data-n=\"1123\">80</sup> וכתי' והחכ' תח\"י'<sup data-n=\"1124\">81</sup>, ולזה הטעם מצינו שעיקר הכח והעוז שיש לכאו\"א למסור נפשו על קדה\"ש היינו רק מצד הארת בחי' חכמ\"ה<sup data-n=\"1125\">82</sup> כח מ\"ה<sup data-n=\"1126\">83</sup> שבנפשו להיות שאין בקליפות כח לנגדה להסתיר אורה כו' וד\"ל.\n<b>ומעתה</b> יובן שרש ענין הי' מכות שנעשו במצרים, דהנה כתיב מלך אלקי' על גוים<sup data-n=\"1127\">84</sup>, פי' שעיקר יניקת החיצוני' הוא רק משם אלקי\"ם ולא משם הוי' כלל. וביאור טעם הדברים, הנה תחלה יש להבין שרש ענין הו\"י' ואלק\"י' דכתיב כי שמ\"ש ומג\"ן<sup data-n=\"1128\">85</sup> הוי' אלקי', <span data-k=\"pg\">794</span> ּ פי' עד\"מ המגן להשמש שהוא נרתק השמש<sup data-n=\"1129\">86</sup> הרי ידוע שהוא המסתיר ומעלים עצם האור של השמש, כך למעלה יובן בשרש ענין שם אלקי\"ם שהוא בחי' כח אלקי, אך הוא הכח להסתיר ולהעלים אוא\"ס וידוע שאוא\"ס הוא כל יכול וגם בחי' כח המסתיר להסתיר ולהעלים האור עד שיומשך השפע בבחי' גבול ותכלית הוא ג\"כ בא מאוא\"ס כי גם בחי' כח המגביל הגבולים נמשך מאוא\"ס<sup data-n=\"1130\">87</sup>, ואע\"פ שאוא\"ס בעצמו בלתי מוגבל אבל מאחר שהוא כל יכול ונק' א\"ס בהכרח שלא יחסר כל ואם לא הי' באפשרי להמצא ממנו גם בחי' הגבול הרי אינו שלם ואוא\"ס נק' שלם בתכלית השלימות ע\"כ בהכרח שגם שם אלק\"י' זה המסתיר הנ\"ל יש לו כח ושרש באוא\"ס עצמו כדי",[["1117","74","<b>חכמה ובינה. . אחוריי' שבהם נפלו</b>: ראה ע\"ח שם. מאמרי אדה\"א דברים ח\"ג ע' א'קטז. וש\"נ."],["1118","75","<b>אין קישוי אלא לדע\"ת</b>: יבמות נג, סע\"ב."],["1119","76","<b>ימות\"ו ולא בחכ'</b>: איוב ד, כא. ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' ט וע' רצט."],["1120","77","<b>וכסי\"ל לא יבין</b>: תהלים צב, ז."],["1121","78","<b>לא יחפוץ כסיל</b>: משלי יח, ב."],["1122","79","<b>השבירה נק' מית\"ה</b>: ראה ע\"ח (שער דרושי הנקודות) ש\"ח, פ\"א. מבו\"ש ש\"ב, ח\"ב פ\"ג ובהגהת צמח ב."],["1123","80","<b>וימלוך וימ\"ת</b>: וישלח לו, לב ואילך."],["1124","81","<b>והחכ' תח\"י'</b>: קהלת ז, יב [ושם: החכמה — ראה הנסמן לעיל ב, ב]."],["1125","82","<b>למסור נפשו. . חכמ\"ה</b>: ראה תניא פי\"ח. ראה גם סה\"מ מלוקט ח\"ב ע' קסו הערה 97."],["1126","83","<b>חכמ\"ה כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["1127","84","<b>מלך אלקי' על גוים</b>: תהלים מז, ט. ראה זהר משפטים צו, א. סידור שער החנוכה רעא, ב. תו\"א יתרו קט, ד."],["1128","85","<b>כי שמ\"ש ומג\"ן</b>: תהלים פד, יב. ראה שער היחוד והאמונה רפ\"ו. הנסמן לעיל פ' שמות לד, סע\"ד ואילך."],["1129","86","<b>נרתק השמש</b>: ראה נדרים ח, ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקב."],["1130","87","<b>כח המגביל. . מאוא\"ס</b>: ראה עבודת הקדש — לר\"מ בן גבאי — ח\"א רפ\"ח. דרך אמונה להנ\"ל רפ\"ב (קה\"ת תשמ\"ח ע' יג)."]]],[2300550324,"שיהי' מסתעף עי\"ז בחי' מציאת כל הנבראי' והעולמות בבחי' הפירוד בפ\"ע כו' וכמ\"ש במ\"א וד\"ל. והנה שם הוי' הוא היפך זה השם דאלקי' המסתיר כו' כי שם הוי' מורה דוקא על בחי' גילוי אוא\"ס ביו\"ד וי\"ו ה\"א<sup data-n=\"1131\">88</sup> כו' כידוע דשם הוי' באצי' דשם אמרו איהו וחיוהי וגרמוהי חד כו', וזהו כמשל השמש עם המגן שהשמש הוא גופו של מאור והמגן הוא הנרתק להסתיר אורו כנ\"ל, כך כתי' כי שמש ומגן הוי' אלקים כלומר ב' שמות הללו הוי' ואלקי' שניהם יחד נמשכו מעצמו' אור הא\"ס אלא ששם הוי' הוא בחי' גילוי אורו והמגן המסתיר שם הוי' זה הוא בחי' שם אלקי' שמסתיר ומעלים על הארת שם הוי' כמו השמש ומגן וד\"ל. והנה מאחר שנא' מלך אלק\"י' על גוים הרי מבואר ששרש יניקת הגוי\"ם הוא משם אלקי\"ם דוקא המסתיר וע\"כ גם אוה\"ע קרו לי' אלקא דאלקייא<sup data-n=\"1132\">89</sup> כידוע, אבל אינם מקבלים יניקה כלל משם הוי' כי שם הוי' הוא בחי' גילוי אוא\"ס כנ\"ל, וכידוע פי' דשם הוי' הי' הוה ויהי'<sup data-n=\"1133\">90</sup> בלי שינוי כלל כמ\"ש אני הוי' לא שניתי<sup data-n=\"1134\">91</sup> דוקא שם הוי' זה אין בו שינוי ואוה\"ע להיותם מקבלים בבחי' הפירוד הגמור וכמ\"ש ומשם יפר\"ד<sup data-n=\"1135\">92</sup> כו', ע\"כ עיקר יניקתם באה דוקא משם אלקים כנ\"ל המסתיר על שם הוי' ואינם יכולים לקבל כלל משם הוי'<sup data-n=\"1136\">*93</sup>, משא\"כ בישראל כתי' כי חלק הוי' עמו<sup data-n=\"1137\">93</sup> כו' וכמ\"ש במ\"א. ולהיות כן זהו הטעם שאמר פרעה לא ידעתי את הוי' כלומר איני מכיר ומשיג כלל לשם הוי' אלא דוקא לשם אלקי\"ם המסתיר מטעם הנ\"ל, כי פרעה הוא בחי' עורף דקליפה המסתיר על מוח הדעת ושרשו מבחי' אחוריי' דקדושה ולכך נק' אלקי' אחרים כנ\"ל וד\"ל. וכיוצא בזה ג\"כ יובן מ\"ש מלך אלקי' על גוים דכל הע' שרים אינם משיגים כלל בשם הוי' כי סבורים שאין גילוי אוא\"ס כלל למטה מפני שבא להם דוקא ע\"י בחי' הסתר דשם אלקי' וזהו שנא' רם הוי' על כל גוים כנ\"ל וכמ\"ש במ\"א.\n<b>ובזה</b> יובן ג\"כ הטעם ענין י' מכות שהיו במצרים, כי הנה לכאורה אינו מובן מ\"ש הטעם בתורה לי' מכות וידעו מצרי\"ם כי אני הוי'<sup data-n=\"1138\">94</sup> כו' וכי אם ידעו מצרים שם הוי' מה יש בזה איזה מעלה ומדרגה אחר שהם גוים וערלים כו', וגם מהו שאמר שידעו כי אני ה' למה שם הוי' דוקא. אך הנה הענין הוא די\"ס דקליפה דבי\"ע יש להם שרש ומקור גם בעולם האצי' אלא שמקומם ומשכנם הוא בעולם הבריאה<sup data-n=\"1139\">95</sup> כי באצי' דאיהו וחיוהי",[["1131","88","<b>ביו\"ד וי\"ו ה\"א</b>: כ\"ה בגוכתי\"ק."],["1132","89","<b>קרו לי' אלקא דאלקייא</b>: מנחות בסופה."],["1133","90","<b>הוי' הי' הוה ויהי'</b>: ראה זהר (רע\"מ) פינחס רנז, ב. שער היחוה\"א פ\"ז. הנסמן בתו\"ח מקץ ריט, ד הערה 62."],["1134","91","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["1135","92","<b>ומשם יפר\"ד</b>: בראשית ב, י."],["1136","*93","<b>ואינם יכולים לקבל כלל משם הוי'</b>: ראה גם לעיל פ' שמות לא, ב ואילך."],["1137","93","<b>כי חלק הוי' עמו</b>: האזינו לב, ט."],["1138","94","<b>וידעו מצרי\"ם כי אני הוי'</b>: וארא ז, ה. ראה גם הנסמן לעיל כ, ב."],["1139","95","<b>די\"ס דקליפה. . ומשכנם הוא בעולם הבריאה</b>: ראה אוה\"ת ויצא (כרך ה) ע' תתמה: ”כ\"מ בע\"ח שער הקליפות פ\"ב. . בשער ק\"נ פ\"ט\" ע\"ש. שופטים ס\"ע תתל ואילך. לקו\"ת במדבר ג, סע\"ג."]]],[2300550349,"כו' לא ישכון שם בחי' רע כלל אפי' שרש הרע כמ\"ש לא <span data-k=\"pg\">שצז</span> ּ יגורך רע<sup data-n=\"1140\">96</sup> כו' וכתיב טהור עינים מראות ברע<sup data-n=\"1141\">97</sup> כו', אבל מ\"מ שרש שלהם ישנו באצי' אלא שאינו נק' בשם קליפה המסתרת אך בהגיעם לעולם הנפרד שם נקראו בשם קליפה וכמ\"ש ביאור דבר זה במ\"א<sup data-n=\"1142\">98</sup>. והנה ע\"י הי' מכות שנעשו במצרים נשברו ונפלו בחי' י\"ס דקליפה מבחי' שרש שרשם באצי' והגם שלא נשברו לגמרי שהרי נשאר עדיין בחי' קליפה בע' שרים דבי\"ע, אך בחי' שרשם באצי' נפל ונשבר עכ\"פ. וז\"ש אשר התעללתי במצרי\"ם<sup data-n=\"1143\">99</sup> כי פרע\"ה ועמו הי' כולל ע' שרים כנ\"ל והרי מבואר למעלה דשרש יניקת הע' שרים הוא רק מבחי' שם האלקי' המסתיר כמ\"ש מלך אלקי' על גוים כו' וכנ\"ל, לכך אמר בטעם העשר מכות וידעו מצרים כי אני ה' כלומר עתה יכירו וישיגו בבחי' גילוי אוא\"ס שבשם הוי' ע\"י הנסים והנפלאות הללו שלמעלה מן הטבע, כי הטב\"ע בגי' אלקי\"ם<sup data-n=\"1144\">100</sup> כידוע להיות ששם אלקי\"ם זה מסתיר ע\"כ נמצא מציאות הטבע, אבל ע\"י הנסים נגלה אור שם הוי' שלמעלה משם אלקי\"ם המסתיר כו'. אך א\"כ לא הי' צריך רק להראות נסים בלבד ולמה היו הנסים דוקא בענין הכאות למצרים כמו בדם וצפרדע כו', אמנם הענין הוא כי אלקי מצרים הוא בחי' אלק\"י' אחרים שמקבלים מבחי' אחוריי' דשם אלקים דקדושה כנ\"ל, וז\"ש ובכל אלקי מצרים אעשה שפטים<sup data-n=\"1145\">101</sup> אני ה' דוקא שם הוי' הוא העושה שפטים ודינים להשפיל ולהאביד שרש יניקו' אלקי' האחרים שמקבלים משם אלקי' דקדושה והיינו בהגלות נגלות אור שם הוי' שאינו בבחי' הסתר כלל. וזהו שאמר הטעם לי' מכות וידעו מצרים כי אני הוי' כלומר מפני ששם הוי' נגלה עליהם בי' מכות הללו וידעו וישיגו מהם שהעיקר הוא שם הוי' דוקא ולא שם האלקי\"ם המסתיר כו', ולא כמו שאמר פרעה לא ידעתי את ה' אלא שם אלקי' כי ע\"י המכות נפלו ונשברו י\"ס דקליפה למעלה היונקי' משם אלקים וידעו וישיגו בשם הוי' דוקא וכמ\"ש אני ה' לא שניתי כו' מפני שאין הטבע מסתיר לפניו.\n<b>אך</b> עדיין יש להבין למה האריך כ\"כ בסיפור הי' מכות בפ' וארא ובפ' בא. וגם מה זה ענין סמיכות לענין מתן תורה שהי' אח\"כ שהוצרך לספר בהם מקודם. אמנם הענין הוא דאריכות סיפור הי' מכות הוא ענין הכנה למ\"ת שאם לא הי' מכות לא הי' נגלה אור התורה לישראל בהר סיני, וע\"כ האריך כ\"כ בסיפורם. והענין הוא מובן ע\"פ הנ\"ל בפי' כללות המאמר דאית מלך וכהן בסט\"א כו', משום דמלך זה הוא כולל י\"ס דקליפה כמ\"ש למעלה דפרע\"ה הוא עורף שעומד לנגד הדעת",[["1140","96","<b>לא יגורך רע</b>: תהלים ה, ה."],["1141","97","<b>טהור עינים מראות ברע</b>: חבקוק א, יג [ושם: רע — ראה מנחת שי שם. לעיל פ' בא קכג, ד וש\"נ]."],["1142","98","<b>ביאור דבר זה במ\"א</b>: ראה מאמרי אדה\"ז אתהלך לאזניא ע' קנה. אוה\"ת ויצא שם."],["1143","99","<b>אשר התעללתי במצרי\"ם</b>: בא י, ב."],["1144","100","<b>הטב\"ע בגי' אלקי\"ם</b>: ראה שער היחוד והאמונה רפ\"ו. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקעג. לעיל פ' שמות לח, א."],["1145","101","<b>ובכל אלקי מצרים אעשה שפטים</b>: בא יב, יב."]]],[2300550372,"שכלולי' בו הז' מדות וכל מדה כלולה מי' הרי ע' שרים כו'. והנה ידוע בכללות ד' עולמות דאבי\"ע שהאצי' בחכ' ובינה בבריא'<sup data-n=\"1146\">102</sup> ומדות ביצי' כו' והוא ד' אותיות דשם הוי' יו\"ד בחכ' בבחי' האצי' ה\"א בבינה<sup data-n=\"1147\">103</sup> בבחי' בריאה כו' כידוע דאבא מקנן באצי'<sup data-n=\"1148\">104</sup> ואימא מקננא בכורסייא<sup data-n=\"1149\">105</sup> וז\"א ביצי'<sup data-n=\"1150\">106</sup> ומל' בעשי'<sup data-n=\"1151\">107</sup> כו', וא\"כ הרי התורה ששרשה מבחי' אור אבא כידוע דאורייתא מחכמה עילאה נפקת<sup data-n=\"1152\">108</sup> הרי היא מבחי' האצי' דשם אמרו דאיהו וחיוהי וגרמוהי חד כו' ולא יגורך רע כתיב שאין שם אפי' שמץ מן הרע גם להיות נמצא <span data-k=\"pg\">796</span> ּ משם שרש לרע וכמארז\"ל אין רע יורד מלמעלה<sup data-n=\"1153\">109</sup>, וא\"כ לפ\"ז לא הי' באפשרי שיתגלה אור דתורה למטה בלתי הקדמת יו\"ד מכות בי\"ס דקליפה כי אור האצי' לא יסבול שום דבר רע כנ\"ל. ואע\"פ שאין רע באצי' מ\"מ יש שם בחי' השרש לקליפה כנ\"ל ע\"כ הוצרך להשפיל בתחלה י\"ס דקליפה בשרשם באצי' ואזי יוכל אור דתורה שבאצי' לבא לידי גילוי למטה כו', והיינו שרש ענין אריכות סיפור הי' מכות בהכנעת פרעה שכולל ע' שרים כדי שאח\"כ יוכל להיות מ\"ת בגלוי וד\"ל.\n<b>אך</b> הנה אע\"פ שפרעה ועמו כבר נכנעו בי' מכות בעוד ישראל במצרים עכ\"ז עדיין לא הי' אור דתורה נגלה לישראל כ\"א ע\"י הכנעת יתרו כהן מדין ג\"כ, וזהו שסמך פ' יתרו לפ' מ\"ת בחדש השלישי כו' דאם לא הכנעת יתרו לא הי' התורה ניתנה לישראל וכמבואר זה במאמר הזהר הזה שזהו כללות תוכן הענין שהקדים לבאר בענין מלך וכהן כו'. וביאור הדברים למה יש צורך עוד בהכנעת יתרו אחר שכבר נפלו ונשברו י\"ס דקליפה בהכנעת פרע\"ה דקליפה כנ\"ל, הנה הענין יובן ע\"פ הנ\"ל בענין שרש יתרו כהן און שהוא בחי' חסד דבריאה דקליפה דוגמת בחי' מיכאל כהנא רבא בסט' דקדושה כו' וכנ\"ל באריכות. והנה מבואר למעלה דיש כח ועוז במיכאל כהנא רבא דקדושה להעלות מ\"ן מכל הניצוצו' דקדושה ולעשות בחי' יחודים עליונים בי\"ס דקדושה שבאצי' המתלבשי' בבריאה ולהוסיף אור בהן והיינו בחי' מלך דקדושה דכהן המשמש תחותי' מביאו וממשיכו בבחי' גילוי אור למטה כו', וכך ממש יש כח ועוז לבחי' כהן און דקליפה להעלות מ\"ן מנשמות החיצוני' כו' ולייחד יחודי' בי\"ס דקליפה עד שהי' ממשיך אותם לבוא בבחי' גילוי למטה, והוא בחי' מלך דקליפה שנק' פרע\"ה והיינו ע\"י שהי' מחזק שרש הי\"ס דקליפה למעלה באצי' ע\"י העובדות בקרבנות והעלאות שהי' יתרו יודע לעבוד לכאו\"א כנ\"ל. ונמצא מובן מזה דהגם שכבר נפלו ונשברו הי\"ס דקליפה משרשם כמו שהם",[["1146","102","<b>דאבי\"ע. . בחכ'. . בבריא'</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, רפ\"א. הנסמן במראי מקומות למאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקי."],["1147","103","<b>יו\"ד בחכ'. . ה\"א בבינה</b>: ראה זהר ויקרא יז, א. הנסמן בתו\"ח ויצא קסז, ג הערה 38."],["1148","104","<b>דאבא מקנן באצי'</b>: ראה ת\"ז ת\"ו (כג, א). הנסמן במאמרי אדה\"א דברים ח\"א ע' רלה."],["1149","105","<b>ואימא מקננא בכורסייא</b>: ראה ת\"ז שם. מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["1150","106","<b>וז\"א ביצי'</b>: ראה ת\"ז שם. מאמרי אדה\"ז הקצרים ע' תקנב. מאמרי אדה\"א נ\"ך ע' יד. וש\"נ."],["1151","107","<b>ומל' בעשי'</b>: ראה ת\"ז שם."],["1152","108","<b>דאורייתא מחכמה עילאה נפקת</b>: נסמן לעיל רסח, ד."],["1153","109","<b>אין רע יורד מלמעלה</b>: ראה ב\"ר פנ\"א, ג. גנת אגוז לר\"י גיקטיליא ח\"א שער ההוי' (ירושלים תשמ\"ט ע' מו). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסו ובהנסמן במראי מקומות לשם. שע\"ת יז, ד הערה 13. לקמן פ' תצוה שמב, ד."]]],[2300550391,"באצי' אבל מ\"מ לא נאבדו לגמרי כי מקומם נשאר בעולם הבריאה כנ\"ל, וא\"כ הרי הי' ביכולת יתרו כהן און לעורר אותם מחדש בהעלאות קרבנות ולחזק הארת שרשם באצי' ולהביאן לידי גילוי אור בבי\"ע כו', והדרא קושיא לדוכתה שלא הי' באפשרי להיות מתן תורה מאצי' לבריאה אחר שנמשך מלמעלה בחי' י\"ס דקליפה ע\"י הכהן און כו', אשר לפ\"ז הטעם בהכרח הי' שיכנע בתחלה גם יתרו כהן און ויתגייר<sup data-n=\"1154\">110</sup> ואזי לא יהי' בחי' כהן דמשמש למלך דסט\"א ולא יתחזק הארת י\"ס דקליפה מחדש ולא יזיקו להסתיר אור דתורה וד\"ל. וכל זה דוקא עכשיו מפני שמקום הקליפות נשאר בעולם הבריאה עכ\"פ ויש חשש שיתחזק שרשן באצי' ע\"י כהן און, אבל לעתיד לבא יהי' ביטול הרע מכל וכל וכמ\"ש ואת רוח הטומא'<sup data-n=\"1155\">111</sup> אעביר מן הארץ לגמרי וכן ובלע המו\"ת<sup data-n=\"1156\">112</sup> כו' אזי לא יהי' חששא כלל מהתגברו' החיצוני' ע\"כ נא' לעתיד ונגלה כבוד ה'<sup data-n=\"1157\">113</sup> וראו כל בשר כו' כי עין בעין נראה אתה ה'<sup data-n=\"1158\">114</sup> כו' ולא יהי' נצרך כלל לאכפיי' לסט\"א בתחלה, משא\"כ עכשיו שיש להם לע' שרים שרש למטה בבריאה עכ\"פ לכך הוצרך לסמוך גם הכנעת יתרו מקודם למ\"ת וזהו שסמך פ' יתרו לפ' מ\"ת דבחדש השלישי כו' וד\"ל.\n<span data-k=\"pg\">שצח</span> ּ<b>ואחר</b> כ\"ז יתבארו פרטי דברי המאמר הנ\"ל, בסט\"א אית מלך וכהן דאקרי מלך זקן וכסיל ותחותי' אית כהן דמשמש ואקרי כהן און כו', כבר נתבאר כל זה למעלה דמלך זהו בחי' מלכו' דקליפה שכלולה בי\"ס דקליפה דאצי' וכהן און הוא בחי' חסד דבריאה דקליפה דמשמש תחותי' להעלות מ\"ן אליו ולהמשיכו עי\"ז למטה כו' וכנ\"ל באריכות גם הטעם שנק' מלך זקן וכסיל כו', ואח\"כ מביא ראי' לביאור ענין כהן און זה כמ\"ש הה\"ד<sup data-n=\"1159\">115</sup> ויאמר אפרים אך עשרתי מצאתי און לי בגין דחילא דא שלטא על ההוא עובדא דעבד ירבעם ובדא אצלח, פי' כי הנה ירבעם ביטל עולי רגל מלבוא לירושלים<sup data-n=\"1160\">116</sup> מפני שמלכי בית דוד יושבין בעזרה<sup data-n=\"1161\">117</sup> והוא הי' צריך לעמוד שם כידוע בדברי רז\"ל וע\"כ התחכם לעשות עגלי זהב בשומרון<sup data-n=\"1162\">118</sup>, ולכאו' מה הי' הוצרך לעגלי זהב הללו. אך הענין הוא דכתי' את זלעו\"ז עשה האלקי' כו', ויש י\"ס בקליפה לעומת י\"ס דקדושה וכמו שבג' רגלים הי' בחי' יחודים עליונים בע\"ס דקדושה ועי\"ז נמשך רב טוב ושפע למטה כידוע, כך יש בחי' יחודי' בסט\"א בע\"ס דקליפה שעי\"ז נמשך מהם טוב ושפע גשמי' כנ\"ל בענין הקטרות והעלאות לע\"ז כמו ע\"ז דפעור וכיוצא בו. וע\"כ התחכם ירבעם להמשיך שפע גשמיו' לישראל מצד אחר והוא בעגלי זהב לעשות בהם יחודים בע\"ס דקליפה ע\"י כהני הבעל ועי\"ז יומשך",[["1154","110","<b>יתרו. . ויתגייר</b>: ראה סנהדרין צד, א."],["1155","111","<b>ואת רוח הטומא'</b>: זכרי' יג, ב."],["1156","112","<b>ובלע המו\"ת</b>: ישעי' כה, ח [ושם: בלע — ראה לקמן פ' משפטים שג, ד. (פ' ויקהל שצב, א). מאמרי אדה\"א דברים ח\"ג ע' א'קכג. וש\"נ. שע\"ת קכ, ב ובהערה 10]."],["1157","113","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."],["1158","114","<b>כי עין בעין נראה אתה ה'</b>: שלח יד, יד [בדילוג — ראה הנסמן לעיל פ' בא קב, ב]."],["1159","115","<b>כמ\"ש הה\"ד</b>: לעיל רסט, סע\"ד ואילך: ודא הוא רזא דכתיב."],["1160","116","<b>ירבעם ביטל עולי רגל מלבוא לירושלים</b>: מל\"א יב, כו ואילך."],["1161","117","<b>שמלכי בית דוד יושבין בעזרה</b>: יומא כה, א. וש\"נ."],["1162","118","<b>לעשות עגלי זהב בשומרון</b>: בהנחת הר\"מ בן כ\"ק אדה\"ז כאן [לא נדפסה לע\"ע]: בדן ובית אל — מל\"א יב, כט."]]],[2300550408,"שפע גשמיות לישראל ולא יצטרכו לקבל שפע מי\"ס דקדושה כלל, וע\"כ אמרו עליו שחטא והחטיא את ישראל<sup data-n=\"1163\">119</sup> כו' שמלבד העדר אור הקדושה הוסיף חטא ופשע במה שהגביר אורות הסט\"א בעגלי זהב כו' וכידוע. והנה שרש כל הע\"ז מקבלים מבחי' שם אלקי' דוקא שהוא שם ב\"ן<sup data-n=\"1164\">120</sup> דקדושה וכמ\"ש מלך אלקי' על גוי\"ם כו', ואמנם הנה ידוע דשרש שם ב\"ן דנוג\"ה דבי\"ע הוא מז' המלכי'<sup data-n=\"1165\">121</sup> דתהו שבהן נא' וימלו\"ך וימת ומלוכה הוא בשם אלקי' שהוא שם ב\"ן וידוע דבחי' התהו קדם לבחי' התיקון<sup data-n=\"1166\">122</sup> כו', וכמ\"ש לפני מלוך מלך לבנ\"י וע\"כ נק' מלך זק\"ן כנ\"ל. ע\"כ אמר אפרי\"ם שהוא ירבעם<sup data-n=\"1167\">123</sup> כידוע אך עשרתי מצאתי או\"ן לי כו', פי' עשרתי כי המשיך רב טוב וחיות מבחי' התה\"ו שגדול מבחי' התיקון ע\"י שעשה העגלי זהב והמשיך הע\"ס דקליפה דבתהו יש עוש\"ר גדול להיותם בשרשם גבוה מאד, אך כשנפלו בשבירה נתגשמו האורות ונעשים בחי' קליפות כמו כל מיני חיות גשמיות וכל התענוגי' הגשמי' כו'. והיינו שאמר אך עשרתי עוש\"ר גדול כי מצאתי און לי פי' כהן או\"ן דמשמש ומעלה מ\"ן בעבודה והקטרה כדי שיומשך העוש\"ר הזה כמ\"ש למעלה בביאור ענין הכתוב במה שאמרו עובדי הבעל ומאז חדלנו לקט\"ר למלכת השמים חסרנו כל כו' וד\"ל. וזהו שמפרש ראי' זאת ממ\"ש מצאתי או\"ן לי בגין דחילא דא דהיינו ע\"ס דקליפה שלטא על ההוא עובדא בהעלאת מ\"ן דהקטרה לע\"ז, ומפרש או\"ן זה לשון כח כמ\"ש כחי וראשית אונ\"י<sup data-n=\"1168\">124</sup> לפי שכהן זה הוא הממשיך תוס' כח ועוז בע\"ס דקליפה להמשיך למטה וע\"כ נק' בשם כהן און, וז\"ש מצאתי או\"ן לי פי' מצאתי על כה\"ן שימשיך האו\"ן כו' ולכך נק' יתרו כהן או\"ן כנ\"ל וד\"ל.\n<b>רזא</b> דמלה כד האי מלך וכהן אתכפיין ואתברון<sup data-n=\"1169\">125</sup> כדין כל סטרין אחרנין <span data-k=\"pg\">798</span> ּ אתברון<sup data-n=\"1170\">126</sup> ואודין לי' לקוב\"ה כמ\"ש<sup data-n=\"1171\">127</sup> ונשגב ה' לבדו כו', פי' האי מלך וכהן משום דאין מלך בלא כהן ולא כהן בלא מלך כנ\"ל והיינו בחי' יחוד דע\"ס דקליפה שלא יהי' מתעורר לעולם באצי', פי' אתברון ואתכפיין היינו רק להשפילם מלמעלה למטה ולא ביטול מכל וכל כנ\"ל דנשאר מקומם בבריאה כו' ואזי ממילא הע\"ס דקליפה דבי\"ע ממילא אתברון כי מלך וכהן כוללם יחד כנ\"ל. ומ\"ש ואודין לי' לקוב\"ה היינו שיודו בשם הוי' דוקא וכמ\"ש ונשגב הוי' לבדו פי' שאין שם אלק\"י' המסתיר לשם הוי' ודלא כפרעה שא' לא ידעתי את הוי', כנ\"ל באריכות, דעיקר יניקו' החיצוני' הוא משם אלקי' דוקא והיינו שמפרש ואומר, ורזא דא ממש עבד קודב\"ה בארעא דתב\"ר מלך זק\"ן וכסיל דא הוא פרע\"ה דאמר לא ידעתי את",[["1163","119","<b>שחטא והחטיא את ישראל</b>: מל\"א יד, טז."],["1164","120","<b>אלקי'. . שם ב\"ן</b>: ראה גם לעיל פ' שמות יט, ג הערה 814."],["1165","121","<b>דשרש שם ב\"ן. . מז' המלכי'</b>: ראה ע\"ח (שער התיקון) ש\"י, פ\"ג."],["1166","122","<b>התהו קדם לבחי' התיקון</b>: ראה תו\"א בשלח סה, ד. לקו\"ת אמור לז, ד. וש\"נ."],["1167","123","<b>אפרי\"ם שהוא ירבעם</b>: ראה רש\"י כאן עה\"פ (הושע יב, ט)."],["1168","124","<b>כחי וראשית אונ\"י</b>: ויחי מט, ג."],["1169","125","<b>ואתברון</b>: לעיל ער, א: ואתברו."],["1170","126","<b>אתברון</b>: לעיל שם: אתכפיין."],["1171","127","<b>כמ\"ש</b>: לעיל שם: כדין כתי'."]]],[2300550425,"הוי', פי' תב\"ר היינו שהשפילו מבחי' האצי' שלא ינק שם מבחי' אלקי' כנ\"ל, ובחי' פרעה שנק' מלך זק\"ן וכסיל מבואר למעלה. ובעא קוב\"ה דיתייקרא שמי' בארעא כמה דאיהו יקירא לעילא, שמי' זה היינו שם הוי' דוקא דהוא יקיר לעילא באצי' ורצה שיתגלה שם הוי' זה גם בבי\"ע כמו באצי', וז\"ש בארע\"א וכמבואר למעלה בפי' וידעו מצרים כי אני ה' כו'. כיון דאלקי לי' ולעמי' אתא ואודי לקוב\"ה, פי' ע\"י יו\"ד מכות דוקא בעשותו שפטי\"ם באלק\"י מצרים נגלה שם הוי' וכנ\"ל באריכות וד\"ל.\n<b>ולבתר</b> אתבר ואתכפיא האי כהן או\"ן יתרו דמשמש תחותי' ואודי לקוב\"ה פי' ואמר ברוך הוי' אשר הציל כו' מבואר למעלה שאם לא הי' הכנעת יתרו כהן און עדיין הי' תקוה לכסיל העליון הנק' מלך זקן וכסיל להמשיך שפע למטה כו', אך כאשר נכנע יתרו אין מי שיעורר ויחזק בחי' מל' דקליפה כו', והכנעתו היינו במה שא' ברוך הוי' שהעיקר הוא שם הוי' דוקא ולא שם אלקי' וביר\"ך לשם הוי' באמרו ברוך הוי' דהיינו שיומשך מבחי' ההעלם שנתעלם בשם אלקי' להאיר למטה כמו למעלה, וכענין לעתיד דכתי' ונגלה כבוד ה' וכמארז\"ל שיוציא חמ\"ה מנרתקה<sup data-n=\"1172\">128</sup> שהוא שם אלקי' הנרת\"ק להוי' שנק' שמ\"ש כו'. וזהו שאמר יתרו עתה ידעתי כי גדול הוי' מכל האלקים, ולכאורה תיבת<sup data-n=\"1173\">129</sup> כל זה מיותר, אך ר\"ל כי יש ק\"ך צירופי אלקי'<sup data-n=\"1174\">130</sup> המסתירי' לשם הוי' כאו\"א מסתיר כפי כחו, ואמנם עתה ראה והשיג לשם הוי' שהוא העיקר והוא גדול מכ\"ל בחי' האלקי' המסתירי' אורו כו' ולאחר שהודה גם יתרו על שם הוי' שהוא גדו\"ל מכל אלקי' אח\"כ דוקא נא' פ' דמ\"ת זאת בחדש השלישי כו' מטעם המבואר למעלה באריכות וד\"ל.\n<b>ודא</b><sup data-n=\"1175\">131</sup> איהו רזא דאמרה רחל כד חמאת דמיתת כמ\"ש ויהי בצאת נפשה כי מתה ותאמר בן אונ\"י<sup data-n=\"1176\">132</sup> כו' ובג\"ד אוחי יעקב ואמר בן ימין סטר ימינא ולא סטר שמאלא וכיון דהאי מלך וכהן אתברו אסתלק יקרא דקוב\"ה לעילא ותתא ואתייהב אוריי' לישראל בשלימו דשולטנא על כולא. פתח וא' יודוך עמי\"ם אלקי'<sup data-n=\"1177\">133</sup> כו' כדין קם דוד מלכא ושבח ואוד\"י למלכא קדישא, דבההוא שעתא דרוח צפון אתער והוה בטש באינון נימין דכנורא וכנורא הוה מנגן וא' שירה ומה א' יודוך עמים כו'<sup data-n=\"1178\">134</sup>. ת\"ח בשעתא דקוב\"ה אתער לכל אינון רתיכין למיהב לון טרפא כמ\"ש ותקם בעוד לילה<sup data-n=\"1179\">135</sup> ותתן טרף לביתה וח\"ק לנערותי\"ה",[["1172","128","<b>שיוציא חמ\"ה מנרתקה</b>: ראה ע\"ז ג, סע\"ב. לעיל פ' שמות לט, ב. וש\"נ."],["1173","129","<b>תיבת</b>: נכתב ממעל לשורה."],["1174","130","<b>ק\"ך צירופי אלקי'</b>: נסמן לעיל רסג, ג."],["1175","131","<b>ודא</b>: המשך זהר יתרו שם (סז, ב) בשינויים. וראה במאמר שלאח\"ז."],["1176","132","<b>ויהי בצאת. . ותאמר בן אונ\"י</b>: וישלח לה, יח [ושם: ותקרא שמו — בזהר כאן מביא מהכתוב רק שתי תיבות האחרונות]."],["1177","133","<b>יודוך עמי\"ם אלקי'</b>: תהלים סז, ד. ו."],["1178","134","<b>יודוך עמים כו'</b>: בזהר כאן ליתא."],["1179","135","<b>ותקם בעוד לילה</b>: משלי לא, טו."]]],[2300550441,"כדין כולהו פתחי וא' אלקי\"ם יחננו ויברכנו<sup data-n=\"1180\">136</sup> כו' כד רוח צפון אתער ונשיב וא' לדעת בארץ דרכך<sup data-n=\"1181\">137</sup> כו', ע\"כ.\n<b>הנה</b> מה שאמר דרחל <span data-k=\"pg\">שצט</span> ּ קראה לבנימין בן אוני משום דחמאת דמיתת כו', הענין הוא לפי שרחל למעלה הוא בבחי' מל' דאצי' שנק' רח\"ל עקרת<sup data-n=\"1182\">138</sup> הבית<sup data-n=\"1183\">139</sup> כידוע ובצאת נפשה כי מת\"ה היינו בשעה שיש יניקה לחיצוני' כמ\"ש רגליה יורדות מו\"ת<sup data-n=\"1184\">140</sup> והוא הנק' אילנא דמותא דשליט<sup data-n=\"1185\">141</sup> בשעת הסתלקו' אור ממל' דקדושה כו', ובראות רחל למטה שהיא מתה ואילנא דמותא שלטא כו' חששה לנפשה פן גם הילד הנולד שרש יש לו באילנא דמותא זה דהיינו מסטר שמאלא שבה דאלקי' אחרים מקבלים משם כידוע וע\"כ קראה לו בן אונ\"י, כלומר שהוא בן משרש חיות הסטר שמאלא בחי' הגבורו' הקשין שבמל' וע\"כ המות שולט בה כו'. אך יעקב מיד הפך הולד מסטר שמאלא לסטר ימינא וקרא לו בן ימי\"ן כלומר שהפך בחי' שרש דסטר שמאלא שהי' לולד והביאו לבחי' קו הימין שבסט' ימינא וקרא לו בן ימי\"ן ולולי שהפכו יעקב משמאל לימין הי' נשאר בסטר שמאלא, ע\"כ אמר דאוחי יעקב שמיהר א\"ע והצילו מסטר שמאלא מגבו' הקשות שבמל' כו' וד\"ל. וזה מביא לראי' על פי' כהן או\"ן שהוא בסטר אחרא אחר דרחל קרא' לו בן אוני מטעם זה כמבואר.\n<b>וכיון</b> דהאי מלך וכהן אתברו אסתלק יקרא דקוב\"ה כו' מבואר כל זה למעלה. ומ\"ש אסתלק יקרא הוא בחי' ת\"ת שהוא בשם הוי'<sup data-n=\"1186\">142</sup> דוקא. ומ\"ש לעילא ותתא היינו שמאיר למטה כמו למעלה ממש כנ\"ל. ומ\"ש ואתייהב אורייתא מפני שהתורה הוא בחי' שם הוי' שבת\"ת<sup data-n=\"1187\">143</sup> כידוע והיינו שאמר בשלימ\"ו דשלטנ\"א על כולא כי שם הוי' דת\"ת שולט בכללות הע\"ס כו' וכידוע, ונק' עמודא דאמצעיתא<sup data-n=\"1188\">144</sup> בחי' קו האמצעי דת\"י כו' וכמארז\"ל חרו\"ת על הלוחות<sup data-n=\"1189\">145</sup> כו' וד\"ל.\n<b>פתח</b> וא' יודוך עמים אלקים כו', פי' בא לבאר טעם הממשלה והשליטה שהיו ישראל שולטי' באוה\"ע כולם ע\"י מ\"ת לולי חטאו בעגל כמבואר בדברי רז\"ל<sup data-n=\"1190\">146</sup>, והקדים לבאר הפסוק זה יודו\"ך עמים דדוד אמרו בחצות לילה ושבח ואודי למלכא כו'. דהנה ידוע דדוד מלכא הוא בחי' מל'<sup data-n=\"1191\">147</sup> דאצי', וידוע שבכל חצות לילה יורדת המל'<sup data-n=\"1192\">148</sup> למטה בהיכלות החיצוני' לברר בירורי' דרפ\"ח ניצוצי'<sup data-n=\"1193\">149</sup> וז\"ש ותקם בעוד לילה ותתן טר\"ף פי'",[["1180","136","<b>אלקי\"ם יחננו ויברכנו</b>: תהלים סז, ב."],["1181","137","<b>לדעת בארץ דרכך</b>: תהלים שם, ג."],["1182","138","<b>מל'. . רח\"ל עקרת הבית</b>: ראה ע\"ח (שער פרצופי זו\"ן) של\"א, פ\"א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקכג ובהנסמן במראי מקומות לשם."],["1183","139","<b>רח\"ל עקרת הבית</b>: ראה ב\"ר פע\"א, ב. זהר ויצא קנד, א. קנז, ב. רש\"י רות ד, יא."],["1184","140","<b>רגליה יורדות מו\"ת</b>: משלי ה, ה. ראה זהר ויחי רכא, ב. קונטרס עץ החיים ע' 27 ואילך. לקמן רעו, ד."],["1185","141","<b>אילנא דמותא דשליט</b>: ראה זהר במדבר קיט, א."],["1186","142","<b>ת\"ת שהוא בשם הוי'</b>: נסמן לעיל רנח, א."],["1187","143","<b>שהתורה. . שבת\"ת</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תשפג. וש\"נ."],["1188","144","<b>דת\"ת. . עמודא דאמצעיתא</b>: ראה זהר (רע\"מ) פינחס רמג, רע\"ב."],["1189","145","<b>חרו\"ת על הלוחות</b>: תשא לב, טז. ראה הנסמן לעיל רסט, א הערה 287."],["1190","146","<b>בדברי רז\"ל</b>: ראה גם זהר ויחי רכט, ב."],["1191","147","<b>דדוד. . מל'</b>: ראה פרדס (שער עה\"כ) שכ\"ג, מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["1192","148","<b>שבכל חצות לילה יורדת המל'</b>: ראה רמ\"ז (בפי' הזהר) כאן. לקו\"ת במדבר ג, סע\"ב ואילך."],["1193","149","<b>דרפ\"ח ניצוצי'</b>: ראה ע\"ח (שער רפ\"ח) שי\"ח, פ\"ב. לקו\"ש וישב — כרך טו — ע' 524 (אג\"ק ח\"ב ע' כא). וש\"נ. מאמרי אדה\"א דברים ח\"ד ע' א'קעד. וש\"נ."]]],[2300550456,"טר\"ף מלשון טריפ\"ה וגזילה כמו חי' הדורסת וטורפת כו'. וידוע ביאור הדברים לפי שרפ\"ח ניצוצי' דתהו נפלו בקליפה ושם ב\"ן הוא היורד ומברר אותן להעלותם מהיכלות החיצוני' לקדושה האלקי', וזהו פי' טר\"ף כי רפ\"ח עם הכולל גימט' טר\"ף<sup data-n=\"1194\">150</sup> כו'. ומ\"ש ותקם בעוד לילה ותתן טר\"ף לביתה טרף זה היינו מה שלוקחין הניצוצו' מן החיצוני' שעלו בידיהם בדרך שביר\"ה ונפילה מז' מלכי' דתהו וז\"ש חיל בל\"ע ויקיאנו<sup data-n=\"1195\">151</sup> שמוציאי' בלעם מפיהם כו' וזה נעשה בחי' מזון וחיות לסט' דקדושה. כי יש גבול ומדה ליניקה ושפע בסט' דקדושה והוא הנק' חק כמ\"ש וח\"ק לנערותי\"ה כו', פי' ח\"ק זה היינו בחי' קצבת המזון הקצוב לכל העולמות שבסט' דקדושה וע\"ד מ\"ש ואכלו את חוק\"ם<sup data-n=\"1196\">152</sup> וכאשר כלה הקצבה שניתנה להם יורדת המל' לטרוף טר\"ף מניצוצי' דקדושה שביד החיצוני' ונותנת מזה בחי' מזון וחיות לסט' דקדושה בחק וקצבה. וז\"ש וח\"ק לנערותי' פי' נערות\"י' הן ההיכלות העליונו' שבסט' דקדושה ונק' ז' הנערות<sup data-n=\"1197\">153</sup> כידוע, ויש בזה ב' מדרגות, הא' אנשי ביתה שבפנימיות העולמות ולהם נותנת טרף ומזו\"ן יתר <span data-k=\"pg\">800</span> ּ על המדה הקצובה להם כי זהו הבא מן השלל שאין לו קצבה. והב' הן נערותי\"ה שבחיצוני' העולמות שנותנת מזה הטרף לחם חוקם בחק וקצבה ולולי זה הטרף הי' כלה השיעור והמדה הנמדד להם מלמעלה ע\"פ קו המדה כנודע וד\"ל.\n<b>והנה</b> טרף זה<sup data-n=\"1198\">154</sup> הנלקח מן החיצוני' הנה בזאת הלקיחה ממילא ניטל מהם מקור החיות וימותו וז\"ש אשר שלט האדם באדם<sup data-n=\"1199\">155</sup> לר\"ע ל\"ו כו' וכן כתיב כי גחלים אתה חותה על ראשו<sup data-n=\"1200\">156</sup> כו' משום דבירידה זאת שהמל' יורדת ומתלבשת בחיצוני' גורמת להם מיתה ואבדון כו' וכמ\"ש במ\"א שזהו ענין הברורי' כו'. וא\"כ בהכרח לומר שיש בזה הבירור מבחי' הגבורו' והדינין מאחר שהורג ליניקו' החיצוני' ופוסק חיותם ממקור חוצבם כו'. וזהו בחי' ה\"ג דרוח צפון המתעורר במל' בחצות לילה ובטש בגדפוהי דתרנגולא<sup data-n=\"1201\">157</sup> למטה וכידוע שזהו ענין הנותן לשכוי בינה<sup data-n=\"1202\">158</sup>, כי שרש ה\"ג הללו במל' באין ונמשכין מלמעלה מעלה דהיינו מבחי' ה\"ג שביסוד דבינה דאצי' וע\"כ אמר הנותן לשכוי בינה דוקא וכמ\"ש במ\"א וד\"ל. ואחר שבחי' ה\"ג הללו פוסקי' יניקו' החיצוני' ועולין מהם בחי' הטוב שבהם לקדוש' האלקי' הנה הם עולין בשיר וזמרה ע\"ד דמיון המנצח המלחמה כשמביא שלל האויב שמרנן ומזמר בשמחה כו' וד\"ל.",[["1194","150","<b>רפ\"ח. . טר\"ף</b>: ראה פע\"ח (שער ק\"ש שעהמ\"ט) שט\"ז, פ\"ה. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקלא. מאמרי אדה\"א בראשית ע' קמו. וש\"נ."],["1195","151","<b>חיל בל\"ע ויקיאנו</b>: איוב כ, טו. ראה גם לעיל פ' שמות מ, ג. וש\"נ."],["1196","152","<b>ואכלו את חוק\"ם</b>: ויגש מז, כב."],["1197","153","<b>נערות\"י' הן ההיכלות. . ז' הנערות</b>: ראה זהר אחרי נח, סע\"ב ואילך ובהגהות מהרח\"ו שם. עמק המלך (שער שעשועי המלך) ש\"א פ\"ד (ג, ב). (שער עולם התהו) ש\"ו, ספס\"ד (לו, ג)."],["1198","154","<b>זה</b>: ע\"כ נדפס בתו\"ח. ומכאן ואילך ניתוסף מגוכתי\"ק."],["1199","155","<b>אשר שלט האדם באדם</b>: קהלת ח, ט. ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' עג. לעיל פ' שמות ל, ד הערה 174."],["1200","156","<b>כי גחלים אתה חותה על ראשו</b>: משלי כה, כב. ראה גם ע\"ח (שער קליפת נוגה) שמ\"ט, פ\"ח. ביאוה\"ז חוקת צו, ב."],["1201","157","<b>ובטש בגדפוהי דתרנגולא</b>: ראה גם לעיל פ' וארא עד, ד. וש\"נ."],["1202","158","<b>הנותן לשכוי בינה</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"ב ע' שצד ואילך."]]],[2300550471,"<b>ומעתה</b> יתבארו כל דברי המאמר בפרט. דוד מלכא קם ושבח ואודי למלכא קדישא פי' בחי' מל' דאצי' בעלותה מהיכלו' החיצוני' אחר שנשלמו הברורי' דרפ\"ח כנ\"ל אזי נא' חצות לילה אקום להודות לך<sup data-n=\"1203\">159</sup> פי' להודו' לשם הוי' דוקא שנק' מלכא קדישא כידוע, לפי ששם אלקים שמלך על גוים כנ\"ל נמתק ונתעלה ע\"י הברורי' דרפ\"ח. וז\"ש יודוך עמים אלקים כו' ומפרש הטעם דבההוא שעתא דרוח צפון אתער פי' ה\"ג דמל' שפוסק חיו' הטוב מן החיצונים ומעלה אותם למעלה כנ\"ל, הוה בטש באינון נימין דכינורא פי' הכינור הזה עם הנימין היינו בחי' כלי השיר והזמר שהמל' מרנן ומזמר בעלותה הטר\"ף כמ\"ש אלקי' אל דמי לך כו' למען יזמר\"ך כבוד<sup data-n=\"1204\">160</sup> כו' וכמ\"ש במ\"א, ויש בכינור זה י' נימין כמ\"ש עלי עשו\"ר<sup data-n=\"1205\">161</sup> ועל הרוב הוא של ז' נימין<sup data-n=\"1206\">162</sup> נגד ז' מדו' שכלולי' בהם הברורי' דע' שרים כו'. ואמנם ה\"ג הנ\"ל המבררי' הן הן המעוררי' השיר בנימין של הכינור הזה וכמארז\"ל כינור הי' תלוי<sup data-n=\"1207\">163</sup> למעלה ממטתו של דוד בשעה שהי' רוח צפונית מנשב בו הי' מנגן מאליו כו' כי השיר בהעלם הוא ע\"י בחי' ה\"ג הללו דוקא וכמ\"ש במ\"א בביאור המאמר רננה ברמשא<sup data-n=\"1208\">164</sup> כו' וד\"ל. ומה הוה א' יודוך עמים אלקי' לפי שכל הע' שרי\"ם נבררי' ועולין ונכללי' בקדוש' כנ\"ל וזהו יודוך עמי\"ם אלקים לפי שכל אוה\"ע מקבלי' משם אלקים כנ\"ל וד\"ל.\n<b>ת\"ח</b> בשעתא דקודב\"ה אתער לכל אינון רתיכין למיהוי לון טרפא כמ\"ש ותקם כו' פי' בא לפרש למה א' שירה זאת דיודו\"ך עמי\"ם דוקא ולא שיר אחר, ואמר משום דהמל' שנק' קודב\"ה בבי\"ע אתער לכל המרכבו' העליוני' ליתן להם טרף ומזון יתר מכפי המדה הקצובה להם עפ\"י מאמר קו המדה כנ\"ל. וז\"ש ותקם בעוד לילה ותתן טר\"ף לבית\"ה בפנימי' וח\"ק לנערותי\"ה בהיכלו' החיצוני' כנ\"ל וכמ\"ש הכפירי\"ם שואגים לטר\"ף<sup data-n=\"1209\">165</sup> כו'. כדין כולהו פתחי ואמרי פי' כל המרכבות העליונות דבי\"ע שמחים לקראת זה האור והשפע האלקי' המגיע להם מבחי' מל' דקדושה בעלותה עם הטר\"ף שלקחה מיד החיצוני', ואמרו כו' אלקי\"ם יחננו ויברכנו יאר פניו כו' פי' שם אלקי' המברר ברורי' דרפ\"ח כידוע דשם ב\"ן דוקא הוא המברר, כי הוא יחננ\"ו בחק ומזון יתר מכפי המדה וזהו ויברכנ\"ו ויאר פניו אתנו סלה כי לולי זה הטרף כבר היה כלה שיעור מזון חיותם מלמעלה כנ\"ל, וע\"כ אמר יאר פניו אתנו סלה דוקא כי",[["1203","159","<b>חצות לילה. . לך</b>: תהלים קיט, סב."],["1204","160","<b>אלקי' אל דמי. . למען יזמר\"ך כבוד</b>: תהלים פג, ב. ל, יג. ראה זהר (היכלות) פקודי רנו, ב. תרומה קמ, רע\"א. וישלח קעח, ב. לך עז, ב. פו, ב. לעיל פ' בשלח קמא, ד."],["1205","161","<b>בכינור זה י' נימין כמ\"ש עלי עשו\"ר</b>: תהלים צב, ד. ראה ערכין יג, ב. סידור שחרית לשבת קפט, סע\"א ואילך. פיה\"מ פב, א ואילך."],["1206","162","<b>בכינור. . ועל הרוב. . ז' נימין</b>: ראה בהערה שלפנ\"ז."],["1207","163","<b>כינור הי' תלוי</b>: ראה ברכות ג, ב. לעיל פ' בא פח, ג. וש\"נ."],["1208","164","<b>רננה ברמשא</b>: זהר ויחי רכט, ב. ראה גם סידור שער החנוכה רעח, ב. תו\"א מקץ לז, סע\"א."],["1209","165","<b>הכפירי\"ם שואגים לטר\"ף</b>: תהלים קד, כא."]]],[2300550486,"כל נצח סלה כו' אין לו הפסק<sup data-n=\"1210\">166</sup> כו' וד\"ל. כד רוח צפון אתער ונשיב א' לדעת בארץ דרכך בכל גוים ישועתך כו' פי' רוח צפון זה הוא המעורר להניצוצי' שנפלו גם בתחתית שאול שיעלו משם כענין הכרוזין שבת קול מכרזת בכל יום שובו<sup data-n=\"1211\">167</sup> בנים שובבים<sup data-n=\"1212\">168</sup> וכמ\"ש במ\"א, והוא ענין כ\"ח המעלה מ\"ן בתחתוני'. וע\"כ אמר כד רוח צפון אתער משום דדוקא מבחי' הגבורו' דצפון [יבא] התעוררו' זאת וכמ\"ש שמאלו תחת לראשי<sup data-n=\"1213\">169</sup> כו' וכמ\"ש במ\"א. ומה אומר לדעת בארץ דרכך בכל גוים ישועתך גם הגוים יכירו וידעו בה' ובדרכיו מצד העלא' בחי' [הטוב] שבהם וזהו יודו\"ך עמים ממש כו' וחלק הרע שלא יוכל לעלות מהם ימות ונופל למטה וזהו עיקר ענין הברורי' כידוע וד\"ל. וזה המאמר הביא כדי להבין מזה תוס' ביאור [לענין יתרו] כהן און לפי שהכל ענין א' הוא לברר יניקו' החיצוני' שנאחזי' בשם אלקי' כנ\"ל וד\"ל.",[["1210","166","<b>כל נצח סלה. . הפסק</b>: ראה ערובין נד, א."],["1211","167","<b>שבת קול. . בכל יום שובו</b>: ראה זהר נשא קכו, א. הנסמן לעיל פ' וארא עח, ג."],["1212","168","<b>שובו בנים שובבים</b>: ירמי' ג, יד. כב."],["1213","169","<b>שמאלו תחת לראשי</b>: שה\"ש ב, ו. ראה גם סידור שחרית לו, א."]]],[2300550045,"<b>בעזר\"ה ליל שבת פ' יתרו</b>\n<span data-k=\"pg\">ת</span> ּ<b>להבין</b> מאמר הזהר בפ' יתרו (דס\"ז ע\"ב) ת\"ח ברזא דשמא<sup data-n=\"1214\">2</sup> קדישא<sup data-n=\"1215\">1</sup> איהו מלך וכהן כו' אית מלך לעילא דאיהו רזא דקדש הקדשים ואיהו מלך עילאה ותחותי' אית כהן רזא דאור קדמאה דמשמש קמי' ואקרי כה\"ג סטרא דימינא. אית מלך לתתא כגוונא דמלך עילאה ותחותי' כהן דמשמש לי' רזא דמיכאל כהנא רבא וכו'. בסט\"א אית מלך ואקרי מלך זקן וכסיל<sup data-n=\"1216\">3</sup> ותחותי' כהן און כמ\"ש ויאמר אפרים [אך] עשרתי<sup data-n=\"1217\">4</sup> מצאתי און לי כו'. בסטר שמאלא ודא הוא דאמרה רחל בן אוני<sup data-n=\"1218\">5</sup> ויעקב קרא לו בנימין ולא לסטר שמאלא כו'. וכיון דהאי מלך וכהן אתכפיין ואתברו ואודו קמי' קוב\"ה אסתלק יקרא דקוב\"ה ביקרי' על כולא עילא ותתא, ע\"כ. (ושם מסיים בדף שלאחריו ע\"א) א\"ר אבא האי כהן און לא כתיב ביתרו כתיב<sup data-n=\"1219\">7</sup> כהן מדין<sup data-n=\"1220\">6</sup> כתיב א\"ל ת\"ח חמוהי דיוסף כהן און<sup data-n=\"1221\">8</sup> אקרי ולבתר חמוהי דמשה כהן מדין רזא דא דאשת מדנים ומשה ויוסף ברזא חדא קיימי רזא דא ו\"ו תרין כחדא ע\"כ.",[["1214","2","<b>ת\"ח ברזא דשמא קדישא</b>: לשון הזהר בשינויים. וראה גם הלשונות בזהר במאמר הקודם במקומות המתאימים."],["1215","1","<b>להבין מאמר הזהר. . ת\"ח ברזא דשמא קדישא</b>: מאמר זה הוא הנחת כ\"ק אדמו\"ר האמצעי ממאמר אביו כ\"ק אדה\"ז מליל שבת פ' יתרו תקס\"ה. וראה גם ד\"ה שנדפס לפנ\"ז. ראה עוד ע\"ד מאמר זה להלן ברשימת הכת\"י (ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות)."],["1216","3","<b>מלך זקן וכסיל</b>: קהלת ד, יג."],["1217","4","<b>ויאמר אפרים [אך] עשרתי</b>: הושע יב, ט."],["1218","5","<b>דאמרה רחל בן אוני</b>: וישלח לה, יח."],["1219","7","<b>כתיב</b>: בזהר וא: ליתא. ב: כבפנים."],["1220","6","<b>ביתרו. . כהן מדין</b>: שמות (ב, טז). ג, א. יתרו יח, א."],["1221","8","<b>חמוהי דיוסף כהן און</b>: מקץ מא, מה. נ."]]],[2300550077,"<b>הנה</b> פי' רזא דשמא קדישא היינו בחי' מל' דא\"ק להיות שנחשב א\"ק עדיין מבחי' הא\"ס<sup data-n=\"1222\">9</sup> כידוע, אך בחי' מל' שבו נק' שמא קדישא וכענין המאמר קודם שנברא העולם<sup data-n=\"1223\">10</sup> הי' הוא ושמו בלבד כמ\"ש במ\"א וד\"ל. ואיהו מלך פי' כי בחי' מל' שבעליון נעשה כתר לתחתון<sup data-n=\"1224\">11</sup> בכל מקום כידוע, וגם כאן הנה ידוע דמבחי' מל' דא\"ק נעשה בחי' הכת\"ר של הנאצלים והוא בחי' עתיק וא\"א. ונמצא שהוא בחי' ממוצע בין עולם הא\"ס לעולם הנאצלים כי יש בו מבחי' תחתונה שבא\"ס שהוא מל' דא\"ק הנק' סוף עולמות דא\"ס כו', וגם הוא שרש וראש לכל הנאצלים בבחי' הכת\"ר כו', ע\"כ בו ועל ידו מתחברים תמיד עולמות דא\"ס בעולם הנאצלים כי הוא מקבל השפע מעולם הא\"ס ומביא וממשיך לעולם הנאצלים. וע\"כ נק' בשם מלך עילאה כמו שמפרש בסמוך אית מלך לעילא כו' מב' טעמים, א' להיותו בחי' מל' דא\"ק, והב' מפני שהוא השרש והמקור לכל הנאצלים כנ\"ל ולהיות שהוא למעלה הרבה מהם נק' בשם מלך עילאה וד\"ל.\n<b>וכהן</b> דמשמש כו' היינו כמ\"ש בסמוך אית מלך לעילא רזא דקדה\"ק כו' וכהן תחותי' רזא דאור קדמאה [כו'], פי' רזא דקדש הקדשים הנה הוא בחי' כת\"ר הנ\"ל ונק' קדה\"ק, כידוע שקדשים הם בחי' חו\"ב<sup data-n=\"1225\">12</sup> והכתר עליהן נק' קדה\"ק<sup data-n=\"1226\">13</sup>, וכהן תחותי' הוא בחי' חכ' דאצי' כידוע דחח\"ן מימין<sup data-n=\"1227\">14</sup> והרי בחי' הקו דחכ' וחסד משמש תחות הכתר עליו לימין ועד\"מ המשמש לרבו שגורם עי\"ז תוס' שפע וברכה מרבו ואדונו. כמו\"כ בעבודה בכהן זה שבקו החכמה בבחי' עליי' מ\"ן גורמת תוספת הארה וההמשכה מבחי' כת\"ר לחכמה תחלה וממנו מסתעפ' ההמשכה לכל מה שלמטה הימנו בקוין כו', וע\"כ נק' אור קדמאה לפי שהוא הראש והראשון כידוע. ואקרי כהן גדול לסטר ימינא, פי' גדול לפי שהוא מקור למדת החסד שלמטה ממנו וכידוע דהחכ' מקור כל החסדים<sup data-n=\"1228\">15</sup> וכמ\"ש החכמה תחי'<sup data-n=\"1229\">16</sup> כו' לפי שכל מה ששכל אדם רחב יותר יותר יסבול כל הדינים<sup data-n=\"1230\">17</sup> והקטרוגי' כו' כמ\"ש במ\"א, ולכך נק' החכ' אבא עד\"מ האב לבנו שהוא בתכלית <span data-k=\"pg\">802</span> ּ החסד עליהם<sup data-n=\"1231\">18</sup> כו', ולכך נק' גדול לפי שחסדו מתפשט בהתרחבו' [כפי התרחבות] של החכ' משא\"כ החסד שלמטה הימנו שנמשך בצמצום ולא בהתרחבות אינו גדול כו', וזהו לסטר ימינא דוקא לפי שחח\"ן מימין וד\"ל.",[["1222","9","<b>א\"ק עדיין מבחי' הא\"ס</b>: ראה גם מאמרי אדה\"ז תקס\"ב ח\"ב ע' תמד. תקס\"ה ח\"א ע' של (נו\"א). מארז\"ל ע' קד. ע' ער. דר\"מ ע' קסו."],["1223","10","<b>קודם שנברא העולם</b>: ראה פדר\"א פ\"ג. לעיל פ' וארא נג, ב. וש\"נ."],["1224","11","<b>מל' שבעליון נעשה כתר לתחתון</b>: ראה ע\"ח (שער כסה\"כ) שמ\"ו, פ\"ב. פ\"ה. הנסמן במאמרי אדה\"א בראשית ע' לז. לקו\"ב לשעה\"י (קה\"ת תשנ\"ה) ע' קעו."],["1225","12","<b>שקדשים הם בחי' חו\"ב</b>: נסמן לעיל רסט, ג."],["1226","13","<b>והכתר. . קדה\"ק</b>: נסמן לעיל שם."],["1227","14","<b>דחח\"ן מימין</b>: נסמן לעיל שם."],["1228","15","<b>דהחכ' מקור כל החסדים</b>: ראה זהר ואתחנן רסב, סע\"א. לעיל פ' בא צד, ד הערה 390."],["1229","16","<b>החכמה תחי'</b>: קהלת ז, יב."],["1230","17","<b>ששכל אדם רחב. . יסבול כל הדינים</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קצה. ע' קצו ואילך. ענינים ע' פו. לקמן פ' תצוה שסא, א."],["1231","18","<b>לבנו. . עליהם</b>: כ\"ה גם בהכת\"י."]]],[2300550109,"<b>ואית</b> מלך לתתא כגוונא דמלך עילאה כו', הענין הוא כי ידוע דמל' דאצי' נעשה כת\"ר לבריאה<sup data-n=\"1232\">19</sup> והוא ג\"כ בחי' ממוצע בין אצי' לבריאה כי הוא [בחי'] התחתונה שבאצי' ושרש וראש לכל העולמות הנפרדים דבי\"ע ונק' עתיק דבריאה<sup data-n=\"1233\">20</sup> כידוע, וע\"כ הוא כגוונא דמלך עילאה שהוא בחי' מל' דא\"ק הנ\"ל והיינו שע\"י מתחבר שפע אצי' בבי\"ע והיו לאחדים כנ\"ל וד\"ל. ותחותי' כהן משמש לרזא דמיכאל כהנא רבא כו', פי' מיכאל הוא בחי' חכ' תתאה שבמל' דאצי' יש י\"ס ובחי' הכת\"ר נק' מלך תתאה ובחי' החכ' שע\"י תצא אור השפע לכל העולמות נק' כהן הדיוט בכלל לפי שהוא ראש לשועלים בעולמות הנפרדי' יש מאין כמ\"ש ומשם יפרד<sup data-n=\"1234\">21</sup> כו'. וכידוע שגם הנשמות שבג\"ע העליון הרי הם בחי' בריאה מוגבלת בבחי' יש מאין בכל<sup data-n=\"1235\">*22</sup> הנבראי' משא\"כ בבחי' האצי' שהוא בחי' אלקות ממש וגם בחי' הכלים דשם בחי' אלק[ו]' הם כמאמר דאיהו וחיוהי וגרמוהי חד בהון<sup data-n=\"1236\">22</sup> כו' כמ\"ש במ\"א וד\"ל. וזהו תחותי' כהן דמשמש לי' להשפיע ולהביא אור החסד בכל ההשתלשלו' דבי\"ע, ועכ\"ז נק' מיכאל כהנא רבא לגבי הנבראים אע\"פ דלגבי האצי' נק' כהן הדיוט מטעם הנ\"ל וד\"ל. והוא אותו מיכאל כהן גדול שמקריב נשמות<sup data-n=\"1237\">23</sup> ע\"ג המזבח כידוע במאמרז\"ל וד\"ל.\n<b>בסט\"א</b> אית מלך ואקרי מלך זקן וכסיל כו', הנה ידוע דאת זלעו\"ז עשה [ה]אלקי'<sup data-n=\"1238\">24</sup> ובסט\"א יש ג\"כ בחי' מלך וכהן ככל הנ\"ל, והנה ידוע דבחי' כת\"ר דקליפה מתחיל מבחי' אחוריים דנוק'<sup data-n=\"1239\">25</sup> דקדושה והוא אקרי מלך זקן וכסיל כו' לפי שהוא שרש וראש לכל ההשתל' החיצוני' שבעולמות דבי\"ע כידוע. ותחותי' רזא דכהן און כו', פי' און יש בו ב' ענינים הא' כפשוטו שהוא לשון כח המוליד כמו כחי וראשית אוני<sup data-n=\"1240\">26</sup> וכן מ\"ש רחל בן אוני<sup data-n=\"1241\">27</sup> כו' והב' לשון אנינות ואבילות כו'.\n<b>וביאור</b> הדברים, הנה ידוע דבחי' יסוד הוא כאשר יבא אור השפע בבחי' גילוי ממש ונק' כנישו דכל נהורין<sup data-n=\"1242\">28</sup> כמו עד\"מ המדות כמו שהן בלב מבלתי הרגשה עדיין לא נשפע מהם מאומה למחשבה ולדיבור אך כשהן נרגשים בלב אז הן נשפעו למחשבה לחשוב מה שחפץ בלבו כו', והוא ע\"י בחי' יסוד שהוא כח המשפיע<sup data-n=\"1243\">29</sup> כמ\"ש במ\"א. ולמעלה יובן ג\"כ שהוא בחי' יסוד ז\"א ונק' בשם צדיק ח\"י עלמין<sup data-n=\"1244\">30</sup> כידוע בזהר ומבואר בכמה מקומות דכל חידו וברכאן שריין בהאי צדיק<sup data-n=\"1245\">31</sup> ח\"י עלמין כו',",[["1232","19","<b>דמל' דאצי' נעשה כת\"ר לבריאה</b>: ראה ע\"ח (שער כסה\"כ) שמ\"ו, פ\"ב. פ\"ה. פ\"ו."],["1233","20","<b>דמל' דאצי'. . עתיק דבריאה</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"ב."],["1234","21","<b>ומשם יפרד</b>: בראשית ב, י."],["1235","*22","<b>בכל</b>: אוצ\"ל: ככל."],["1236","22","<b>דאיהו וחיוהי וגרמוהי חד בהון</b>: ראה ת\"ז בהקדמה (ג, ב). ראה גם מאמרי אדה\"ז על מארז\"ל ע' רצב (כמא' אליהו ז\"ל)־ אגה\"ק ס\"כ. מאמרי אדה\"א ויקרא ח\"ב ע' תנג בהערה."],["1237","23","<b>מיכאל. . שמקריב נשמות</b>: ראה גם לעיל פ' שמות ה, א. וש\"נ."],["1238","24","<b>דאת זלעו\"ז עשה [ה]אלקי'</b>: נסמן לעיל רנא, ג."],["1239","25","<b>כת\"ר דקליפה. . אחוריים דנוק'</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"ג. לקמן רעו, ג."],["1240","26","<b>כחי וראשית אוני</b>: ויחי מט, ג."],["1241","27","<b>וכן מ\"ש רחל בן אוני</b>: רקאנטי ויצא ל, כד. בחיי שם ל, כג."],["1242","28","<b>יסוד. . כנישו דכל נהורין</b>: ראה גם לעיל פ' בשלח ריט, ג. וש\"נ."],["1243","29","<b>יסוד שהוא כח המשפיע</b>: ראה גם סידור שחרית נ, א ואילך. שער הסוכות רנח, ד."],["1244","30","<b>יסוד. . צדיק ח\"י עלמין</b>: ראה זהר (רע\"מ) פינחס רכז, א."],["1245","31","<b>וברכאן שריין בהאי צדיק</b>: ראה זהר ויחי רלא, רע\"א. רמז, ב. לך פז, ב."]]],[2300550141,"והיינו מפני שבבחי' כלות השפע דוקא אז יומשך מבחי' התענוג<sup data-n=\"1246\">32</sup> העליון ומתלבש בהשפעה זו בבחי' יסוד ועד\"מ הזווג גשמי'<sup data-n=\"1247\">33</sup> כמ\"ש במ\"א באריכות. וכמו\"כ בהשפעת צדיק ח\"י עלמין להוליד נשמות חדשות בבי\"ע כמ\"ש אור זרוע לצדיק<sup data-n=\"1248\">34</sup> כו', מלובש בו מבחי' עונג העליון דבחי' יסוד דעתיק כו', וזהו ענין צדיק כתמר יפרח<sup data-n=\"1249\">35</sup> כארז בלבנון ישגה פי' מפני ששרש יסוד ז\"א הוא אחוז וקשור ביסוד דע\"י הנק' לבנון כידוע וד\"ל. וא\"כ בשעת אור השפע דקדושה בבחי' יסוד אז כל חידו וברכאן <span data-k=\"pg\">תא</span> ּ ממקור התענוג העליון נמצא בו מטעם הנ\"ל והוא בחי' כח המוליד בקדושה שידוע שיש בו מבחי' הארת א\"ס<sup data-n=\"1250\">36</sup> שהרי הוא מרבה השפע עד אין קץ ושיעור כו', וגם הרי הוא מוליד נשמות חדשות לגמרי שלא היו עדיין בהשתלשלו' והוא לפי שיש בו דוקא הארת בחי' העונג העליון שהוא הממוצע בין המאציל לנאצלים שהוא למעלה מן ההשתל' כנ\"ל וד\"ל. וזהו מוכרח בכל ההשתל' מעולם לעולם כמו מעולם הא\"ס לעולם הנאצלים הוא בחי' כהן עילאה הנק' אור קדמאה הנ\"ל היינו דוקא ע\"י בחי' יסוד דאבא שמביא השפעה לנאצל כו', ועד\"ז הוא בחי' כהן תתאה הנ\"ל שמביא השפע לבי\"ע והוא פי' דמשמש לי' הנז' למעלה. אבל בהיכלות הקליפות דאת זלע\"ז עשה האלקי' מאחר שנק' לע\"ז הרי הן מנגדים ממש ומוכרח שבהם הוא בהיפוך מן הקדושה כו', והענין הוא להיות ידוע דגם בקליפות נמשך בחי' כהן מבחי' חכ' דקליפה והוא נק' כהן און כו', וכמ\"ש יתפרדו כל פועלי און<sup data-n=\"1251\">37</sup> שהוא ענין עומק מחשבת דבר רע כמ\"ש ואיש און מחשבותיו<sup data-n=\"1252\">38</sup> כו' וכתיב לא הביט און ביעקב<sup data-n=\"1253\">39</sup> כו' כי בקליפו' החכמה אינה אמיתית רק נק' ערמה<sup data-n=\"1254\">40</sup> ומרמה כמ\"ש במ\"א דזהו שרש ענין חכמ' דקליפות. והנה ערך הערמומי' הוא לפי ערך אמיתי' החכמה וכמ\"ש אני חכמה שכנתי ערמה<sup data-n=\"1255\">41</sup> כו', ולכך נק' כהן און ובחי' יסוד דחכמה דקליפה הוא אשר מביא ההשפעה לכל ההשתל' בהיכלות החיצוני' כו', וזהו תחותי' משמש כהן און וד\"ל.\n<b>והנה</b> בסמוך יתבאר בסוף המאמר הנ\"ל דחמוהי דיוסף אקרי כהן און כו' דבכאן מיירי בבחי' יסוד ז\"א ולא בבחי' יסוד דאבא כו'. וזהו שא' כאן דהמנגד וההיפוך לבחי' יסוד ז\"א דקדושה שהוא בחי' יוסף<sup data-n=\"1256\">42</sup> הוא כהן און והוא לסטר שמאלא כו' והה\"ד ויאמר אפרים כו', פי' מה שבבחי' יסוד ז\"א דקדושה הנ\"ל הוא בכל חי[ד]ו וכל ברכאן כו' לפי שנמשך ומלובש בו מבחי'",[["1246","32","<b>כלות השפע. . התענוג</b>: ראה גם לעיל ריט, ד. וש\"נ."],["1247","33","<b>ועד\"מ הזווג גשמי'</b>: ראה גם לעיל רח, א. וש\"נ."],["1248","34","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["1249","35","<b>צדיק כתמר יפרח</b>: תהלים צב, יג. ראה גם לעיל פ' בשלח רח, א. וש\"נ."],["1250","36","<b>כח המוליד. . הארת א\"ס</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' שג. תקס\"ו ע' קח. מארז\"ל ע' קסו. ביאוה\"ז ד, ב. נז, ב. שע\"ת נט, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תקכז. וש\"נ."],["1251","37","<b>יתפרדו כל פועלי און</b>: תהלים צב, י."],["1252","38","<b>ואיש און מחשבותיו</b>: ישעי' נה, ז."],["1253","39","<b>לא הביט און ביעקב</b>: בלק כג, כא."],["1254","40","<b>בקליפו' החכמה. . ערמה</b>: ראה גם תו\"ח נח עט, א ובהערה 1."],["1255","41","<b>אני חכמה שכנתי ערמה</b>: משלי ח, יב."],["1256","42","<b>יסוד ז\"א דקדושה. . יוסף</b>: ראה ע\"ח (שער הצלם) שכ\"ו, פ\"ג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקיז. ובהנסמן במ\"מ לשם. ביאוה\"ז ויחי כט, ב. ד."]]],[2300550173,"ענג העליון כנ\"ל, אבל ביסוד ז\"א דקליפה נהפוך הוא ששם הוא מקור כל העצבות והמ\"ש וע\"כ כל הדינים הקשים נמשכים משם כו'. וזהו פי' און מלשון אנינות ואבילות כו', והוא מפני ששרש יניקת החיצונים הוא למעלה מסטר שמאלא, פי' מבחי' הקו השמאל דבג\"ה<sup data-n=\"1257\">43</sup> והוא בא ונמשך מבחי' פסולת גבורות העליונות דקו השמאל כידוע ומבואר במ\"א והוא היפך השמחה והעונג שיש בבחי' יסוד ז\"א דקדושה הנ\"ל והוא מפני שאזלעו\"ז עשה כו'. וזהו ויאמר אפרים [אך] עשרתי הוא בחי' יסוד דקליפה שמתכנשין בו כל ההשפעות שמקבל ממלך זקן הנ\"ל מפסולת שפע האצי' וכו', מצאתי און לי פי' כח המוליד להוליד חדשות, אמנם מפני שהוא לסטר שמאלא הוא בא בבחי' אנינות ויגון היפך השמחה כו' וד\"ל. וזהו שאמרה רחל בן אוני מבחי' הגבורות דקו השמאל שהיו נאחזים בה בשעת מיתתה כו' ויעקב קרא לו בן ימין לסטרא דימינא הנ\"ל שבו מלובש בחי' עונג העליון כו' וד\"ל.\n<b>ועתה</b> יש להבין סוף סיום המאמר (בדס\"ח ע\"א) א\"ר אבא האי כהן און לא כתי' ביתרו כו', פי' וענין קושייתו הוא שהרי נתפרש במאמר הקדום בפי' כהן און <span data-k=\"pg\">804</span> ּ דלסטר שמאלא כו' שהוא המנגד באת זלעו\"ז כו' לבחי' יסוד דקדושה דלסטר ימינא, ומבואר למעלה דבחי' כהן דקדושה הוא בחי' יסוד דאבא כמ\"ש למעלה ותחותי' רזא דאור קדמאה כו' ובכהן דלתתא הוא רזא דמיכאל כו' שהוא ג\"כ בחי' חכמה שבמל' דאצי' וכנ\"ל. ואיך יתכן כך דהא האי כהן און לא כתיב ביתרו שהוא המנגד למשה בחי' יסוד<sup data-n=\"1258\">45</sup> אבא<sup data-n=\"1259\">44</sup> וביתרו כהן מדין כתיב ולא כהן און כו', והשיב לו ת\"ח חמוהי דיוסף כהן און אקרי כו' עד משה ויוסף ברזא חדא קיימא ו\"ו תרין כחדא, פי' ו\"ו תרין כחדא היינו בחי' יסוד אבא שמלובש בבחי' יסוד ז\"א<sup data-n=\"1260\">46</sup> דידוע שהמה ב' ווי\"ן וי\"ו רבתא וי\"ו זעירא, ומה שהן תרין כחדא עד\"מ הגשמי שאין קישוי אלא לדעת<sup data-n=\"1261\">47</sup> ומיד שמהרהר במוח שאז נמשך טפת אבא הרוחניות במוח תיכף ומיד יומשך ליסוד כו' והרי בקלקול כלי המוח לא יוליד כי המה תלוי' זב\"ז ומתאחדי' כאלו הן כלי אחד כמ\"ש במ\"א וד\"ל.\n<b>ומ\"ש</b> חמוהי דיוסף כהן און ולבתר חמוהי דמשה כהן מדין כו', הענין הוא דהמנגד דאת זלעו\"ז דיוסף בחי' יסוד ז\"א דקדושה כנ\"ל הוא בחי' [כהן און הנ\"ל שהוא ג\"כ] כח המוליד אלא שהוא בבחי' אנינות כנ\"ל והמנגד דאת זה לעו\"ז דמשה בחי' יסוד אבא דקדוש' אז הוא בחי' כהן מדין [וענין כהן מדין] ע\"ש אשת מדנים כו'. יובן ע\"פ הקדמה הידוע דאו\"א דקדושה הן נקראי' תרין ריעין<sup data-n=\"1262\">48</sup> דלא מתפרשין לעלמין, והטעם",[["1257","43","<b>הקו השמאל דבג\"ה</b>: נסמן לעיל רסט, ג הערה 19."],["1258","45","<b>למשה בחי' יסוד אבא</b>: ראה לקוטי שיחות שמות כרך ו ע' 244 ואילך."],["1259","44","<b>ביתרו שהוא המנגד. . יסוד אבא</b>: ראה לקו\"ת להאריז\"ל ר\"פ יתרו."],["1260","46","<b>ו\"ו תרין. . יסוד אבא. . ז\"א</b>: ראה רמ\"ז כאן."],["1261","47","<b>שאין קישוי אלא לדעת</b>: יבמות נג, סע\"ב. ראה גם תו\"א ויחי קה, סע\"ג. הנסמן לעיל פ' בשלח קמה, ב."],["1262","48","<b>דאו\"א. . תרין ריעין</b>: ראה זהר בשלח נו, א. ויקרא ד, א. לעיל פ' בא קכ, א. וש\"נ."]]],[2300550205,"שזיווגן תדיר<sup data-n=\"1263\">49</sup> להיות כי מבואר למעלה בענין רזא דקדש הקדשים כו' שבחי' הארת הכתר מאיר עליהם תמיד וידוע שיש בו מבחי' הארת הא\"ס שהוא בתכלית האחדות הפשוטה ע\"כ יחוד דאו\"א הם ביחוד בתמידות ג\"כ להיות תמיד בתכלית ביחוד, כי בחי' הא\"ס הוא להיות תכלית היחוד ותכלית האחדות היפוך הפירוד וההתחלקות כו' וע\"כ לא מתפרשין לעלמין מפני שהן קרובי' אל אור א\"ס שבכתר כו', משא\"כ באת זה לעו\"ז שלהם בחו\"ב דקליפ' הוא ההיפוך והמנגד לזה ממש כמ\"ש ומשם יפרד כו' דהיינו שיבא בהם בחי' הפירוד ו[ה]התחלקות בתכלית ולזה הטעם נק' כהן מדין בבחי' ריב ומדון<sup data-n=\"1264\">50</sup> והוא בחי' יסוד אבא דקליפה וגם נוק' דיליה נק' אשת מדנים וד\"ל. וזהו רזא דאשת מדנים שמקבלת מכהן מדין שהוא המנגד ממש למשה בחי' יסוד אבא דקדושה, וזהו שא' חמוהי דיוסף כהן און ולבתר חמוהי דמשה כו' כי בחי' יסוד ז\"א דיוסף נתברר תחלה מיניקת כהן און חמוהי ואח\"כ ממשה נתברר גם בחי' יסוד אבא מיניק' כהן מדין חמוהי דמשה, [ו]להיות כי יסוד אבא מתלבש אח\"כ ביסוד ז\"א כנ\"ל ע\"כ מסיים המא' דמשה ויוסף ברזא חדא קיימא ו\"ו תרין כחדא לאחר הבירור דוקא כנ\"ל וד\"ל. וזהו שאמר בסוף מאמר הראשון וכד האי מלך וכהן אתכפיין ואתברו אסתלק יקרא דקודב\"ה לעילא ותתא, פי' לעילא בבחי' יסוד אבא רזא דאור קדמאה הנ\"ל שנברר מבחי' כהן מדין ולתתא בחי' יסוד ז\"א שמוליד נשמות בבריאה כו' והוא רזא דמיכאל כו' שנברר מבחי' כהן און הנ\"ל וד\"ל.\n<span data-k=\"pg\">תב</span> ּ<b>ועם</b> כל הנ\"ל יובן הטעם שנקראת אשת [משה] צפורה<sup data-n=\"1265\">51</sup> ואשת יוסף אסנת בת פוטי פרע<sup data-n=\"1266\">52</sup> כהן און כו', דהנה ידוע דנוק' דקדושה הוא בחי' הדבור העליון וידוע שמקבלת השפע רק מבחי' אחוריים דיסוד ז\"א כו'. וביאור הדברים ידוע עד\"מ באדם התחתון הנה אנו רואים שאיזה דבר אהבה ותשוקה שבלב לא יוכל להביא בדבור ולפרש אותו היטב כמו שהוא בלבו ממש ואפי' במכתב באותיות הכתב, וגם כי רוצה להסביר הדבר ברבוי דברים וברבוי המכתב לא יוכל לפרש ולגלות כמו שהדבר הוא באמת בתוך לבבו אלא רק אפס קצהו יתגלה בדיבור וכתב והוא בחי' החיצוני' של אותו הדבר בלבד. אבל פנימית הלב שיש לו באותו הדבר שנתקע בו כו' לא יתגלה לעולם לא בדיבור ולא בכתב וא\"כ בחי' האותיות ותיבות הדבור שמקבלים השפע מן המדות שבלב [הנה] אין מקבלים רק מבחי' חיצוני' ואחוריים של הלב ולא מפנימיותו כלל, וזהו משל להבין למעלה שבחי' נוק' דקדושה מקבלת רק מבחי' אחוריי' דיסוד ז\"א שהוא אור השפע הבא מן המדות כנ\"ל לפי שאין השפע בא מהם רק בבחי'",[["1263","49","<b>דאו\"א. . שזיווגן תדיר</b>: ראה זהר (אד\"ז) האזינו רצ, ב. ע\"ח שער הכללים פי\"ג. מאמרי אדה\"א בראשית ע' שנו. וש\"נ. תו\"ח נח מו, ג הערה 25."],["1264","50","<b>מדין בבחי' ריב ומדון</b>: ראה לקו\"ת וספר הליקוטים (הובאו ב)רמ\"ז כאן. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' ש. מאמרי אדה\"א במדבר ח\"ה ע' א'תשלט."],["1265","51","<b>אשת [משה] צפורה</b>: שמות ב, כא. יתרו יח, ב."],["1266","52","<b>ואשת יוסף אסנת בת פוטי פרע</b>: מקץ מא, מה. נ."]]],[2300550237,"חיצוניות ואחוריי' כנ\"ל וד\"ל. והנה מאחר שהי' יוסף מרכבה לבחי' צדיק עליון בחי' יסוד ז\"א ע\"כ היתה לו אסנת לאשה בבחי' נוק' דקדושה אחר הבירור שנתבררה והעלה אותה מבית פוטיפר[ע] כהן און כנ\"ל לקבל מבחי' אור זרוע לצדיק דקדושה בבחי' אחוריים דיסוד ז\"א כו' וממנה הולך אח\"כ ירידת שפע הקדושה למטה, ואמנם אין הירידה אלא מבחי' האחוריים שלה והוא מבחי' שערות דנוק' כו' לפוטיפרע כהן און כידוע דאין יניקת החיצוני' רק מבחי' אחוריי' דנוק' דקדושה, וא\"כ כהן און דקליפה מקבל מתמצית ופסולת אחוריי' דאחוריי' בלבד, וגם בזאת השפע שמגיע לו מן הקדושה הנה הוא מתברר עי\"ז וכמ\"ש למעלה ונמצא פוטיפרע כהן און עדיין אינו בבחי' הקליפ' לגמרי אלא הוא בחי' ממוצע בין הקדושה לקליפה לאחר הבירור כו' וד\"ל.\n<b>ועד\"ז</b> יובן ג\"כ בענין צפורה אשת משה כו', דהנה ע\"ד הנ\"ל במדות שבלב שא\"א שיבאו פנימיות שלהן באותיות הדבור כו', כמו\"כ א\"א שיבא בחי' אור השכל והחכמה כמו שהיא מושכלת במוח ממש לידי גילוי אותיות גם באותיות מחשבת השכל הנק' אותיות השכל, והוא בחי' גילוי השכל כשישיג בבחי' דבר מה בהשגה במוח עד\"מ אדם חכם שיודע איזה שכל וסברא כבר והיא בכח שכלו תמיד וכשילמוד אותה או יהרהר בה הרי יבא אותו השכל והסברא לידי אותיות מחשבה והשגה במוח, הנה א\"א שיבא אור השכל ההוא במושג כמו שהוא ממש רק מלובש ממנו בהשגה רק בחי' החיצוני' והאחוריי' ממנו. והמופת לזה שהרי יוכל אדם לחשוב שכל וסברא פעמים רבות ולא יהי' כל העתים בסגנון א' במוח השגה אלא לפעמים כך ולפעמים כך בצירופים שונים ועכ\"ז אין השכל והסברא משתנה מחמת זה כלל כמו שיוכל האדם להסביר איזה שכל בכמה מיני לשון בלה\"ק או בשאר לשונות וכו' וכמ\"ש במ\"א, והכל ענין א' מפני שאין מאיר בהאותיות של השכל רק מבחי' החיצוני' ואחוריי' של השכל ולא מפנימיו' <span data-k=\"pg\">806</span> ּ (וע\"כ נק' האותיות בלשון תרגום<sup data-n=\"1267\">53</sup> כי המה מקבלים רק מבחי' אחוריים דחכ' כו' וכמ\"ש במ\"א וד\"ל). ונמצא האותיות של השכל הן בחי' אחוריי' דאחוריי' דחכמה עצמה מאחר שבאותיות של השכל אינו מאיר רק מבחי' החיצוניות והאותיות הן לבוש החיצוני' כי האותיות הן מתחלפים גם הן כו' וד\"ל.",[["1267","53","<b>האותיות בלשון תרגום</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' יג. ענינים ע' סו."]]],[2300550268,"<b>וכ\"ז</b> משל להבין למעלה בבחי' נוק' דאבא דאצי' הוא כמו עד\"מ בחי' אותיות השכל והוא מקבל מאור יסוד אבא רק מבחי' החיצוניות כנ\"ל וזהו בחי' אשת משה שנק' צפורה מלשון וענין צפור המצפצף כו' והוא בחי' אותיות השכל שמקבלים מבחי' משה יסוד אבא כו', וממנה הולך בירידת המדרגה אור שפע דקדושה למנגד דמשה והוא חותן משה כהן מדין הנ\"ל וגם הוא אינו מקבל רק מבחי' אחוריי' שלה כנ\"ל ונמצא בחי' כהן מדין מקבל רק מבחי' אחוריי' דאחוריים דחכמה דקדושה כו', וכ\"ז לאחר הבירור וכמ\"ש למעלה דמשה ויוסף ברזא חדא קיימא כו' שאינו אלא לאחר דאתכפיין האי מלך וכהן דבסט\"א ע\"י הבירור דכהן מדין וכהן און כנ\"ל וד\"ל. ועם הנ\"ל בצפורה אשת משה יובן המדרש דצפורה היתה תאומה של הבל<sup data-n=\"1268\">54</sup> ובה נתקנא קין<sup data-n=\"1269\">55</sup> כו' וידוע דהבל הי' משרש נשמת משה כי אותיות מש\"ה משה שת הבל<sup data-n=\"1270\">56</sup> כו' ע\"כ לקח משה לצפורה תאומה של הבל לו לאשה ובה ועל ידה הי' משה מברר הבירור כנ\"ל ותיקן בזה נשמת הבל ותאומתו וד\"ל.",[["1268","54","<b>דצפורה היתה תאומה של הבל</b>: ראה לקו\"ת להאריז\"ל יתרו יח, ב."],["1269","55","<b>תאומה של הבל ובה נתקנא קין</b>: ראה ב\"ר פכ\"ב, ז. זהר בראשית נד, ב. ע\"ח (שער אנ\"ך) שי\"ט, פ\"ז."],["1270","56","<b>אותיות מש\"ה משה שת הבל</b>: ראה ת\"ז תס\"ט (קיד, א)."]]],[2300550046,"<b>בעזר\"ה שבת פ' תבא</b>\n<b>ענין</b> קין והבל<sup data-n=\"1271\">1</sup>. הנה<sup data-n=\"1272\">2</sup> בספר לק\"ת להאריז\"ל בענין ערי מקלט בפ' שופטים כ[תוב] שם הטעם לערי מקלט לעתיד ג\"כ מפני שא\"א להיות הקץ עד שיכלו זרעו של הבל, וכל אותן בנ\"א שנהרגו בשגגה בהריגה ולא במיתת עצמן הן מזרעו של הבל וכמ\"ש דוד על אבנר הכמות נבל ימות אבנר<sup data-n=\"1273\">3</sup> כו' לפי שה[י'] מבחי' הבל ע\"ש. ואם זכו אחישנה<sup data-n=\"1274\">4</sup> לא זכו בעת\"ה כו' אבל בין כך ובין כך א\"א כ\"א עד שיכלה זרעו של הבל ע\"ש באריכות. הנה בתחלה יש להקדים בענין הרבוי של ההתחלקות שנמצא בעולמות שהוא בא מסיבת הגבורו' דוקא, וזהו מ\"ש וארב\"ה את זרעו<sup data-n=\"1275\">5</sup> ואתן לו את יצחק כו' וארב\"ה בגימ' יצחק<sup data-n=\"1276\">6</sup> כידוע וגם מבואר במ\"א לפי שבחי' הריבוי שהוא פי' ארבה את זרעו הוא נמשך ע\"י בחי' הגבורות דיצחק<sup data-n=\"1277\">7</sup> דוקא. וביאור הדברים הנה אנו רואים באמת רבוי מינים שונים מאד בעוה\"ז השפל ג\"כ ומזה נבין עד רום המעלות שבכל עולם לפי ערכו יש בחי' הרבוי וההתחלקו' לאין מספר כו', דהנה ד' חלקי העולם דצח\"מ כ\"א",[["1271","1","<b>ענין קין והבל</b>: מאמר זה נאמר ע\"י כ\"ק אדה\"ז בליל שבת פ' תבא תקס\"ה ונדפס בב' נוסחאות במאמרי אדה\"ז תקס\"ה ח\"ב ע' תתמג נוסח א' שנרשם ע\"י כ\"ק אדמו\"ר האמצעי והוא הנדפס כאן. ונוסח ב' — הנחת הר\"מ בן כ\"ק אדה\"ז בפתיחה ולהבין מ\"ש בלקו\"ת ע\"פ ואם ירחיב ה' את גבולך. מאמר זה קשור עם מאמר שאמר כ\"ק אדה\"ז בש\"פ שופטים שגם הוא נדפס במאמרי אדה\"ז תקס\"ה שם ע' תשצח בשני נוסחאות הנחת כ\"ק אדה\"א שמתחיל שלש ערים תבדיל לך. והנחת הר\"מ בפתיחה ואם ירחיב ה\"א את גבולך. וקיצור מכ\"ק אדמו\"ר מהר\"ש נדפס שם ע' א'מט. וראה גם אוה\"ת בראשית כרך ז ע' תתשסז ואילך. שיחת כ' מנ\"א תשי\"ב ס\"ג ואילך. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["1272","2","<b>ענין קין והבל הנה</b>: הו: (ו)הנה."],["1273","3","<b>הכמות נבל ימות אבנר</b>: שמו\"ב ג, לג."],["1274","4","<b>זכו אחישנה</b>: סנהדרין צח, א."],["1275","5","<b>וארב\"ה את זרעו</b>: יהושע כד, ג."],["1276","6","<b>וארב\"ה </b>[ד: ארבה]<b> בגימט' יצחק</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' ה בשם הלקוטי תורה — ראה שם טעמי המצות פ' שמיני. פע\"ח (שער הק\"ש) ש\"ח, פכ\"ח. מאמרי אדה\"א דברים ח\"ג ע' א'ל. וש\"נ. נ\"ך ע' סו. וש\"נ. סידור שער התקיעות רמז, א. תו\"ח תולדות קנב, ג. וישלח קפב, א."],["1277","7","<b>הריבוי. . הגבורות דיצחק</b>: ראה גם מאמרי אדה\"ז תקס\"ב שם."]]],[2300550078,"יש בו רבוא רבבות מינים שונים, כמו חלק הדומם הנה יש אבן ועפר ומתכת וכיוצא בזה<sup data-n=\"1278\">8</sup> רבבות מינים ממינים<sup data-n=\"1279\">9</sup> שונים, וכן חלק הצומח יש תבואות ואילנות ופירות ועשבים<sup data-n=\"1280\">10</sup> ובכאו\"א רבוא רבבות אופנים<sup data-n=\"1281\">11</sup> ממינים שונים כו', וכן בחלק החי דגים ועופות ובהמות וחיות ובכאו\"א רבבות מינים ממינים שונים<sup data-n=\"1282\">12</sup> לאין שיעור, וכן במדבר יש רבבות מינים בכ\"א<sup data-n=\"1283\">13</sup> שונים זמ\"ז בדעותיהם ובמדותיהם כו'. וע\"ד כ\"ז יובן בעולם העליון מעולם הזה השפל דגם שם בהכרח לומר שיש כמו כל בחי' הרבוי <span data-k=\"pg\">תג</span> ּ הזה ממש מאחר דעולם הרוחני כמו עולם הגלגלים והמזלות הוא בחי' המשפיע לדצח\"מ הגשמי' הרי בהכרח שימצא במשפיע כל פרטי אופני הריבוי שבמקבלי' כו', ועד\"ז מעילה לעילה כי גבוה מעל גבוה<sup data-n=\"1284\">14</sup> כו' ועד רום המעלות כן הוא בחי' הרבוי וכמו אפי' בג\"ע העליון שימצא בו ריבוי הנשמות ומלאכים ברבבות מדרגות שונות וכן חלקי הדצח\"מ דשם המה בבחי' הריבוי מאד וכמ\"ש היש מספר לגדודיו<sup data-n=\"1285\">15</sup> כו' ובכל היכל ועולם יש כמה רבבות מחלק הדצ\"ח דשם כנ\"ל וע\"ד שאנו רואים כאן בעוה\"ז השפל ממש וד\"ל. והנה מ\"ש וארב\"ה את זרעו כו', פי' ע\"י בחי' מדת הגבורה והצמצום דוקא הוא בא ונמשך הריבוי להתחלקות פרטיות מעילה לעילה עד אין שיעור כנ\"ל הוא מטעם שטבע הגבורות לחלק ולהרבות חלקים עד אין שיעור כנראה בחוש שטבע האש לפרר<sup data-n=\"1286\">16</sup> לחלקים כו', וכן כמו חמימות התאוה שהוא מעורר הרבוי של התחלקות הטפות<sup data-n=\"1287\">17</sup> זרע ולהיות נובע כמעיין מבלתי יופסק וכמ\"ש במ\"א. כך עד\"מ מבחי' הגבו' עליונות דאצי' דוקא בא סיבת ההתהוות בעולמות בבחי' הרבוי וההתחלקו' וכמ\"ש אתה פוררת בעזך ים<sup data-n=\"1288\">18</sup> כו' שהפירור והפירוד לחלקים רבים כנ\"ל הוא מפני מדת עוזו שהן הן גבורותיו וכמ\"ש להודיע לבנה\"א גבורותי\"ו<sup data-n=\"1289\">19</sup> ואז ממילא מתפרד<sup data-n=\"1290\">20</sup> השפע בריבוי כנ\"ל, ובזה נעשה כבו\"ד הד\"ר מלכות\"ו כי אין מלך בלא ריבוי עם<sup data-n=\"1291\">21</sup> דוקא וזהו עיקר הד\"ר כבו\"ד מלכותו וכמ\"ש ברו\"ב עם הדרת מלך<sup data-n=\"1292\">22</sup> ברו\"ב ע\"ם דוקא וד\"ל.\n<b>והנה</b> כתיב עושה השלום במרומיו<sup data-n=\"1293\">23</sup> כו' וכידוע מארז\"ל דעושה שלום בין מיכאל וגבריאל שזה שר של אש וזה שר של מים ואין מכבין זא\"ז כו', וזה לכאורה יפלא מהיכן יוכל להיות השלום בין שני הפכים כאלו אש ומים כו'. אך הענין הוא דיש בחי' צמצום שאחריו נמשך בחי' הקו וחוט כו' והוא מבחי' הגבורות דוקא כנ\"ל, ואמנם לפני הצמצום הזה הראשון אין שם",[["1278","8","<b>וכיוצא בזה</b>: דו: כו' ובכאו\"א."],["1279","9","<b>ממינים</b>: שם ליתא."],["1280","10","<b>ועשבים. . ריבוא רבבות</b>: ראה גם לעיל פ' וארא ס, ב ובהערה 35."],["1281","11","<b>רבוא. . אופנים</b>: ד: יש. . מדריגות ואופנים."],["1282","12","<b>ממינים שונים</b>: דו: ליתא."],["1283","13","<b>בכ\"א</b>: ד: בנ\"א. ו: ליתא."],["1284","14","<b>כי גבוה מעל גבוה</b>: קהלת ה, ז."],["1285","15","<b>היש מספר לגדודיו</b>: איוב כה, ג."],["1286","16","<b>שטבע האש לפרר</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תרכד. וש\"נ."],["1287","17","<b>חמימות התאוה. . התחלקות הטפות</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' ד ואילך."],["1288","18","<b>אתה פוררת בעזך ים</b>: תהלים עד, יג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תצח. וש\"נ."],["1289","19","<b>להודיע לבנה\"א גבורותי\"ו</b>: תהלים קמה, יב."],["1290","20","<b>מתפרד</b>: דו: מתפרר."],["1291","21","<b>אין מלך בלא. . עם</b>: נסמן לעיל רנו, ד."],["1292","22","<b>ברו\"ב עם הדרת מלך</b>: משלי יד, כח."],["1293","23","<b>עושה השלום במרומיו</b>: איוב כה, ב (ושם שלום — ראה לעיל פ' שמות יג, ד. וש\"נ. ד: ובתקס\"ה כאן: שלום]. ראה במדב\"ר פי\"ב, ח. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרמה ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' שס. וש\"נ."]]],[2300550110,"בחי' התחלקות כלל וכלל כי שם עדיין מבחי' עצמות אור הא\"ס, וידוע דבחי' אוא\"ס עצמו אינו בגדר חלקים כלל מאחר שנק' א\"ס [ו]אם הוא מתחלק לחלקים וגבולים אין זה מבחי' א\"ס וכמ\"ש במ\"א. וא\"כ כאשר מאיר בצמצום הקו והחוט כו' מלמעלה מלפני הצמצום איזה ההארה משם אזי מתבטלים כל בחי' הרבוי וההתחלקות שנמצא אחר הצמצום הראשון והי' כלא הי' ממש, כי אור א\"ס עצמו הוא פשוט בתכלית הפשיטות וע\"כ הוא מעלה מעלה מגדר התחלקות וריבוי לגמרי, ע\"כ גם בבוא אפי' ההארה והשפע מעצמותו גם במה שנעשה לאחר הצמצום אז בא בהם בחי' הביטו\"ל במציאות ממש עד שאינם ב' הפכים כלל מאחר שכ\"א א[ו]בד את מקומו לגמרי וכאלו אינו במציאות כלל כו' וכמ\"ש דבר זה במ\"א באריכות וד\"ל. וזהו עוש\"ה השלו\"ם במרומי\"ו כו' כי מפני בחי' הביטול הגדול שימצא בהם ע\"י הארת עצמות אור הא\"ס נעשה שלום בין ב' הפכים כמו מיכאל וגבריאל למטה שהן שר של אש ושר של מים ב' הפכים גשמיי', ועד\"ז עד רום המעלות [הרי] מחולקי' ומופרדי' הן ב' בחי' אלו שהוא בחי' חו\"ג עד בחי' צמצום הראשון דקו וחוט הנ\"ל שמשם שרש הראשון להתחלקות כו' וכנ\"ל וע\"י הארת אור א\"ס שלפני הצמצום נעשה השלום ביניה\"ם מטעם הנ\"ל וד\"ל.\n[ב] <b>ואחר</b> הקדמה זו יובן שרש ענין קין והבל בדרך כלל. דהנה שרש בחי' קי\"ן הי'<sup data-n=\"1294\">24</sup> מבחי' <span data-k=\"pg\">808</span> ּ הגבורות<sup data-n=\"1295\">25</sup> עליונות שנעשה ממנו הצמצום הראשון כנ\"ל וע\"כ הי' קי\"ן עובד אדמה<sup data-n=\"1296\">26</sup> דוקא, כי האדמה יש בה רבוי התחלקות מינים שונים והוא להיותה בבחי' הפירוד והפירוד<sup data-n=\"1297\">27</sup> דוקא מבחי' הגבורות כנ\"ל. והבל הי' בו הארת בחי' החסדים<sup data-n=\"1298\">28</sup> שלפני הצמצום הראשון שאין שם עדיין בחי' התחלקות כלל ואדרבה מקור היחוד הפשוט בתכלית כו', וע\"כ הי' הבל רועה צאן<sup data-n=\"1299\">29</sup> דוקא כי ענין רועה צאן הוא בחי' המייחד והמחבר כל המדריגות הנפרדים וההפכיי' שימצאו ביחוד דוקא כמו יעקב שהי' רועה צאן<sup data-n=\"1300\">30</sup> מעקודי' נקודים כו', והי' ענין עבודתו במרעה שלהם רק לחבר ולייחד כל בחי' הנפרדי' כמ\"ש במ\"א באריכות שזהו הנק' רועה כו', ולכך הי' גם הבל רועה צאן שהוא היפוך בחי' הפירוד וההתחלקות דקין כו' כי הי' מייחד את בחי' הפירוד ע\"י בחי' ההארה שלפני הצמצום שטבעו ליחד דוקא כל נפרד מפני בחי' הביטול שנמצא בנפרדים כנ\"ל וד\"ל. והטעם שזה נק' בשם קי\"ן וזה [נק'] בשם הבל מבואר בע\"ח והוא בדרך פרט,",[["1294","24","<b>בחי' קי\"ן הי'</b>: גד: ענין קי\"ן."],["1295","25","<b>קי\"ן. . הגבורות</b>: ראה ע\"ח (שער קיצור אבי\"ע) ש\"נ, פ\"ג. (שער ק\"נ) שמ\"ט פ\"ג. לקוטי הש\"ס — להאריז\"ל — מס' מגילה. ספר הגלגולים פכ\"א ואילך. לקוטי תורה להאריז\"ל בראשית ג, א (כא, א ואילך). יחזקאל (ב) ד\"ה ענין יחזקאל. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשכה ובהנסמן במ\"מ לשם."],["1296","26","<b>קי\"ן עובד אדמה</b>: בראשית ד, ב. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשכה."],["1297","27","<b>והפירוד</b>: גד: והפירור."],["1298","28","<b>והבל. . בחי' החסדים</b>: ראה הנסמן בהערה 25."],["1299","29","<b>הבל רועה צאן</b>: בראשית ד, ב. ראה גם מאמרי אדה\"ז שבהערה 26."],["1300","30","<b>יעקב שהי' רועה צאן</b>: ויצא כט, יד ואילך. ל, כט ואילך. לא, ח ואילך. ראה מאמרי אדה\"ז על פרשיות התורה ח\"א (מהדורת תשמ\"ט) בהוספות ע' 15. תו\"ח ויצא קעא, ג."]]],[2300550142,"אבל דרך כלל הם ב' מדרגות הנ\"ל ובעבודת ה' יובן ג\"כ כדוגמתם והן ב' מדרגות הידועי' בחי' רצוא ובחי' שוב, דהנה בחי' הרצוא ידוע שהוא בחי' ההעלא' מלמטה למעלה כשלהבת העולה מלמטה למעלה דוקא וכמו\"כ בחי' רשפי אש התשוקה הנה היא בדרך ההעלאה מלמטה למעלה כו' והוא מבחי' הגבורות דוקא, אבל בחי' שוב הוא בחי' ההמשכה מלמעלה למטה והוא בחי' החסדי'<sup data-n=\"1301\">31</sup> דוקא כמו המים שיורדים מגבוה לנמוך<sup data-n=\"1302\">32</sup> כו' וכמ\"ש במ\"א. והנה ידוע דב' מדרגות הללו נק' בלשון המקובלים בשם מ\"ן ומ\"ד בחי' הרצוא הוא בחי' מיין נוק' להיותו בבחי' העלאה כנ\"ל וכמ\"ש ואל אישך תשוקתך<sup data-n=\"1303\">34</sup> כו' וכתי' רשפי' רשפי אש<sup data-n=\"1304\">35</sup> שלהבת כו', ובחי' השוב<sup data-n=\"1305\">33</sup> הוא בחי' מיין דוכרין דהיינו המשכת המשפיע למקבל שהוא מלמעלה למטה מגבוה לנמוך וכו' ונק' המ\"ן בשם קין והמ\"ד בשם הבל.\n<b>ויובן</b> ביאור זה בהקדים ענין א' והוא במ\"ש קול ה' חוצב להבות אש<sup data-n=\"1306\">36</sup> כו', ומבואר בזהר<sup data-n=\"1307\">37</sup> ובע\"ח<sup data-n=\"1308\">38</sup> ע\"פ [ו]כפטיש יפוצץ סלע<sup data-n=\"1309\">39</sup> כו' דכמו שהפטיש הזה בהכאתו על הסלע הקשה יזרוק ניצוצו' אש הרבה מן הסלע לכל צד כך למעלה מבחי' בוצינא דקרדוניתא<sup data-n=\"1310\">40</sup> כו' עד זריק ש\"ך ניצוצי' לכל ע[י]בר כו' ע\"ש. והנה ביאור ענין זה המאמר הוא ע\"פ הנ\"ל בענין וארב\"ה את זרעו כו' שטבע הגבורות הוא לחלק השפע לרבבות חלקים שונים כו', וכך הוא ממש במשל הפטיש שיפוצץ בסלע שיוציא כמה מיני ניצוצי' אש לכל ע[י]בר כו' הענין הוא דמה שנמצא בחי' הריבוי וההתחלקו' בכמה ניצוצי' כו' הוא בא מבחי' הגבורות דהיינו ע\"י הכאת הפטיש החזק בסלע הקשה. כו' והנה הניצוצו' הללו שיצאו מן הסלע הרי תחלה היו כלולים בבחי' העלם בגוף הסלע הקשה וביציאתן לחוץ הוא שנגלו מן ההעלם כו', ובודאי כשהיו הניצוצו' בהעלם לא היו עדיין בבחי' ריבוי התחלקות והפירוד כזה אלא היו הכל כא' ביחוד אחדות א' אך ע\"י ההכאה הוא <span data-k=\"pg\">תד</span> ּ שיצאו לחלק בחלקים רבים עד שיש כמה סך<sup data-n=\"1311\">41</sup> ניצוצו' קטנים מפורדים כו'. והנמשל מזה יובן למעלה במאמר הנ\"ל ג\"כ דע\"י בחי' הגבורות עליונות שנק' בוצינא דקרדוניתא ונק' גם בשם קו המדה<sup data-n=\"1312\">42</sup> כו' שהוא כמו הפטיש עד\"מ עד שיחלק האור והשפע לרבוי החלקים מאד עד דזריק ש\"ך ניצוצו' לכל עיבר כו' וקודם שיחלק הי' כל הניצוצי' בתכלית היחוד במאצילן כו'. וזהו פי' קול ה' חוצב להבות אש, פי' להב הוא ענין",[["1301","31","<b>הרצוא. . מבחי' הגבורות. . שוב. . בחי' החסדי'</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרל. תו\"א יתרו עג, ד."],["1302","32","<b>המים שיורדים מגבוה לנמוך</b>: ראה תענית ז, א."],["1303","34","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["1304","35","<b>רשפי' רשפי אש</b>: שה\"ש ח, ו."],["1305","33","<b>מ\"ן ומ\"ד בחי' הרצוא. . השוב</b>: ראה גם מאמרי אדה\"ז תקס\"ז ע' לד ואילך."],["1306","36","<b>קול ה' חוצב להבות אש</b>: תהלים כט, ז."],["1307","37","<b>בזהר</b>: ראה (היכלות) פקודי רנד, סע\"ב. (אד\"ז) האזינו רצב, ב."],["1308","38","<b>ובע\"ח</b>: ראה (שער רפ\"ח ניצוצין) שי\"ח, פ\"ה. עמק המלך (שער או\"א) שי\"ג, פי\"ג."],["1309","39","<b>[ו]כפטיש יפוצץ סלע</b>: ירמי' כג, כט. הכתוב הובא בעמק המלך. מאמרי אדה\"ז תקס\"ח ח\"א ע' תקז."],["1310","40","<b>בוצינא דקרדוניתא</b>: ראה הערה 42."],["1311","41","<b>סך</b>: ו: ש\"ך."],["1312","42","<b>בוצינא דקרדוניתא. . קו המדה</b>: ראה גם לעיל פ' בשלח קע, ב הערה 322."]]],[2300550174,"התכללו' כמה ניצוצי' יחד עד\"מ הלהב הגשמי שאינו בגדר חלקי ניצוצו' קטנים עדיין כו' אך בחי' החציב\"ה בלה\"ב הוא בחי' התחלקות והרבוי לכמה ניצוצי' להבות קטנים ע\"י הכאות הגבורות דבוצינא כו', וזהו בחי' קול ה' שנמשך מבחי' גבורות דבוצינא הנ\"ל לחצוב בחלקים רבים להבות אש שהיו תחלה כלולים ביחוד במאציל כנ\"ל להיות מסתעפים ללהבות ניצוצי' רבים כו' וכמא' הנ\"ל דזריק ש\"ך ניצוצים לכל עיבר כו' וד\"ל.\n<b>וע\"פ</b> כ\"ז יובן ההפרש ג\"כ בין קי\"ן להב\"ל דהנה שרש בחי' קי\"ן הוא מבחי' הגבורות עליונות דבוצינא הנ\"ל שמחלק אור השפע לחלקים רבים כו' (וזהו שמספר קי\"ן ק\"ס<sup data-n=\"1313\">43</sup> חצי ממספר ש\"ך ניצוצי' ומפני שאין לך טפה<sup data-n=\"1314\">44</sup> כו' שאין טפיי' דיצי'<sup data-n=\"1315\">45</sup> עולי' כו' וד\"ל), וכידוע דבחי' מ\"ן דנוק' הן עולים בבחי' התחלקות ורבוי כו', אבל בחי' הב\"ל (הוא אותיות לה\"ב<sup data-n=\"1316\">46</sup> ) הענין הוא בחי' [מ\"ד] שהוא היפך הפירוד והריבוי כנ\"ל אלא הוא בחי' שפע ההעלם שבמשפיע קודם שיתחלק לחלקים כו' וכמשל ניצוצי אור שהיו כלולים בסלע כו', ולכך נק' הב\"ל עד\"מ הבל הדיבור שאנו רואים שהדיבור הוא רק בחי' התחלקו' ההבל לכמה חלקים אבל ההבל עצמו פשוט הוא וכולל האותיות המופרדי' ממנו יחד כו' וד\"ל (וזהו שהי' הב\"ל רועה צאן כי צאן כמו צא[י]נה וראינה<sup data-n=\"1317\">47</sup> כו' לשון יציאה<sup data-n=\"1318\">48</sup> רבוי מדרגות מן ההעלם בבחי' הפירוד כו' והבל הרועה הוא המחבר כולם ומייחד אותם כמו ההבל שמייחד כל האותיות שנתפרדו כנראה בחוש וד\"ל). וזהו שמבואר בע\"ח דהב\"ל הוא בגימ' ל\"ז<sup data-n=\"1319\">49</sup> והוא בחי' מילוי דשם ס\"ג<sup data-n=\"1320\">50</sup> (דיו\"ד דס\"ג שבטהירו עילאה הוא שנבקע<sup data-n=\"1321\">51</sup> וממנו נעשה שרש התחלקות למטה כידוע והמילוי דס\"ג זהו בחי' הבל הכולל כל התחלקות עדיין כו' וד\"ל). ופי' המילוי ידוע שהוא בבחי' אור ההעלם שכלול במשפיע עדיין כו' כמו העלם הדיבור כאשר הוא כלול עדיין במחשבה דהיינו שחושב מה לדבר כו' וד\"ל. והכל מטעם הנ\"ל לפי שבחי' הבל הוא קודם צמצום הראשון כו', והוא בחי' הבל דאורייתא כמ\"ש קהלת הב\"ל הבלי\"ם<sup data-n=\"1322\">52</sup> כו' הכל הב\"ל שגם ז' ההבלי' שמתחלקי' בדרך כלל מ\"מ כלולים בהבל אחד והוא משום כי הכל הבל, והיינו הבל דאורייתא דוקא להיותו מבחי' שו\"ב הנ\"ל דאורייתא מח\"ע נפקת<sup data-n=\"1323\">53</sup> בהבל אחד ובשעת מ\"ת הוא שנחלק לרבוי אותיות וכמ\"ש קול ה' חוצב להבות אש כו', אבל שרשה של תורה באמת",[["1313","43","<b>שמספר קי\"ן ק\"ס</b>: ראה לקו\"ת להאריז\"ל בראשית ג, כ."],["1314","44","<b>שאין לך טפה</b>: ראה תענית כה, ב. רוקח סשע\"ז. זהר (רע\"מ) פינחס רמז, ב. לקמן פ' תשא שפג, ב. תו\"א תשא קיב, ד. מאמרי אדה\"ז תקס\"ג ח\"א ע' קפא. מאמרי אדה\"א הנחות תקע\"ז ע' רכב. וש\"נ."],["1315","45","<b>דיצי'</b>: דו: דמ\"ן."],["1316","46","<b>הב\"ל. . לה\"ב</b>: ראה ת\"ז תכ\"א (מט, ב). ת\"ל (עג, רע\"ב). תס\"ט (קד, א. קיז, ב). זהר (רע\"מ) פינחס רלה, ב. לקו\"ת אחרי כה, ג. ובהנסמן במ\"מ לשם."],["1317","47","<b>צאן כמו צא[י]נה וראינה</b>: שה\"ש ג, יא. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א בהוספות ע' 15 ובהנסמן במראי מקומות לשם. תו\"ח וישלח קפ, ג."],["1318","48","<b>צאן. . לשון יציאה</b>: ראה שרש ישע מערכת צון. תו\"ח וישלח קפ, ג ובהערה 12."],["1319","49","<b>דהב\"ל הוא בגימ' ל\"ז</b>: ראה לקו\"ת להאריז\"ל בראשית ג, כ. פע\"ח (שער השופר) שכ\"ו, פ\"א. פ\"ג. ובמהדורת דובראוונא פ\"ב."],["1320","50","<b>ל\"ז. . מילוי דשם ס\"ג</b>: ראה ע\"ח (שער טנת\"א) ש\"ה, פ\"א. (שער רפ\"ח) שי\"ח, ספ\"א. פע\"ח שם."],["1321","51","<b>דיו\"ד דס\"ג. . שנבקע</b>: ראה גם לעיל פ' בשלח קנ, ד. וש\"נ."],["1322","52","<b>הב\"ל הבלי\"ם</b>: קהלת א, ב."],["1323","53","<b>דאורייתא מח\"ע נפקת</b>: נסמן לעיל רסח, ד."]]],[2300550206,"הוא מבחי' עצמו' אור הא\"ס שלפני הצמצום וכמ\"ש ואהי' אצלו אמון<sup data-n=\"1324\">54</sup> כו' ואסתכל באורייתא<sup data-n=\"1325\">55</sup> כו' וד\"ל. וזהו שארז\"ל שאין העולם מתקיים<sup data-n=\"1326\">56</sup> אלא בהב\"ל פי תינוקות של בית רבן בהבל דוקא וד\"ל. (והיינו ג\"כ שרש <span data-k=\"pg\">810</span> ּ ענין הפסוק כי לא על הלח\"ם לבדו<sup data-n=\"1327\">57</sup> כו' אלא על כל מוצא פי ה' שהוא הבל דאורייתא יחי' האד\"ם בחי' האד\"ם דלעילא כו' וד\"ל).\n[ג] <b>ואחר</b> כ\"ז יובן<sup data-n=\"1328\">58</sup> שרש הענין הנ\"ל בכליון זרעו של הבל עד הקץ כמ\"ש בלק\"ת הנ\"ל. ותחלה יש להקדים שיש ב' מדרגות במיתה, הא' המיתה שאדם ימות על מטתו בבואו עת[ו ו]זמנו דוקא. והב' אשר ימות בפתע פתאום כמו ע\"י מיתת ב\"ד או ע\"י המל' או ע\"י סיבה [אחרת] כמו [מי] שנהרג ע\"י רציחה אם במזיד או בשוגג או שנפל מן הגג ומת וכיוצא בכל אלה שאין מיתה כזו בזמנה ועתה עדיין כו'. וההפרש בין ב' מדרגות הללו יובן בהקדים תחלה ענין א' והוא כמ\"ש כי צל ימינו עלי ארץ<sup data-n=\"1329\">59</sup> וכתיב ימים יצרו<sup data-n=\"1330\">60</sup> כו', ומבואר הענין במ\"א בהיות שבצלם אלקי' עשה את האדם<sup data-n=\"1331\">61</sup> כו' וכדי לתקן בחי' הצלם שלו ניתן לו ימים ושנים במספר וקצבה לפי הצורך לתיקון שצריך לתקן בצלמו, וזהו ימים יצרו כו' במספר מפני שיש גבול לימי חייו של צלם נפשו בגוף עד שיתקן מה שראוי לתקן. וזהו כי צל ימינו עלי ארץ, פי' צ\"ל מבחי' הצל\"ם נמשך וירד בגופו במדה וגבול ימים כו', והנה לעת קץ ימי חייו כבר נגמר כל בחי' תיקון הצלם דנפשו ואין לו עוד מה לתקן כ\"א בגלגול אחר ע\"כ יבא בהכרח עת קץ לימי חייו וזוהי סיבת המיתה שבאה בעתה וזמנה על מטתו. והנה ידוע דאת זלעו\"ז עשה האלקים<sup data-n=\"1332\">62</sup> וכמו שיש נשמות וניצוצי' דקדושה בעולמות די\"ס דקדושה באבי\"ע כמו\"כ לעומת זה יש י\"ס דקליפה בארבע עולמות הללו ג\"כ בניצוצ[ו]' ונשמות ומלאכים דמסטרא דנוג\"ה כו', וידוע דיניקת הקליפות מתחלת דוקא בסיום שפע אור הקדושה שבכל עולם ועולם כמו בעולם האצי' מתחיל יניקת כתר דקליפה מבחי' אחוריי' דנה\"י דמל' דקדושה כו' וכמבואר בע\"ח דכת\"ר דקליפה דבוק מאחוריי' דנוק'<sup data-n=\"1333\">63</sup> שהוא מבחי' נה\"י דנה\"י כו'. וזהו ויאסוף יעקב רגליו אל המטה<sup data-n=\"1334\">64</sup>, פי' כאשר כבר מסתיים אורו' דאצי' שהוא בחי' יעקב בחי' ת\"ת<sup data-n=\"1335\">65</sup> דאצי' בבחי' נה\"י שבו שנק' רגלי\"ו כתיב ויאסוף רגליו שנסתלקו בחי' נה\"י, וכאשר מסתלק אור הקדושה גם מבחי' התחתונה אזי יש שרש וראש להתחלת החיצוני' שהיא המיתה, שהרי אין המיתה אלא בהסתלקות החיות בתחלה שאם לא נסתלק החיות לגמרי עדיין אין המיתה מצויי'",[["1324","54","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["1325","55","<b>ואסתכל באורייתא</b>: נסמן לעיל רנט, ד."],["1326","56","<b>שאין העולם מתקיים</b>: ראה שבת קיט, ב. הנסמן לעיל פ' וארא פא, ד."],["1327","57","<b>כי לא על הלח\"ם לבדו</b>: עקב ח, ג."],["1328","58","<b>יובן</b>: דו: ובמאמרי אדה\"ז תקס\"ה כאן: יש להבין."],["1329","59","<b>כי צל ימינו עלי ארץ</b>: איוב ח, ט."],["1330","60","<b>ימים יצרו</b>: תהלים קלט, טז. ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' רסט. תקס\"ד ע' לח. לקמן פ' משפטים רעח, ד. רפה, ג. ש, ד. מאמרי אדה\"א שמות ח\"ב ע' שמא. וש\"נ."],["1331","61","<b>שבצלם אלקי' עשה את האדם</b>: נח ט, ו."],["1332","62","<b>דאת זלעו\"ז עשה האלקים</b>: נסמן לעיל רנא, ג."],["1333","63","<b>דכת\"ר דקליפה. . דנוק'</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"ג."],["1334","64","<b>ויאסוף. . אל המטה</b>: ויחי מט, לג [בהוספת תיבת: יעקב]."],["1335","65","<b>יעקב. . ת\"ת</b>: זהר (ס\"ת) ויצא קנז, ב. שם ח\"ג (תוספות) שב, א."]]],[2300550238,"ואחר הסתלקות החיות מכל וכל דוקא אזי מותא שליט<sup data-n=\"1336\">66</sup> כו', והמות הזה הוא שרש יניקת החיצונים למעלה. וזהו שנא' רגלי' יורדות מות<sup data-n=\"1337\">67</sup> פי' מבחי' הסתלקות נה\"י דקדושה שהוא החיות הנק' מקור כל החיים כידוע אזי מתחיל יניקו' שרש המות כו' והוא שרש יניקת החיצוני' כי אין יניקתם אלא כאשר נתרוקן אור החיות מכל וכל כידוע, אבל כאשר עדיין יש קצת מבחי' החיות עדיין לא יש להם אחיזה ויניקה כלל כו', וזהו ראה נתתי לפניך<sup data-n=\"1338\">68</sup> החיים והטוב והמות והרע ובחרת בחיים<sup data-n=\"1339\">69</sup> כו' וכמ\"ש במ\"א וד\"ל. וא\"כ מובן לפ\"ז למעלה דבעולם התחתון ג\"כ הוא ע\"ד הזה דע\"י מיתה אשר היא באה בעתה ו[ב]זמנה שהוא לאחר שכבר נגמר התיקון דצלם הנפש דעשי' או דיצי' ודבריאה וכיוצא ובהכרח שיסתלק הניצוץ הקדוש כנ\"ל, א\"כ יש בהכרח התחלה ליניקת החיצוני' ויונקים מבחי' רשימו והוא הארה דהארה מאור ניצוץ הקדושה שנסתלק, וגם יהי' לפעמי' תוספת יניקה להם <span data-k=\"pg\">תה</span> ּ מסיבת נפילת אור ניצוצי קדושה ממש שנפלו בבחי' מותרות למטה בהיכלות החיצוני' בעת וזמן הסתלקותם מגופם וכו'.\n<b>ועד\"ז</b> יובן [בכלל] למעלה בכללות נש\"י שהוא בחי' מל' דאצי' שבזמן וקץ<sup data-n=\"1340\">70</sup> הבירורי' דרפ\"ח כו' אזי יוכל להיות לחיצוני' תוס' יניקה מחמת טעם הנ\"ל וזהו לא זכו בעתה כו', אבל זכו אחישנ\"ה להיות בירורי' דרפ\"ח לפני הע\"ת והזמן. וענין זה הוא מובן למעלה בדוגמא ממה שאנו רואים למטה במדריגת מיתה השני' שהיא לפני הזמן והעת כמו ע\"י מיתת ב\"ד או מל' או ע\"י רוצחי' בשוגג או במזיד, וכמו סיבת הורגי נפש בשגגה דכתיב בהם והאלקי' אנה לידו<sup data-n=\"1341\">71</sup> דלכאורה פלאי איך ימצא להסיבה<sup data-n=\"1342\">72</sup> סיבה מאת ה' בחנם על לא פשע והגם שיש בדברי רז\"ל דרשות<sup data-n=\"1343\">73</sup>, אבל לפי מ\"ש בלק\"ת הנ\"ל הענין הוא ע\"ד סוד ה' כאשר חפץ ה' בהצלת נפש מישראל שלא יפול ממנה מותרות לחיצוני' ולא ידח ממנו נדח<sup data-n=\"1344\">74</sup> כו' יבוא [לו] סיבה שיהרג לפני זמנו ועתו דהיינו קודם שיתקן בחי' צלמו דקדושה, ואז עדיין לא יש מקום ושרש התחלה כלל ליניקת החיצוני' שהרי אין התחלתם אלא מסיום אורות דקדושה דוקא כנ\"ל ולא יפול מהנפש מאומה בהיכלות החיצוני', ואדרבה מלבד שכולו עולה לה' בכל מכל כל<sup data-n=\"1345\">75</sup> אלא עוד יתוסף בהנפש עליי' גדולה ועצומה בהיות שהעלאת מ\"ן שלה יגיע למקום ומדרגה גבוה מאד נעלה מה שלא היתה מגעת בהסתלקותה בזמן ועת המוגבל שלה. וכאשר אנו רואים בי' הרוגי מלוכה<sup data-n=\"1346\">76</sup> שנשמותיהם נכללו במוחין",[["1336","66","<b>מותא שליט</b>: ראה זהר במדבר קיט, א."],["1337","67","<b>רגלי' יורדות מות</b>: משלי ה, ה. לעיל ערב, ד הערה 140."],["1338","68","<b>ראה נתתי לפניך</b>: נצבים ל, טו [בשינוי — ראה גם הנסמן לעיל פ' בשלח קמו, ד]."],["1339","69","<b>ובחרת בחיים</b>: נצבים ל, יט."],["1340","70","<b>וקץ</b>: ד: וסוף."],["1341","71","<b>והאלקי' אנה לידו</b>: משפטים כא, יג. ראה מכילתא שם. מכות י, ב."],["1342","72","<b>להסיבה</b>: דו: להריגה. וכ\"ה במאמרי אדה\"ז תקס\"ה כאן."],["1343","73","<b>בדברי רז\"ל דרשות</b>: ראה הערה 71."],["1344","74","<b>ולא ידח ממנו נדח</b>: שמו\"ב יד, יד."],["1345","75","<b>בכל מכל כל</b>: לשון הגמ' ב\"ב יז, א."],["1346","76","<b>בי' הרוגי מלוכה</b>: ראה פיוט אלה אזכרה (מוסף ליו\"כ)."]]],[2300550269,"דאימא שהי' בחי' העלא' מ\"ן<sup data-n=\"1347\">77</sup> לבינה וזהו מדרגה<sup data-n=\"1348\">78</sup> גבוה מאד שלא היו יכולים להגיע בהסתלקותם בעתם וזמנם כו', ועד\"ז גם בשאר הרוגי מיתה שלפני הזמן וכמו הרוגי לוד שאין כל ברי'<sup data-n=\"1349\">79</sup> כו' אע\"פ שלא היו אלא הרוגי מל', ועד\"ז גם בשאר הרוגי' שלא ע\"י עת קץ וזהו והאלקי' אנה לידו כו' וד\"ל. ועתה יובן קצת גם במ\"ש בספר לק\"ת הנ\"ל בענין ערי מקלט לעתיד שהוא כדי לכלות זרעו של הבל וכענין לא זכו בעתה זכו אחישנה כו' מפני שבחי' הבל הוא מבחי' מ\"ד שלפני הצמצום כנ\"ל וחטא הבל<sup data-n=\"1350\">80</sup> עד שיכלה זרעו כו' עמוק עמוק הוא ומובן לי\"ח, אך מה שיכלה זרעו ע\"י הורגי נפש בשגגה דוקא מובן הוא מטעם הנ\"ל כדי שלא יפול לחיצוני' מאורות ניצוצי הנשמות ששרשם מבחי' הבל כשהי' מסתלקי' בעתם וזמנם כו' וד\"ל<sup data-n=\"1351\">81</sup>.",[["1347","77","<b>בי' הרוגי מלוכה. . העלא' מ\"ן</b>: ראה ע\"ח (שער מ\"ן ומ\"ד) של\"ט, דרוש א. מאמרי אדה\"א ויקרא ח\"ב ע' תרכז. וש\"נ. בראשית ע' שנז ואילך. וש\"נ. שע\"ת נו, ב הערה 62."],["1348","78","<b>וזהו מדרגה</b>: ד: למקום ומדרגה."],["1349","79","<b>הרוגי לוד שאין כל ברי'</b>: ב\"ב י, ב."],["1350","80","<b>וחטא הבל</b>: ראה גם בענין חטא הבל אוה\"ת בראשית כרך ז ע' תתשסז ואילך. וע' תתשע."],["1351","81","<b>וד\"ל</b>: בג: ניתוסף: ולהבין דבר זה בתוספות ביאור. וכ\"ה במאמרי אדה\"ז תקס\"ה כאן."]]],[2300550047,"<b>בעז\"ה שבת פ' משפטים</b>\n<span data-k=\"pg\">תט</span> ּ<b>ואלה</b> המשפטים<sup data-n=\"1352\">1</sup> אשר תשים לפניהם<sup data-n=\"1353\">2</sup>, כי תקנה עבד עברי שש שנים יעבוד ובשביעית יצא לחפשי חנם<sup data-n=\"1354\">3</sup>, וצ\"ל כ\"ז שלפניהם משמע לשון רבים וכי תקנה [משמע] לשון יחיד דלפי\"ז הול\"ל כי יקנו ג\"כ לשון רבים כו'. אך הענין הוא דכי תקנה א' משרע\"ה<sup data-n=\"1355\">4</sup> דקאי אדלעיל מיני' שא' [לו] הקב\"ה ואלה המשפטים אשר תשים לפניהם תשים דוקא דקאי על משרע\"ה שהוא ישים המשפטים לפניהם וע\"ז קא מפרש קרא לה[ל]ן איך תשים לפניהם כי תקנה עבד עברי וגו'. והענין הוא דהנה כתיב ונתתי עשב בשדך לבהמתך<sup data-n=\"1356\">5</sup> שזה א' משרע\"ה שמשפיע בחי' עשב לבהמתך והיינו דכתיב וזרעתי את בית ישראל<sup data-n=\"1357\">6</sup> זרע אדם וזרע בהמה וגו'<sup data-n=\"1358\">7</sup>, פי' שיש ב' בחי' ומדריגות בכנס\"י, המדרג' הא' הוא בחי' זרע אדם שהם הנשמות שנמשכים מבחי' אדם העליון דכתי' נעשה אדם בצלמנו כדמותנו<sup data-n=\"1359\">8</sup> שאדם אדמה לעליון<sup data-n=\"1360\">9</sup> דהיינו שאלו הנשמות יש להם דעת והרגשה באלקות עד שלהם הוא בנקל העבודה לעבוד היתה<sup data-n=\"1361\">10</sup> בלב שלם ואין העולם מסתיר להם כלל מפני שמרגישים ומכירים את פועלם",[["1352","1","<b>ואלה המשפטים</b>: מאמר זה (וביאורו) הוא הנחת הר' משה בן כ\"ק אדה\"ז מש\"פ משפטים תקס\"ה. ונדפסה גם במאמרי אדה\"ז תקס\"ה ח\"א ע' רמז (נוסח א'). ושם נדפסה גם הנחת כ\"ק אדה\"א (נוסחא שני'). ובשינויים בתו\"א ר\"פ משפטים (וראה הנסמן במ\"מ לשם). במאמרי אדה\"ז שם ע' רפז נמצא מהנחת הר\"מ גם ביאור שני. המאמרים (ד\"ה ואלה המשפטים וד\"ה כי תקנה עבד עברי) שנדפסו לקמן הם ביאורים מכ\"ק אדה\"א על דרוש זה (הנחתו). ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["1353","2","<b>ואלה המשפטים. . לפניהם</b>: משפטים כא, א."],["1354","3","<b>כי תקנה. . חנם</b>: משפטים שם, ב."],["1355","4","<b>א' משרע\"ה</b>: ראה גם לקמן רפד, א."],["1356","5","<b>ונתתי עשב בשדך לבהמתך</b>: עקב יא, טו."],["1357","6","<b>וזרעתי את בית ישראל</b>: ירמי' לא, כו [בדילוג — ראה לקמן רפ, א. פ' ויקהל תכט, א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' יב]."],["1358","7","<b>וגו'</b>: וכ\"ה גם באהו."],["1359","8","<b>נעשה אדם בצלמנו כדמותנו</b>: בראשית א, כו."],["1360","9","<b>שאדם אדמה לעליון</b>: נסמן לעיל פ' יתרו רסב, א."],["1361","10","<b>היתה</b>: אהו: ה' ית'."]]],[2300550079,"ית' המהווה אותם מאין ליש בדעת והרגשה ממש. והמדרגה הב' הוא בחי' זרע בהמה שהם הנשמות שאין להם דעת והרגשה באלקות שנמשל כבהמות נדמו<sup data-n=\"1362\">11</sup>, אף שיש להם שכל והשגה שמשיגים איך שהקב\"ה מחי' את כולם וכולא קמי' כל\"ח<sup data-n=\"1363\">12</sup> כי לגדולתו אין חקר<sup data-n=\"1364\">13</sup>, אעפ\"כ מאחר שאין להם דעת נמשל כבהמות נדמו כבהמה [ש]יש בה כל החושים ראי' ושמיעה רק שאין לה דעת, כך עד\"מ אותם בנ\"א שאין להם דעת באלקות אף שיש להם שכל ומשיגים [ומשכילים] גדולת הבורא ית' נמשל כבהמות נדמו, והיינו שהדעת הוא בחי' ההרגשה שמרגיש מקורו מקור החיים אוא\"ס ב\"ה המחי' את כולם כהרגשת חיי נפשו ממש, אף שאינו משיג מהות החיות של נפשו שאינו בגדר ארוך וגוץ קור וחום שהוא חיות רוחני שאינו נתפס בשכל והשגה אעפ\"כ מרגיש מציאותו שהוא כח החיוני המחי' אותו, כנראה בעליל כאשר הוא ישן מסתלק החיות וכאשר ניעור משנתו הרוח החיוני תשוב אליו כמקדם שנרגש פעולת הרוחני החיוני שלו<sup data-n=\"1365\">14</sup> בהרגשה <span data-k=\"pg\">820</span> ּ ממש. כך עד\"מ ממש הוא בחי' הדעת באלקות שהוא בחי' ההרגשה שמרגיש החיות הנשפע [מ]מקור החיים להחיות כל העולמות בהרגשה ממש אף דלמחתב\"כ מהות החיות הנשפע מחיי החיים אוא\"ס ב\"ה לכל העולמות להחיותם ולקיימם, אעפ\"כ ירגיש בבחי' הרגשה ממש את בחי' מציאותו איך שמחי' את כולם כמו שמרגיש חיי נפשו אף שאינו משיג מהותו ממש כנ\"ל. ולכן כאשר אין לו דעת אף שיש לו שכל והשגה באלקות שמשכיל ומשיג גדולת הבורא ית' איך",[["1362","11","<b>שנמשל כבהמות נדמו</b>: תהלים מט, יג. כא."],["1363","12","<b>וכולא קמי' כל\"ח</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה (שער היראה) ש\"א, פ\"א (ז רע\"א). מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1364","13","<b>לגדולתו אין חקר</b>: תהלים קמה, ג."],["1365","14","<b>שלו</b>: אהו: של נפשו."]]],[2300550111,"שלגדולתו אין חקר וכולא קמי' כ\"ח רק שאין לו דעת והרגשה נמשל כבהמות נדמו שאלו נק' זרע בהמה, הגם שיש לו אמונה באחדות ה' כי ישראל מאמינים בני מאמינים<sup data-n=\"1366\">15</sup> הם כו' שהאמונה היא למעלה מן הדעת שמאמין באמונה פשוטה בלי טעם ודעת כלל כו' ולכך נק' זרע בהמה כנ\"ל, משא\"כ זרע אדם אדמה לעליון שיש להם דעת והרגשה באלקות שמרגישי' את מקורם מקור החיים אוא\"ס ב\"ה המחי' את כולם כמ\"ש כי עמך מקור חיים<sup data-n=\"1367\">16</sup> וגם זה<sup data-n=\"1368\">17</sup> בבחי' הרגשה ממש כהרגשת חיי נפשו ממש, שזהו בחי' ראי' שרואה בעין השכל ודעת שלו מציאות החיות הנשפע ממקור החיים בבחי' הרגשה נגלית ממש שאין מסתיר להם העולם כלל, אזי יוליד מזה האהבה לה' ית' שהאהבה הוא מדבר שרואה בבחי' ראי' דוקא שרואה בעין השכל ודעת כי עמך מקור חיים שירגישו כהרגשת חיי נפשו וכ[ל] אשר לאיש יתן בעד נפשו<sup data-n=\"1369\">18</sup> ע\"כ בטל כל רצונותיו מפני רצונו ית' שהוא חיי נפשו מקור החיים כנ\"ל, ואז יהי' נקל להם מאד עבודת ה' [ית'] מאחר שאין נסתר מנגד עיניהם ומרגישים מקור החיים המהווה בכל רגע מאין ליש ממש בכל רגע [ממש כו' כנ\"ל] לכך נק' זרע אדם אדמה לעליון כמ\"ש נעשה אדם בצלמנו כדמותנו כנ\"ל וד\"ל.\n(ב) <b>והנה</b> משרע\"ה משפיע בחי' הדעת בכנ\"י אף באותן שנק' זרע בהמה שיהי' להם דעת והרגשה במקורם מקור החיים אוא\"ס ב\"ה כי משה הוא רעיא מהימנא אחד ומיוחד מז' הרועי'<sup data-n=\"1370\">19</sup> עילאין שרועה וזן את ישראל בהשפעות אליהם מוח הדעת המתפשט ממש בכנ\"י ולכך הוא גואל ראשון וגואל אחרון<sup data-n=\"1371\">20</sup> כמ\"ש שלח נא ביד תשלח<sup data-n=\"1372\">21</sup> והשיב לו הקב\"ה אנכי אהי' עם פיך<sup data-n=\"1373\">22</sup> וגו', פי' הוא גואל ראשון שבתחלת הדבור שלו לישראל אמר וידעתם כי אני הוי'<sup data-n=\"1374\">23</sup> כו' שהשפיע להם בחי' הדעת עליון שידעו את הוי' בבחי' דעת והרגשה ממש, כי מקודם כתיב ויאמן העם<sup data-n=\"1375\">24</sup> שהיו מאמינים בה' בבחי' אמונה פשוטה בלי טעם ודעת כלל כי ישראל מאמינים בני מאמינים כו', אך הי' חסר להם בחי' הדעת והרגשה באלקות לידע את הוי' בבחי' הרגשה ממש ע\"ז השפיע להם מרע\"ה בחי' מוח הדעת כמו שאמר להם בראשית שליחותו וידעתם כי אני הוי' כו' וזהו בחי' גואל ראשון שהי' משפיע להם הדעת בצאתם ממצרים כו'. והוא שיהי' ג\"כ גואל אחרון שלע\"ל הוא יגאל את ישראל <span data-k=\"pg\">תי</span> ּ וישפיע להם בחי' הדעת כמ\"ש ומלאה הארץ דעה את ה'<sup data-n=\"1376\">25</sup> כו' כי כולם ידעו אותי<sup data-n=\"1377\">26</sup> וגו' שכ\"ז יהי' ע\"י בחי' משה שמשפיע להם מוח הדעת שהוא יהי' גואל האחרון כנ\"ל וד\"ל,",[["1366","15","<b>מאמינים בני מאמינים</b>: ראה שבת צז, א. לעיל פ' בא קי, ד בהערה."],["1367","16","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["1368","17","<b>וגם זה</b>: א: וגו'."],["1369","18","<b>וכ[ל] אשר לאיש. . נפשו</b>: איוב ב, ד."],["1370","19","<b>מז' הרועים</b>: נסמן לקמן רפב, ב."],["1371","20","<b>גואל ראשון וגואל אחרון</b>: ראה שמו\"ר פ\"ב, ד. הנסמן לעיל פ' בא קיח, ג."],["1372","21","<b>שלח נא ביד תשלח</b>: שמות ד, יג."],["1373","22","<b>אנכי אהי' עם פיך</b>: שמות ד, יב."],["1374","23","<b>וידעתם כי אני הוי'</b>: וארא ו, ז."],["1375","24","<b>ויאמן העם</b>: שמות ד, לא."],["1376","25","<b>ומלאה הארץ דעה את ה'</b>: ישעי' יא, ט [ושם: כי מלאה נסמן לעיל פ' בשלח קס, ד]."],["1377","26","<b>כי כולם ידעו אותי</b>: ירמי' לא, לג."]]],[2300550143,"וז\"ש ונתתי עשב בשדך לבהמתך וגו', פי' עשב הוא בחי' דעת [עליון] שהוא שם ע\"ב ושי\"ן<sup data-n=\"1378\">27</sup> באמצע התיבה שהוא שי\"ן כזה הממשיך בחי' דעת העליון למטה אל בחי' שדה העליונה שנק' חקל תפוחין קדישין<sup data-n=\"1379\">28</sup> בשביל בהמתך המה הנשמות [שנקראי' זרע בהמה שאין להם דעת שמשה משפיע להם הדעת עליון כנ\"ל וכמ\"ש מצמיח חציר לבהמה] וגו' כמ\"ש בזהר על בהמה דאכלה אלף טורין<sup data-n=\"1380\">29</sup> בכל יומא וכנ\"ל<sup data-n=\"1381\">30</sup>, והיינו שאף המלאכים עליונים שתחת המרכבה ד' מחנות שכינה<sup data-n=\"1382\">31</sup> נק' ג\"כ בשם בהמות וחיות<sup data-n=\"1383\">32</sup> שהם הם הד' חיות שנא' במרכבת יחזקאל פני ארי' אל הימין פני שור<sup data-n=\"1384\">33</sup> מהשמאל כו'. והענין הוא שאף שיש להם דעת גדול שיודעים את רבונם וגדולתו ית' ומתבטלים לפניו בתכלית הביטול וכמ\"ש וצבא השמים לך משתחוים<sup data-n=\"1385\">34</sup> וכו' אך אעפ\"כ לגבי בחי' מהות המאציל ב\"ה הרם ומתנשא לבד בבחי' אין ערוך כו' נמשל כבהמות נדמו כי לית מחתב\"כ, ואף המלאכים עליונים אין להם דעת כלל בעצמות המאציל ב\"ה אשר הם נבראים מחודשים מאין ליש [ממש] שאין להם ערך כלל אל הבורא ית' לכך לית מחשבה דילהון תב\"כ רק במציאותו ית' מפעולתו ניכר גדולתו ית' אשר אין לה חקר ותכלית כלל [לכך לגבי ית' נמשל כבהמות נדמו, ולזאת מצטרכים להמשיך עליהם ג\"כ בחי' הדעת עליון מלמעלה מבחי' ומדריג']<sup data-n=\"1386\">35</sup> משרע\"ה רע\"מ הרועה וזן את כולם בהשפעת דעת עליון עד שאף אלו שנק' זרע בהמה ימצא טוב טעם ודעת באלקות כנ\"ל. ולז\"א ונתתי עשב בשדך לבהמתך וגו' כנ\"ל שאף המלאכים [ה]עליונים נק' בשם בהמות שאינם משיגים רק מציאותו ית' דהיינו שכל עיקר החיות שלהם וקיומם הוא רק מבחי' שם כבוד מלכותו ית' כמ\"ש מלכותך מל' כ\"ע<sup data-n=\"1387\">36</sup> כו', וכמו עד\"מ במלך ב\"ו המולך על כמה מדינות שאין עצם עצמו של המלך מלובש [בתוך המדינות] זולת[י] מלך שמו נק' עליהם בלבד. כך עד\"מ למעלה מבחי' התפשטו' שם כבוד מלכותו [ית'] אשר שמו נק' עליהם זה עצמו הוא החיות והקיום של כל העולמות כולן, שזה רק בחי' התפשטות הארה חיצוני' ממנו ית' ולא בחי' עצמותו ית' שאינם מכירים<sup data-n=\"1388\">37</sup> ויודעים כלל דלית מחתב\"כ לכך נק' המלאכים העליונים בשם בהמות שאי[נם] משיגים ויודעים [כלל] בחי' עצמותו ית' כנ\"ל ולכך נאמר ונתתי עשב בשדך לבהמתך וגו'. והיינו שהמלאכים ממשיכים הדעת עליונים<sup data-n=\"1389\">38</sup> ע\"י השיר שלהם שאו' קדוש קדוש קדוש<sup data-n=\"1390\">39</sup> כו' כי אין הקב\"ה מצטרך להשיר שלהם כי הוא משובח ומרומם ומפואר<sup data-n=\"1391\">40</sup> לבדו מצד עצמו ית' זולת[י] השיר שלהן הוא בשביל עצמן להמשיך עליהם הדעת [עליון] ע\"י השיר שלהן שעוני' באימה",[["1378","27","<b>עשב. . שם ע\"ב ושי\"ן</b>: נסמן לקמן רפב, ד."],["1379","28","<b>שדה. . חקל תפוחין קדישין</b>: ראה זהר ויחי רכד, ב."],["1380","29","<b>מצמיח חציר לבהמה. . דאכלה אלף טורין</b>: תהלים קד, יד. ראה זהר בראשית יח, ב. לעיל פ' בא צג, א. וש\"נ."],["1381","30","<b>וכנ\"ל</b>: אהו: כו'."],["1382","31","<b>המלאכים. . ד' מחנות שכינה</b>: זהר במדבר קיח, ב."],["1383","32","<b>המלאכים. . בהמות וחיות</b>: ראה גם לעיל קסח, ג. וש\"נ."],["1384","33","<b>פני ארי'. . פני שור</b>: יחזקאל א, י [ושם: ופני. . ופני]."],["1385","34","<b>וצבא השמים לך משתחוים</b>: נחמי' ט, ו."],["1386","35","<b>[לכך. . ומדריג']</b>: בתו\"ח כאן: אבל."],["1387","36","<b>מלכותך מל' כ\"ע</b>: תהלים קמה, יג."],["1388","37","<b>מכירים</b>: אה: משיגים. וראה בסמוך בפנים בשו\"ה משיגים."],["1389","38","<b>עליונים</b>: אהו: עליון."],["1390","39","<b>קדוש קדוש קדוש</b>: ישעי' ו, ג."],["1391","40","<b>ומרומם ומפואר</b>: אהו: ומפואר ומרומם."]]],[2300550175,"וביראה ועונין<sup data-n=\"1392\">41</sup> ג\"פ קדוש עי\"ז ממשיכי' בחי' הדעת עליון אליהם כנ\"ל וד\"ל.\n(ג) <b>והנה</b> נאמר בפי' יוצר אור כולם כאחד עונים באימה ואומרים ביראה קדוש קדוש כנ\"ל כולם כאחד דוקא כמ\"ש בזהר דלא מקדשין (לי'] לעילא עד דמקדשין ישראל<sup data-n=\"1393\">43</sup> לתתא דמקדשי' לי' כולא כחדא<sup data-n=\"1394\">42</sup> כנ\"ל. והענין הוא שלכך אין מקדשין אותו מלמעלה עד שיקדשו אותו מלמטה שמצפים המלאכים לקדושת ישראל שלמטה דמקדשי לי' כולא כחדא כנ\"ל, בהיות שרש ישראל עלו במחשבה<sup data-n=\"1395\">44</sup> לפניו תחלה כנ\"ל שנמשכו מבחי' <span data-k=\"pg\">822</span> ּ מחשבה עילאה ושרש המלאכים הוא דבר ה'<sup data-n=\"1396\">45</sup> ורוח פיו ית' כמ\"ש בדבר ה' שמים נעשו<sup data-n=\"1397\">46</sup> וברוח פיו כל צבאם וגו' לכך אינם יכולים המלאכים לומר קדוש היינו להמשיך עי\"ז בחי' הדעת [עליון] אליהם כנ\"ל עד שיאמרו ישראל למטה נקדישך כנ\"ל, בהיות ששרש ישראל עלו במחשבה ע\"כ ממשיכים משרשם בחי' עליונה כנ\"ל ואז המלאכים יכולים להמשיך אליהם הדעת משרשם בחי'<sup data-n=\"1398\">47</sup> דבר ה' ית' אליהם הדעת ג\"כ. אבל טרם שהמשיכו ישראל משרשם בחי' מחשבה עילאה כנ\"ל אין המלאכים יכולים להמשיך אליהם הדעת משרשם דבר ה' ית' מאחר שלא נמשך עדיין אף במחשבה עילאה איך ימצא בבחי' הדבור עליון, כמו עד\"מ א\"א לדבר זולתי כשיחשוב בתחלה במחשבתו צירופי אותיות אלו שרוצה לדבר כנ\"ל. כך עד\"מ למעלה א\"א [להמלאכים] להמשיך מבחי'<sup data-n=\"1399\">48</sup> דבור עליון בחי' הדעת עד שיקדשו אותו מלמטה פי' שימשיכו ישראל [ש]למטה ממקורם ושרשם בחי' מחשבה עילאה אל הדבור, והיינו שע\"י אמירתם קדוש קדוש קדוש<sup data-n=\"1400\">49</sup> כו' נקדישך כו' הם ממשיכים את הדעת מלמעלה מן המחשבה עילאה לתוך המח' עילאה ואח\"כ מהמח[שבה] אל הדבור עליון, אז יוכלו המלאכים להמשיך אליהם הדעת מבחי' דבור עליון ג\"כ ואז אומרים המלאכים ג\"כ קדוש כו' בשביל להשפיע הדעת מהדבור עליון מקורם אל בחי' עולם העשי' אל ישראל שנפלו למטה ונתלבשו בגופי' גשמיי' דעשי' כנ\"ל, ובבחי' ומדרגה א' ישראל הם למעלה מהמלאכים עד שהמלאכי' יצטרכו אליהם שימשיכו אליהם הדעת ממקורם ושרשם מח' עילאה [כנ\"ל, ובבחי' ומדריגה אחת המלאכים למעלה מישראל, עד שישראל מצטרכים שישפיעו אליהם הדעת למטה בעשי' מחמת שנתלבשו בגופים גשמי' דעשי', שמצד שרש שרשם הם למעלה מהמלאכים לכך ממשיכים הם ממקורם הנעלה בחי' מחש'",[["1392","41","<b>ועונין</b>: שם: ואומרים."],["1393","43","<b>דמקדשין ישראל</b>: אה: דישראל מקדשין לי'."],["1394","42","<b>דלא מקדשין. . כולא כחדא</b>: ראה זהר ויחי רלא, א."],["1395","44","<b>ישראל עלו במחשבה</b>: ראה ב\"ר פ\"א, ד. הנסמן לעיל פ' שמות לב, ב."],["1396","45","<b>ישראל. . במחשבה. . המלאכים הוא דבר ה'</b>: ראה גם לעיל לט, ד. וש\"נ."],["1397","46","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["1398","47","<b>עליונה כנ\"ל. . בחי'</b>: אהו: מחשבה עילאה את בחי' הדעת אל בחי' דבר ה' ית', ואזי יוכלו המלאכים להמשיך משרשם בחי'."],["1399","48","<b>מבחי'</b>: שם: ליתא."],["1400","49","<b>קדוש קדוש</b>: שם ליתא."]]],[2300550207,"עילאה אל בחי' הדיבור עליון שרש ומקור המלאכים העליונים כו'] ומצד ירידתם למטה להתלבש בגופים גשמיים דעשי' המלאכים הם נעלים מהם עד שמצטרכים להשפעת המלאכים שישפיעו להם הדעת שכבר נמשך אליהם ע\"י ישראל שלמטה כנ\"ל למטה לעולם העשי' ממש. וזהו וכולם מקבלים דין מן דין<sup data-n=\"1401\">50</sup> כו' שהאחד מצטרך לקבל מחבירו שיש מעלה בזה משא\"כ<sup data-n=\"1402\">51</sup> בזה וכן להיפוך דלא ראי זה כראי זה<sup data-n=\"1403\">52</sup> לכך מצטרכים זה לזה לקבל זה מזה כנ\"ל, ולזאת נאמר ג\"פ קדוש הראשון הוא להמשיך מוח הדעת מלמעלה מהמח' לתוך המחשבה עילאה והשני להמשיך מן המח' אל הדבור עליון והג' מדבור עליון אל בחי' עולם העשי' שזהו ירידת השפע עליונה דרך ג' לבושי עליונים מחדו\"מ כנ\"ל וד\"ל.\n<b>והנה</b> כ\"ז נעשה ע\"י בחי' משה רע\"מ שהוא המשפיע מוח הדעת מריש כל דרגין מבחי' מח' עילאה עד סוף כל דרגין בחי' עולם העשי' ש[י]הי' עובר דרך ג' לבושי' מחדו\"מ כנ\"ל, והנה כתיב בזהר ע\"פ משה משה דלא פסיק טעמא<sup data-n=\"1404\">53</sup> בגוויי' (אבל אברהם אברהם פסיק טעמא<sup data-n=\"1405\">*54</sup> בגווייהו) והיינו שבחי' שפע הדעת הנמשך מבחי' משה רע\"מ לתוך המח' עילאה ובחי' ירידת השפע הנמשך ויורד ממנו לתוך בחי' הדבור ומעשה שוין במהות אחד ממש ולא ישתנו כלל בדמותן ובצלמן כנ\"ל, וזהו משה משה דלא פסיק טעמא בגווייהו כו' וד\"ל. וז\"ש ואלה המשפטי' אשר תשים לפניהם משפט הוא לשון הליכה כדמתרגם על משפט הראשון הלכתא קדמייתא<sup data-n=\"1406\">54</sup> כו' והיינו שעתה הוא בחי' עליות העולמות מדרגא לדרגא <span data-k=\"pg\">תיא</span> ּ עלי' בתר עליי' כו' שז\"ש הליכות עולם לו<sup data-n=\"1407\">55</sup> כו', וע\"ז אמר ואלה המשפטים אשר תשים לפניהם דוקא דהיינו משה ישפיע בחי' הדעת עליון שהוא הפנימי' של המדות שהוא עיקר הקיום של המדות<sup data-n=\"1408\">56</sup> כי אברהם הי' מרכבה לבחי' החסד<sup data-n=\"1409\">57</sup> ויצחק למדת הגבו'<sup data-n=\"1410\">58</sup> כו', אבל משה הי' בחי' הדעת עליון שהוא הפנימי' של המדות חו\"ג אלו המסתעפים ממנו והוא עיקר הקיום שלהם כנ\"ל וע\"ז נאמר אשר תשים לפניהם דוקא לבחי' הפנימי' שלהם (גם לשון לפניהם הוא לשון לפנים שהוא למעלה ומקדם אליהם) וד\"ל.\n(ד) <b>כי</b> תקנה עבד עברי וגו', כתיב קונה שמים וארץ<sup data-n=\"1411\">59</sup> וכתי' בורא שמים וארץ<sup data-n=\"1412\">60</sup> נאמר קונה הכל<sup data-n=\"1413\">61</sup> ונאמר בורא הכל<sup data-n=\"1414\">62</sup>, ההפרש שביניהם [הוא] שבורא שייך בבחי' הבריאה מאין",[["1401","50","<b>וכולם מקבלים דין מן דין</b>: ראה גם מאמרי אדה\"א נ\"ך ע' תקסט."],["1402","51","<b>משא\"כ</b>: אולי צ\"ל: מה שאין."],["1403","52","<b>דלא ראי זה כראי זה</b>: ברכות לה, א."],["1404","53","<b>משה משה דלא פסיק טעמא</b>: נסמן לקמן רפג, ג."],["1405","*54","<b>אברהם אברהם פסיק טעמא</b>: ראה שמו\"ר פ\"ב, ו. זהר וירא קכ, א. מנחת שי שמות ד, ג. קרבן אהרן לתו\"כ ויקרא א, א ספ\"א. בהערה שלפנ\"ז."],["1406","54","<b>משפט הראשון הלכתא קדמייתא</b>: ראה לקמן רפג, ד הערה 111."],["1407","55","<b>הליכות עולם לו</b>: חבקוק ג, ו."],["1408","56","<b>הדעת. . עיקר הקיום של המדות</b>: ראה תניא פ\"ג."],["1409","57","<b>אברהם. . החסד</b>: נסמן לעיל פ' יתרו רנט, א."],["1410","58","<b>ויצחק למדת הגבו'</b>: ראה פרדס (שער הכנויים) שכ\"ב, פ\"ד. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם."],["1411","59","<b>קונה שמים וארץ</b>: לך יד, יט. כב."],["1412","60","<b>בורא שמים וארץ</b>: נסמן לקמן רפד, ב."],["1413","61","<b>קונה הכל</b>: תפילת העמידה."],["1414","62","<b>בורא הכל</b>: בסיום פיסקא זו: בורא את הכל — ע\"פ ברכת יוצר."]]],[2300550239,"ליש שלא כדרך סדר והדרגת ההשתלשלו' כלל שאין הנברא ערך כלל אל הבורא שהבורא קדמון ונצחי והנברא הוה ונפסד כו' אבל כו'<sup data-n=\"1415\">63</sup>, ולכך בחי' הבריאה הוא בחי' התחדשות ממה<sup data-n=\"1416\">64</sup> שנתחדש השפע של הבורא למהות אחר ממש הוא מהות הנברא אשר אין ערך ביניהם כנ\"ל<sup data-n=\"1417\">65</sup>. אבל קונה אינו שייך כ\"א בדרך סדר והדרגת ההשתל' מעילה לעילה שאין משתנה השפע של העילה כשנמשך ממנו העלול זולת בחי' גילוי מן ההעלם, שבעודו עלול ונכלל במקורו עילתו הי' בבחי' התכללות והעלול<sup data-n=\"1418\">66</sup> (שיש בכלל מאתים מנה<sup data-n=\"1419\">67</sup> ) ועתה נתגלה בבחי' גילוי אבל לא נשתנה ממהות למהות כלל בין קודם הגילוי לאח\"כ, ומה גם אין בזה שום חידוש כלל שלא נתחדש [דבר מה] כלל רק אותו הדבר שהי' בבחי' העלם והתכללות נשתנה<sup data-n=\"1420\">68</sup> בבחי' גילוי כנ\"ל. וזהו נק' בחי' קונה כמשל האדם הקונה סחורה שמתחלה קודם לקיחתו הי'<sup data-n=\"1421\">69</sup> הסחורה צפונה וטמונה אצל המוכר או החנוני בקופסא או בחנות ועתה כשהלוקח קנה הסחורה הוציאה מהעלמה לידי גילוי שעשאה למלבוש וכדומה וכה\"ג, והיינו שהסחורה יצתה מרשות לרשות מרשות המוכר לרשות הלוקח ויצתה מהעלמה לידי גילוי עי\"ז כנ\"ל. כך עד\"ז למעלה ענין יציאת השפע מבחי' העלמה שהיתה נכללת במקורה עלתה לידי גילוי בהעלול זהו נק' בחי' קונה שיצתה מרשות לרשות מהעלמה לידי גילוי כנ\"ל, וזהו קונה שמים וארץ קונה הכל כו' כנ\"ל, אבל בחי' בורא הוא בחי' התחדשות ממש מאין ליש שלא כסדר ההשתל' כנ\"ל וזהו מ\"ש בורא שמים וארץ או בורא את הכל כו' וד\"ל.\n<b>וז\"ש</b> כי תקנה עבד עברי כו' שהקב\"ה אמר למשרע\"ה ואלה המשפטים אשר תשים אתה דוקא לפניהם והיינו ע\"י שתקנה עבד עברי וז\"ש לי<sup data-n=\"1422\">70</sup> דוקא כי תקנה ע\"ע וגו'. והענין הוא דכתי' בעבר הנהר ישבו אבותיכם מעולם<sup data-n=\"1423\">71</sup>, הנהר הידוע הוא בחי' נהר עליון דכתי' ונהר יוצא מעדן<sup data-n=\"1424\">72</sup> להשקות את הגן ומשם יפרד והי' לארבעה ראשים וגו', פי' כללי סדרי ההשתלשלו' דעולם האצי' נק' בחי' נהר היוצא מעדן להשקות את הגן שנמשך השפע מריש כל דרגין ויורד ומשתלשל למטה עד שמשקה את הגן, ומשם יפרד והי' לד' ראשים וגו' דהיינו שבבריאה מתחלק השפע לד' חלקים שהוא <span data-k=\"pg\">824</span> ּ עלמא דפרודא משא\"כ באצי' הוא עולם האחדות הוא רק נהר א' היוצא מעדן כנ\"ל ששם תכלית היחוד כנודע, ובעבר הנהר עליון הנ\"ל שהוא למעלה מבחי' נהר עליון הנ\"ל דהיינו למעלה מסדר ההשתל' ישבו אבותיכם, ולכך נק' ישראלים בשם עברים כמ\"ש עברי אנכי<sup data-n=\"1425\">73</sup> וגו' ע\"ש בעה\"נ שישבו אבותיכם מעולם כו'. והיינו",[["1415","63","<b>אבל כו'</b>: כ\"ה גם בהכת\"י."],["1416","64","<b>ממה</b>: הו: ממש."],["1417","65","<b>כנ\"ל</b>: גדו: כלל."],["1418","66","<b>והעלול</b>: אהו: והעלם."],["1419","67","<b>שיש בכלל מאתים מנה</b>: ב\"ק עד, א."],["1420","68","<b>נשתנה</b>: אהו: נתגלה."],["1421","69","<b>הי'</b>: שם: הימנו. ג: היתה."],["1422","70","<b>לי</b>: אוצ\"ל ל\"י לשון יחיד. אהו: לו."],["1423","71","<b>בעבר הנהר. . מעולם</b>: יהושע כד, ב."],["1424","72","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["1425","73","<b>עברי אנכי</b>: יונה א, ט."]]],[2300550270,"שבעבה\"נ שהוא למעלה מההשתל' שם הוא למעלה מבחי' התחלקות המדרגות מעלה ומטה נשמות ומלאכים זרע אדם וזרע בהמה כנ\"ל, ששם הקטן והגדול שוין בערך א' כלא חשיבי ואין יתרון לגדול על הקטן שכולם שוין בערך א' בבחי' הביטול לפניו כי שוה ומשוה קטן וגדול<sup data-n=\"1426\">74</sup> וכמ\"ש אדם ובהמה תושיע הוי'<sup data-n=\"1427\">75</sup> בשוה להאדם והבהמה כנ\"ל, וע\"ז נאמר כי תקנה עבד עברי שמשרע\"ה קונה את בחי' העבד עברי שהי' בעבה\"נ העליון בבחי' ההעלם מהעלם לגילוי שיתגלה למטה וימשיך דעת בכולם אף בבחי' זרע בהמה, כי זה שהם זרע בהמה הוא בסדר והדרגת ההשתל' ששם ימצא התחלקות המדרגות מעלה ומטה קטן וגדול כנ\"ל, אבל משה הוא בחי' ע\"ע שנמשך מעה\"נ העליון מהעלם לגילוי ששם שוה מעלה ומטה קטן וגדול כנ\"ל, וזהו כי תקנה שמשה הוא הקונה את בחי' ע\"ע מהעלם אל הגילוי בשביל השפעת הדעת אף בזרע בהמה כנ\"ל וד\"ל.\n(ה) <b>שש</b> שנים יעבוד וגו', כתיב ואברהם זקן בא בימים<sup data-n=\"1428\">76</sup> וכ' בזהר ע\"ז בא בימים ממש באינון יומין דאינון קריבין לי' כו' ע\"ש, פי' ימים הם בחי' לבושים שהימים שהאדם חי ע\"פ האדמה ע' שנה או פ' שנה ומקיים בהם תומ\"צ זהו בחי' הלבושים הנעשים בימים ושנים שתחת הזמן דוקא מהימים שנמשכו מלמעלה מהזמן להתלבש בבחי' הזמן וע\"ז נא' ימים יצרו ולא אחד בהם<sup data-n=\"1429\">77</sup> וגו', דהיינו כמ\"ש והיתה נפש אדוני<sup data-n=\"1430\">78</sup> צרורה בצרור החיים את ה' אלקיך פי' שתכלית הכל מוכרח כאו\"א מישראל להתעלות למעלה להיות צרורה בצרור החיים את ה' כו' ליהנות מזיו השכינה בה' ולאשתאבא בגופא דמלכא<sup data-n=\"1431\">79</sup> כו', והיינו ע\"י תומ\"צ שקיים בעוה\"ז תחת הזמן בימים ושנים שחי ע\"פ האדמה וקבל מזיו השכינה ב\"ה ועונג עליון נועם ה' ית', בהיות התומ\"צ נק' בחי' גופא ממש שע\"י דוקא ישתאב בגופא דמלכא להיות צרורה בצרור החיים בהלבושי' דתומ\"צ כנ\"ל (משא\"כ המדות אהוי\"ר הם רק גדפין<sup data-n=\"1432\">80</sup> לפרחא לעילא כנ\"ל ). וז\"ש שש שנים יעבוד שש שנים הן השית אלפי שני<sup data-n=\"1433\">*81</sup> דהוה עלמא<sup data-n=\"1434\">81</sup> שהוא זמן העבודה כי היום לעשותם<sup data-n=\"1435\">82</sup> דוקא, והיינו שיעבוד הוא לשון עיבוד עורות שהעבד עברי הוא בחי' משרע\"ה הוא יעבוד את התומ\"צ שנשפלו למטה בגשמיות בעניני עוה\"ז הגשמי' שצריך לברר ולינק<sup data-n=\"1436\">83</sup> אותם ולרחוץ ולכבס אותם במים עליונים ממקורו עה\"נ העליון וכמשל ה[מ]לבוש גשמי שרוחצים אותו<sup data-n=\"1437\">84</sup> ומכבסים אותו במים טהורים אז יהי' צח ונקי מלובן. כך משה בחי' הדעת עליון מזכך הלבושי' דתומ\"צ שנתלבשו בענינים גשמיים ע\"י מוח הדעת עליון שעי\"ז מזדככים",[["1426","74","<b>שוה ומשוה קטן וגדול</b>: ע\"פ פיוט (לימים נוראים) האוחז ביד מדת משפט."],["1427","75","<b>אדם ובהמה תושיע הוי'</b>: תהלים לו, ז. ראה גם לקמן רפה, א."],["1428","76","<b>ואברהם זקן בא בימים</b>: נסמן לקמן רפה, ב."],["1429","77","<b>ימים יצרו ולא אחד בהם</b>: תהלים קלט, טז. ראה לעיל פ' יתרו רעו, ג. וש\"נ."],["1430","78","<b>והיתה נפש אדוני</b>: ראה גם לקמן רפה, ב. וש\"נ."],["1431","79","<b>ולאשתאבא בגופא דמלכא</b>: נסמן לעיל רסט, ד."],["1432","80","<b>אהוי\"ר. . גדפין</b>: ראה תניא פ\"מ. מאמרי אדה\"א בראשית ע' עה. וש\"נ."],["1433","*81","<b>שש שנים יעבוד. . השית אלפי שני</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' רנז וע' רפב (נו\"ש). תו\"א עו, א. ג. לקמן רפא, ג. רפו, ב. רצב, ג. פ' ויקהל תלא, א."],["1434","81","<b>השית אלפי שני דהוה עלמא</b>: ראה ר\"ה לא, א. הנסמן במאמרי אדה\"א בראשית ע' נג."],["1435","82","<b>היום לעשותם</b>: ואתחנן ז, יא."],["1436","83","<b>ולינק</b>: ה: ולנקות."],["1437","84","<b>אותו</b>: א: כבפנים. הו: ליתא."]]],[2300550298,"בזיכוך מעלה<sup data-n=\"1438\">85</sup> וכמ\"ש כעדר הרחלים שעלו מן הרחצה<sup data-n=\"1439\">86</sup>, שמשה הוא רע\"מ כרועה ירעה עדרו<sup data-n=\"1440\">87</sup> <span data-k=\"pg\">תיב</span> ּ שצריך להאכילן עשב השדה ולרחוץ אותם מצואתם כו', כך משה משפיע בחי' עשב השדה כנ\"ל וגם רוחץ עדרו במים עליונים דעבר הנהר עליון לזכך הלבושים דתומ\"צ כנ\"ל וכמ\"ש רוחצות בחלב<sup data-n=\"1441\">88</sup> כו' שממשיך בהן בחי' לובן העליון, וזהו בחי' ליבון הלכתא שמלבין ההלכה בלובן העליון כנ\"ל וזהו ע\"י התפלה שתקנו רבנן שבזמן התפלה מתגלה דעת עליון ועי\"ז נזדככו הלבושי' כנ\"ל<sup data-n=\"1442\">89</sup> דתומ\"צ כנ\"ל וד\"ל [ו]כדרז\"ל על צדיקים אין להם מנוחה<sup data-n=\"1443\">90</sup> לא בעוה\"ז ולא לעוה\"ב כו', אבל באלף השביעי יהי' מנוחה<sup data-n=\"1444\">91</sup> לחיי העולמים אזי יצא לחפשי חנם חנם בלא מצות<sup data-n=\"1445\">92</sup> כנ\"ל<sup data-n=\"1446\">93</sup> וד\"ל.",[["1438","85","<b>מעלה</b>: שם: נעלה."],["1439","86","<b>כעדר הרחלים שעלו מן הרחצה</b>: שה\"ש ו, ו."],["1440","87","<b>כרועה ירעה עדרו</b>: ע\"פ ישעי' מ, יא."],["1441","88","<b>רוחצות בחלב</b>: שה\"ש ה, יב."],["1442","89","<b>כנ\"ל</b>: א: כבפנים. הו: ליתא."],["1443","90","<b>צדיקים אין להם מנוחה</b>: ראה תרגום לתהלים פד, ח. מאמרי אדה\"א ויקרא ח\"א ע' מו. וש\"נ."],["1444","91","<b>באלף השביעי יהי' מנוחה</b>: ראה גם לעיל פ' בשלח רכא, ב. וש\"נ."],["1445","92","<b>חנם בלא מצות</b>: ראה גם לעיל פ' שמות א, ב. וש\"נ."],["1446","93","<b>כנ\"ל</b>: כן הוא גם בהכת\"י."]]],[2300550048,"<b>בעז\"ה ביאור על הנ\"ל.</b>\n[ו] <b>להבין</b> שרש הדברים הנ\"ל<sup data-n=\"1447\">1</sup> באר היטב, איתא בס' התמונה<sup data-n=\"1448\">2</sup> דהאי עלמא הוא בחי' שמיטה שני' שמיטת הפחד, דהיינו כל וי\"ו אלפי שנין דהוי עלמא<sup data-n=\"1449\">3</sup> וחד חרוב הוא בחי' שמטה [שני'] שנק' שמטת הפחד וקודם לזה הי' שמטת החסד לכל וי\"ו אלפי שנין שהיתה באופן אחר ממש בדקות ורוחניות יותר שהתורה הי' באופן אחר והעבודה הי' באופן אחר ובנ\"א היו כמלאכים כו', ועתה בשמיטה זו השני' ממדת הגבו' שנק' שמטת הפחד העולם מגושם ביותר ועברו כל הצרות לישראל בחורבן בית ראשון ובית שני כו' הכל מצד שנמשכה ממדת הגבו' והפחד כו'. והנה ב' נשמות [לבד] נמשכו משמיטה ראשונה לשמיטה זו לתקן העוה\"ז והם חנוך ומשה כו' כמשנ\"ת<sup data-n=\"1450\">4</sup> וכמ\"ש במשה כי מן המים משיתיהו<sup data-n=\"1451\">5</sup> פי' כי הוא נמשך משמיטה הראשונה שהוא שמיטת החסד שנק' מים<sup data-n=\"1452\">6</sup> ולז\"א כי מן המים משיתיהו וגו' ולזאת ירדו ונמשכו ב' נשמות אלו משמיטה הראשונה לשמיטה שני' לתקן את השמיטה זו כו' וד\"ל. וז\"ש כי תקנה עבד עברי<sup data-n=\"1453\">7</sup> שמשרע\"ה נק' ע\"ע מצד שרשו שנמשך מעבר הנהר עליון הידוע שהוא למעלה מסדר ההשתל' כו' כנודע ולזה אמר לו הקב\"ה כי תקנה ע\"ע וגו', ותחלה צריך להבין [היטב] ענין ההפרש בין קונה לבורא הנ\"ל בתו[רה] ע\"ש.",[["1447","1","<b>להבין שרש הדברים הנ\"ל</b>: מאמר זה הוא הנחת הר' משה בן כ\"ק אדה\"ז ונדפסה גם במאמרי אדה\"ז תקס\"ה ח\"א ע' רסב (נוסח א'). ושם נדפסה גם הנחת כ\"ק אדה\"א (נוסחא שני'). ובשינויים בתו\"א משפטים עו, ב. במאמרי אדה\"ז שם ע' רפז נמצא גם ביאור שני מהנחת הר\"מ. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["1448","2","<b>איתא בס' התמונה</b>: ראה גם לעיל פ' שמות מג, א. וש\"נ."],["1449","3","<b>וי\"ו אלפי שנין דהוי עלמא</b>: ראה ר\"ה לא, א. הנסמן במאמרי אדה\"א בראשית ע' נג."],["1450","4","<b>ב' נשמות. . חנוך ומשה כו' כמשנ\"ת</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' קעט. לעיל פ' שמות מג, ד."],["1451","5","<b>כי מן המים משיתיהו</b>: שמות ב, י."],["1452","6","<b>החסד שנק' מים</b>: ראה זהר תרומה קסז, א. קעה, ב. שמיני מא, א. מאמרי אדה\"א דברים ח\"ד ע' א'שצב. וש\"נ."],["1453","7","<b>כי תקנה עבד עברי</b>: משפטים כא, ב."]]],[2300550080,"<b>הנה</b> ידוע ההפרש בין בחי' סדר והדרגת ההשתלשלו' בהדרגה וסדר מעילה לעלול וממדרגה למדרגה ובין בחי' [ש]למעלה מסדר ההשתל' שאינו נמשך בסדר והדרגת ההשתל' כ\"א בבחי' דילוג ממהות למהות שלא כדרך השתלשלו', והיינו כמו עד\"מ בנפש האדם שמבשרי אחזה אלוה<sup data-n=\"1454\">8</sup> כו' שהמדות נמשכות מהשכל כי לפי שכלו יהולל איש<sup data-n=\"1455\">9</sup> שהקטן שאין לו דעת מתאווה לדברים קטנים והגדול שיש לו דעת מתאוה לדברים גדולים שלפי ערך השגת שכלו כך ערך מדותיו שנמשך אחר הדברים [האלה] ששכלו משגת כו', מפני שהמדות נמשכות מהשכל בסדר והדרגה שיש להם ערך ויחוס אל השכל שבאופן מהות השכל כך הוא ערך המדות כו' ומהשכל<sup data-n=\"1456\">10</sup> נמשכת המחשבה ומהמח' הדבור כו', וכ\"ז נק' סדר והדרגת ההשתל' דרך עילה ועלול שנמשכים בסדר והדרגה שהעלול יש לו ערך ויחוס אל העילה שלו כו' כנ\"ל. ויש עוד בחי' ומדרגה בנפש האדם שבאה אליו שלא בערך<sup data-n=\"1457\">11</sup> סדר והדרגת ההשתל' כ\"א בבחי' דילוג כו', והיינו כענין מארז\"ל אע\"ג דאינהו לא חזו<sup data-n=\"1458\">12</sup> מזלייהו חזי שכאשר האדם מפחד ואינו יודע ממה [הוא] מפחד כו' ע\"ז ארז\"ל אע\"ג דאיהו לא חזי מזלי' חזי שהפחד נמשך אליו מבחי' המזל שלו שלמעלה מבחי' הדעת והשכל <span data-k=\"pg\">826</span> ּ שלא כדרך ההשתל' כו'.\n<b>אך</b> באמת א\"א למצוא בחי' ומדריג' זה שלמעלה מהשתלשלות בנפש האדם להרחיב הביאור בזה זולת למעלה נוכל לבאר יותר להבין הדבר [ע]ל מתכונתו כו', בהיות ידוע שיש בחי' עגולים ויושר<sup data-n=\"1459\">13</sup> למעלה פי' יושר הוא כללות סדרי ההשתל' שבינה נמשכה מן החכ' בסדר והדרגה עד שיש לה ערך ויחוס אלי' כו' וכן המדות מבינה כנ\"ל במשל מע\"ס הנאצלי' נמשכו ע\"ס דבריאה כו' וכ\"ז הוא בחי' יושר שהוא סדר השתלשלו' העולמות אבי\"ע כו', ובחי' עיגולי' הוא למעלה מן ההשתל' הכולל הכל יחד בסקירה אחת ומקיף מכל צד בהשוואה אחת ואין נמצא בו בחי' מעלה ומטה כלל, כמשל עיגול הגשמי שאין נמצא בו מעלה ומטה כלל כמו הארץ גשמי' היא כדורית<sup data-n=\"1460\">14</sup> עגולה כתפוח כו' שאין נמצא בה בחי' מעלה ומטה<sup data-n=\"1461\">15</sup> כלל פי' שבנ\"א היושבים על הארץ נדמה להם שהם למעלה אשר בנ\"א הדרים [לנגדם] תחתיהם ממש (בעולם החדש אמעריקא<sup data-n=\"1462\">16</sup> ) הם",[["1454","8","<b>שמבשרי אחזה אלוה</b>: איוב יט, כו. ראה הנסמן לעיל פ' בא צח, ב."],["1455","9","<b>לפי שכלו יהולל איש</b>: משלי יב, ח. ראה גם לעיל פ' בשלח רמא, א."],["1456","10","<b>ומהשכל</b>: אהו: ומן המדות."],["1457","11","<b>בערך</b>: שם: כדרך."],["1458","12","<b>אע\"ג דאינהו לא חזו</b>: ראה מגילה ג, א."],["1459","13","<b>עגולים ויושר</b>: ראה גם לעיל פ' שמות כג, ד. כז, ב."],["1460","14","<b>הארץ גשמי' היא כדורית</b>: נסמן לעיל פ' בשלח רמ, א."],["1461","15","<b>הארץ. . שאין. . מעלה ומטה</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"ב ע' תעה וע' תעז."],["1462","16","<b>אמעריקא</b>: ראה גם תורת חיים בראשית מג, ג ובהערה 22. מאמרי אדמו\"ר ה”צמח צדק\" תרי\"ד ע' ט."]]],[2300550112,"עומדים ברגליהם למעלה ופניהם למטה והיו מצטרכים ליפול לגמרי, אך באמת לגבי בנ\"א שלמטה נדמה שהם למעלה ואלו למטה, ובאמת כך הוא ששניהם למעלה שבדבר כדורית לא ימצא [בו] בחי' מעלה ומטה שאותם העומדים בצד דרום נדמה להם שאותם הצפונים הם למטה ואלו הצפונים נדמה להם להיפוך כו'. וכמו שהוא למטה בגשמי' כן שבעיגול הגשמי אין בו מי שימצא ראש וסוף מעלה ומטה כלל, כך עד\"מ למעלה ממש בבחי' עיגולים הם המקיפים שלמעלה שנק' בחי' סוכ\"ע שלמעלה מבחי' ההשתל' הכוללם יחד בסקירה א' כולם כא' מראש לסוף בהשוואה א' ממש לכל צד בלי שימצא ראש וסוף כלל והיינו כענין מארז\"ל בכמה מקומות בש\"ס גלוי וידוע לפני מי שאמר והי' העולם<sup data-n=\"1463\">17</sup> ולא אמרו הוא יודע הכל כו', בהיות הרמב\"ם ז\"ל כתב שהוא היודע והוא הידוע והוא המדע<sup data-n=\"1464\">18</sup> כו' אין לך דבר שחוץ ממנו ית' ודבר זה אין הפה יכולה לאומרה ע\"ש, בהיות המאציל ב\"ה הוא רם ונשא לבדו מופשט מגדרי התוארים אלו בתכלית הפשיטות עד שהע\"ס דאצי' אין להם ערך ויחוס אליו כלל ולכן כאשר נתארו בתואר זה שהוא היודע שזהו כפי הדעת הנמנה בין הע\"ס דאצי' זהו שפלות גדול קמי' ית', ומה גם בבחי' הדעת ימצא בבחי' מעלה ומטה כאדם היודע ומקיף בדעתו שמצייר בדעתו כדומה שמים וארץ ובנ\"א שעליה תחלה מקיף ומצייר בדעתו הראש הוא השמים ואח\"כ הארץ ובנ\"א כו' כדומה שנתפס בציור שכלו ודעתו הראש קודם לסוף, דלא סגי בלא\"ה שיתפוס דעת כולם כא' בסקירה א' בלתי שתתפשט תחלה בדעתו הראש ואח\"כ הסוף מפני שדעתו מתלבשת בתפסו הדבר ההוא והדבר ההוא נתפס בו ומוקף בו ולכך לא סגי בלא\"ה כו'. ולכן כאשר נתאר את המאציל ית' ג\"כ בזה שהוא היודע את כל סדרי ההשתל' עולמות אבי\"ע כו' מרכ\"ד עד סוכ\"ד שיודע אף מחשבת בנ\"א שלמטה שחושב בחדרים כו'<sup data-n=\"1465\">19</sup> אין לך כ\"ד נעלם [ממך] כו' מוכרח להיות שהוא מתלבש בבחי' הדעת לידע מציאות כל הנבראים<sup data-n=\"1466\">20</sup> הנפעלים מראש ועד סוף ימצא בו בחי' ראש וסוף שבדעתו יהי' מוקף תחלה הראש הנפעלים <span data-k=\"pg\">תיג</span> ּ עליונים דאצי' ואח\"כ דבי\"ע כסדר השתלשלותן כו', אבל באמת המאציל ב\"ה מופשט מגדר התוארים אלו בתכלית הפשיטות ואין בו מי שימצא ראש וסוף כלל כי הוא השוה ומשוה קטן וגדול<sup data-n=\"1467\">21</sup> שכולם בערך א' כלא חשיבי קמי' [ית'], ואעפ\"כ הוא צופה ומביט עד סוף כל הדורות<sup data-n=\"1468\">22</sup> בכל פרטי פרטיות של הנבראי' אף מחשבות לבות האדם שבחדרי חדרים אין לך כ\"ד נעלם ממנו כו' [כי] זהו כדרז\"ל הכל גלוי וידוע<sup data-n=\"1469\">23</sup> לפני מי שאמר והי' העולם, שאין הוא היודע את כולם שיתלבש בבחי' הידיעה וידע את כולם כי הוא מופשט מגדר התוארים",[["1463","17","<b>גלוי וידוע. . העולם</b>: ערובין יג, ב. ועוד. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' קכה. תו\"א יד, ד. לקו\"ש קרח כרך יח ע' 197 בהערה."],["1464","18","<b>שהוא היודע. . המדע</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ב, ה\"י."],["1465","19","<b>כו'</b>: אהו: כי."],["1466","20","<b>הנבראים</b>: או: ליתא. ה: כבפנים."],["1467","21","<b>השוה ומשוה קטן וגדול</b>: פיוט (לימים נוראים) האוחז ביד מדת משפט."],["1468","22","<b>צופה ומביט. . הדורות</b>: מוסף לר\"ה (ברכת זכרונות)."],["1469","23","<b>הכל גלוי וידוע</b>: ראה לעיל הערה 17."]]],[2300550144,"אלו לגמרי והידיעה הוא ממנין התוארים דע\"ס דאצי' כ\"א הכל גלוי וידוע לפניו, שהידיעה ממציאת כל הנפעלים בא לפניו לכך יתקשרו<sup data-n=\"1470\">24</sup> כולם בסקירה א' מבלי שימצא ראש וסוף כלל דהיינו שבחי' הידיעה ממחשבות לבות בנ\"א דעשי' החושב בחדרי חדרים בא לפניו והידיעה הראשיות מהנפעלים דאצי' כדומה כולן באין כא' בסקירה א' נסקרים להיות הכל גלוי וידוע לפניו דוקא כנ\"ל. וזהו בחי' העיגולים שלמעלה מהשתלשלו' עולמות אבי\"ע הכוללם יחד בסקירה א' מבלי שימצא ראש וסוף כלל והיינו בחי' כתר דאצי' שמל' דא\"ק נעשה כתר לאצי'<sup data-n=\"1471\">25</sup> המקיף הגדול הכוללם יחד בסקירה א' מבלי שימצא ראש וסוף כלל כנ\"ל וד\"ל.\n<b>והנה</b><sup data-n=\"1472\">26</sup> בדרך פרט אף בסדר ההשתלשלו' עולמות אבי\"ע ימצא בחי' המקיפים שלמעלה מההשתל' המקיף לכולם כא' בהשווא' אחת [מכל צד] מבלי שימצא ראש וסוף כו', והיינו כמו בחי' תחתונה דאצי' הוא בחי' מל' דאצי' נעשי' ראש לעולם הבריאה בחי' עתיק דבריאה<sup data-n=\"1473\">27</sup> שכל סדר ההשתל' של עולם הבריאה נסקרים בסקירה אחת בלי שימצא ראש וסוף שלגבי עולם הבריאה נחשבת היא לבחי' מקיף וסובב שלמעלה מן ההשתל' עד שהוא כוללם יחד בסקירה אחת כנ\"ל וכן מל' דבריאה נעשה עתיק ליצי'<sup data-n=\"1474\">28</sup> כו' ומל' דיצי' נעשה עתיק לעולם העשי'<sup data-n=\"1475\">29</sup> כו' כנ\"ל שכל עולם שלמטה בטל ונכלל בהעליון [הימנו] בתכלית ההתכללו' ונסקרו בסקירה אחת מבלי שימצא ראש וסוף כנ\"ל וד\"ל.\n[ז<sup data-n=\"1476\">30</sup> ] וז\"ש ואלה המשפטים<sup data-n=\"1477\">31</sup> אשר תשים לפניהם, פי' תחלה בפ' יתרו<sup data-n=\"1478\">32</sup> נא' עשרת הדברות ששמעו ישראל מפי הקב\"ה בכבודו ובעצמו ואמרו למשה דבר אתה [עמנו] ונשמעה [פן]<sup data-n=\"1479\">33</sup> כו', שלא יכלו לקבל השפע מפי הקב\"ה בכבודו ובעצמו זולת ע\"י הממוצע הוא משרע\"ה שהי' נשמתו מעבה\"נ העליון הידוע שהוא בחי' המקיפי' שלמעלה מבחי' ההשתל' כנ\"ל. ולזאת נאמר ואלה המשפטים אשר תשים לפניהם שאמר הקב\"ה למשה שהוא ישים המשפטים לפניהם שיהא עובר השפע אליהם ע\"י משה דוקא והיינו מ\"ש כי תקנה ע\"ע שש שנים יעבוד כו', והיינו כמש[נת\"ל] בתורה שמשה הוא בחי' הדעת עליון שהוא רעי' מהימנא הרועה וזן את ישראל להשפיע [להם] בחי' הדעת עליון שהוא פנימי' המדות, לעבוד הוא ל' עיבוד עורות לברר את המדות ולאהפכא מחשוכא לנהורא להפוך את המדות לקדושה להיות עבודם באופן אחד<sup data-n=\"1480\">34</sup> ממש, שכ\"ז עושה בחי' משרע\"ה שנק' רע\"מ<sup data-n=\"1481\">35</sup> שנמשך מעבה\"נ העליון כמ\"ש בו כי מן המים",[["1470","24","<b>יתקשרו</b>: אהו: יסקרו."],["1471","25","<b>שמל' דא\"ק נעשה כתר לאצי'</b>: ראה ע\"ח (שער סדר אצי') ש\"ג, פ\"ב. לקו\"ת מסעי צה, ב."],["1472","26","<b>והנה</b>: א: נדפס כאן: פ\"ו."],["1473","27","<b>מל' דאצי' נעשי'. . עתיק דבריאה</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"ב. בהערה הבאה."],["1474","28","<b>מל' דבריאה. . ליצי'</b>: ראה ע\"ח (שער כסה\"כ) שמ\"ו, פ\"ב. פ\"ד. פ\"ו."],["1475","29","<b>ומל' דיצי'. . לעולם העשי'</b>: ראה ע\"ח שם."],["1476","30","<b>ז</b>: א: כבפנים. בג: ו. דה: לא נסמן."],["1477","31","<b>ואלה המשפטים</b>: משפטים כא, א."],["1478","32","<b>בפ' יתרו</b>: כ, א ואילך."],["1479","33","<b>דבר אתה [עמנו] ונשמעה [פן]</b>: שם כ, טז [בדילוג]."],["1480","34","<b>אחד</b>: אהו: אחר."],["1481","35","<b>רע\"מ</b>: שם: עבד עברי."]]],[2300550176,"משיתיהו שנמשך משמיטת החסד שמיטה ראשונה לעבוד הוא <span data-k=\"pg\">828</span> ּ ולברר ולתקן את העוה\"ז דקיימא וא\"ש, וז\"ש שש שנים יעבוד המה הוי\"ו אלפי שנין מהאי עלמא שמשה הוא המברר אותן כו'.\n<b>ביאור</b> הענין הוא דהנה כתי' וזרעתי את בית ישראל<sup data-n=\"1482\">36</sup> זרע אדם וזרע בהמה וגו', פי' שיש ב' בחי' ומדרגות בכנס\"י, הא' הוא בחי' זרע האדם שהמה הנשמות הגבוהות דאצי' כמו נשמות הנביאים והמיוחד שבתנאים כמו רשב\"י<sup data-n=\"1483\">37</sup> וחביריו שנמשכי' מבחי' אדם העליון דאצי' שרוכב על הכסא שהוא בבחי' שם מ\"ה דתיקון דאצי' שלא הי' בשבירה מעולם, שהנשמות אלו א\"צ לברר א\"ע כלל כי אין מעורב בנפשותם בחי' רע כלל מאחר שנמשכו מאצי' [התיקון] שלא יגור במגורו רע כלל ח\"ו, רק שכל<sup data-n=\"1484\">38</sup> עבודתם בעוה\"ז הי' באופן אחד ממש שכל עסקם בתומ\"צ הי' בכדי להוסיף אורות באצי' כנודע ולא בשביל לברר בירורי נוגה כו'. והשני' הוא בחי' זרע בהמה שהמה הנשמות דבי\"ע שנמשכו מהניצוצים דתהו שנפלו דרך שבירה לבי\"ע שאלו נק' זרע בהמה ע\"ש בהמה רבה שלמעלה מקור דבי\"ע שלשם נפלו הניצוצות דתהו דרך שבירה שהמה מעורבים טו\"ר יחד (או מחטא דעה\"ד דאדה\"ר המעורב טו\"ר כנ\"ל<sup data-n=\"1485\">39</sup> ) אזי לזאת צריכים לברר הטוב שבהן מן הרע ולהפרידם זמ\"ז בתכלית התבררות כו'. והנה ידוע כי בחכמה אתברירו<sup data-n=\"1486\">40</sup> דוקא ע\"י [חכמה] כח מ\"ה<sup data-n=\"1487\">41</sup> הוא ש' מ\"ה דתיקון דאצי' [מתבררי' הניצוצין דתוהו שנפלו בשבירה לבי\"ע וע\"י משרע\"ה שנמשך מבחי' חכמה<sup data-n=\"1488\">42</sup> הוא שם מ\"ה התיקון דאצי'] הוא עיקר המברר אותן כנ\"ל, ולזאת הי' רועה נאמן של ישראל שהשפיע בתוך הזרע בהמה בחי' הדעת עליון שע\"י דוקא יוכל לעבוד ולברר הטוב מן הרע ולאהפכא חשוכא לנהורא כנ\"ל.\n<b>וז\"ש</b> משה [בעצמו] ונתתי עשב בשדך לבהמתך<sup data-n=\"1489\">43</sup> כרועה ירעה עדרו שמראה לבהמתו מרעה טוב ושמן עשב השדה והם אוכלים מעשב השדה מקום מרעיתן שהראה להם הרועה וחיים<sup data-n=\"1490\">44</sup> ממש ויש טלאים אשר אינם יכולים לילך<sup data-n=\"1491\">45</sup> בעצמם לאכול מעשב השדה אזי הרועה מאכילן ומלעיטן כו' כמ\"ש כרועה עדרו ירעה<sup data-n=\"1492\">46</sup> בזרועו יקבץ טלאיו<sup data-n=\"1493\">47</sup> ובחיקו ישא כו', כך [עד\"מ למעלה] משה [הוא בחי' רועה נאמן הרועה את ישראל להשפיע<sup data-n=\"1494\">48</sup> ] בזרע בהמה המה הנשמות הנמשכי' מבי\"ע בחי' דעת עליון שיוכלו עי\"ז לברר ולהפוך את המדות לקדושה ולהפריד הטוב מן הרע כו' והיינו דכתיב ונתתי עשב בשדך לבהמתך וגו', פי' שדה",[["1482","36","<b>וזרעתי את בית ישראל</b>: נסמן לעיל רעז, א."],["1483","37","<b>הנשמות הגבוהות דאצי'. . רשב\"י</b>: ראה גם לעיל רז, ד. וש\"נ."],["1484","38","<b>שכל</b>: אהו: ליתא."],["1485","39","<b>כנ\"ל</b>: שם: כו'."],["1486","40","<b>בחכמה אתברירו</b>: ראה זהר (היכלות) פקודי רנד, סע\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה־ שמות ח\"ב ע' שכא."],["1487","41","<b>[חכמה] כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["1488","42","<b>חכמה</b>: גו: ח\"ע."],["1489","43","<b>ונתתי עשב בשדך לבהמתך</b>: עקב יא, טו."],["1490","44","<b>וחיים</b>: אהו: [ו]לחמם."],["1491","45","<b>לילך</b>: שם: ליקח."],["1492","46","<b>כרועה עדרו ירעה</b>: ישעי' מ, יא."],["1493","47","<b>טלאיו</b>: א: טלאים."],["1494","48","<b>הוא. . להשפיע</b>: בתו\"ח: משפיע."]]],[2300550208,"העליונה הוא בחי' חקל תפוחין קדישין<sup data-n=\"1495\">49</sup> בחי' מל' דאצי' שנק' שדה כנודע שמשה משפיע בהשדה העליונה בחי' עשב לבהמתך המה הנשמות דבי\"ע שינקו מן העשב ההוא ויקבלו חיותם כו'. והיינו שעשב הוא בחי' ש[ם] ע\"ב ושי\"ן<sup data-n=\"1496\">50</sup> באמצע התיבה כו', פי' ש[ם] ע\"ב הוא מדת החסד<sup data-n=\"1497\">51</sup> עליון שנק' בחי' מים שיורדי' מגבוה לנמוך<sup data-n=\"1498\">52</sup> שנשפעו מלמעלה מבחי' משה ד\"ע דאצי' למטה לבהמתך הם הנשמות דבי\"ע כנ\"ל, אך השי\"ן שבאמצע התיבה בא להורות שבהדעת הנשפע מבחי' משה כלולים ג' קוין עליונים דאצי' המה ג' אבות שהם חג\"ת<sup data-n=\"1499\">53</sup> דאצי' כצורת השי\"ן שהוא בג' קוין כנ\"ל, והיינו שהדעת הוא פנימי' [המדות] שכולל ג' קוין חג\"ת ביחד והוא עיקר המקיים של המדות<sup data-n=\"1500\">54</sup> והוא עיקר המברר אותן לאהפכא מחשוכא לנהורא כנ\"ל, כנראה בעליל בנפש האדם המעורב טו\"ר יחד שמתאוה בטבעו לכל חפצי עוה\"ז <span data-k=\"pg\">תיד</span> ּ [כל] התאוות רעות והגאוה ודומיהן כל המדות מגונות הרעות כו' וגם נמצא בו בחי' הטוב הוא האהבה והתשוקה לה' ית' כנ\"ל, אך הטו\"ר מעורבים יחד בתכלית התערובות ולזאת הדעת הוא המבדיל ומפריד הטוב מן הרע להיות הטוב מתברר בתכלית ההתבררות והרע יופרד בפ\"ע וידחה לחוץ כו'. והיינו שע\"י השכל לבדו לא יתברר הטוב שבנפשו להתהפך לקדושה כלל שאף כשישכיל בדעתו<sup data-n=\"1501\">55</sup> גדולת ורוממות האל ית' איך שכולא קמי' כ\"ח<sup data-n=\"1502\">56</sup> אעפ\"כ לא תתהפך לבבו לה' לבדו ולא להתאוות תאוות עוה\"ז כו' זולת ע\"י דעת דוקא יוכל להמשיך<sup data-n=\"1503\">57</sup> מדותיו לה' לבדו, מפני שהדעת הוא בחי' ההרגשה שמרגיש אלקות בבחי' הרגשה וגילוי ממש כמו שמרגיש חיי נפשו בהרגשה ממש כך ירגיש חיות אלקי הנשפע בכל העולמות כמ\"ש כי הוא חייך<sup data-n=\"1504\">58</sup> שירגיש החיות הנשפע בכל העולמות ממקור החיים כחיי נפשו ממש וע\"ז אמר לאהבה את ה'<sup data-n=\"1505\">59</sup> כי הוא מקור החיים לכל חי כו', אבל מצד השכל אע\"פ שמשכיל בשכל אעפ\"כ יוכל לעשות בהיפוך השכל שזהו דרך האמונה בלבד וישראל מאמינים בני מאמינים<sup data-n=\"1506\">60</sup> אעפ\"כ ימצא בנ\"י גנב[ים] וע\"ע<sup data-n=\"1507\">61</sup> כו' כמארז\"ל גנבא אפום מחתרתא<sup data-n=\"1508\">62</sup> רחמנא קריא כו' והיינו כנודע שהאמונה היא למעלה מן השכל בבחי' מקיף והעלם שנק' בחי' עטרת<sup data-n=\"1509\">63</sup> כנודע. אבל כשיעמיק דעתו בזה וירגיש החיות השופע עליו ממקור החיים בבחי' הרגשה ממש כחיי נפשו שזהו בחי' גילוי אלקות ממש אזי תחלה יתמרמר לבבו מדוע הוא רחוק מאור פני מלך חיים<sup data-n=\"1510\">64</sup> וימר לבבו מאד מזה וישוב בתשובה [שלימה] אליו ית' שזהו מדת הגבורה הנמשך מן הדעת למרת לבבו מאד, וירגיז יצ\"ט על היצה\"ר כדרז\"ל לעולם",[["1495","49","<b>שדה. . חקל תפוחין קדישין</b>: ראה זהר ויחי רכד, ב."],["1496","50","<b>עשב. . ע\"ב ושי\"ן</b>: נסמן לקמן רפב, ד."],["1497","51","<b>ע\"ב. . החסד</b>: ראה גם לעיל פ' וארא פה, א ובהערה 816."],["1498","52","<b>מים שיורדים מגבוה לנמוך</b>: ראה תענית ז, א."],["1499","53","<b>אבות. . חג\"ת</b>: ראה גם לעיל סא, ד. וש\"נ."],["1500","54","<b>שהדעת. . המקיים של המדות</b>: ראה תניא פ\"ג."],["1501","55","<b>בדעתו</b>: אהו: בשכלו."],["1502","56","<b>שכולא קמי' כ\"ח</b>: נסמן לעיל רעז, ב."],["1503","57","<b>להמשיך</b>: אהו: להפך."],["1504","58","<b>כי הוא חייך</b>: נצבים ל, כ."],["1505","59","<b>לאהבה את ה'</b>: נצבים שם."],["1506","60","<b>מאמינים בני מאמינים</b>: ראה שבת צז, א. לעיל פ' בא קי, ד בהערה."],["1507","61","<b>וע\"ע</b>: ועוברי עבירה."],["1508","62","<b>גנבא אפום מחתרתא</b>: ראה ברכות סג, א ע\"פ גי' הע\"י. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' ט."],["1509","63","<b>שהאמונה. . עטרת</b>: ראה מאמרי אדה\"ז הקצרים ע' תסט. וש\"נ. שה\"א ו, א ובהערה 10."],["1510","64","<b>מאור פני מלך חיים</b>: ע\"פ משלי טז, טו."]]],[2300550240,"ירגיז אדם<sup data-n=\"1511\">65</sup> יצ\"ט על יצה\"ר כו' שענין הרוגז על יצה\"ר הוא כשמשיג בדעתו ומרגיש גדולת הבורא ית' וערך ביטול הנפעלי' קמי' עתה יהי' ברוגז גדול על יצה\"ר מדוע הסתיר ממנו והחשיך עליו האור אלקי כו' וכמ\"ש בלק\"א<sup data-n=\"1512\">66</sup> [ע\"ש], ואח\"כ יעורר ר\"ר על נפשו בהרגשתו בדעתו גודל עוצם ריחוקו מאור פני מלך ע\"כ תגדל הרחמנות עליו מאד, ואח\"כ יתעורר מזה באהבה אליו ית'. נמצא כל המדות אלו חג\"ת נסתעפים מבחי' דעת דוקא כנ\"ל שזולת הדעת והרגשה במקור החיים בבחי' הרגשה ממש לא יתמרמר לבבו על ההיפוך כלל ולא הי' ברוגז כלל על יצה\"ר כי אינו מכאיבו<sup data-n=\"1513\">67</sup> ומה עשה לו היצה\"ר, וגם לא הי' מעורר ר\"ר כלל על נפשו שאינו מרגיש הרחמנות כלל שלא יחסר לו מאומה אף שמשכיל בשכלו גדולת ה' ית' כנ\"ל. נמצא עיקר המהפך את המדות הוא הדעת דוקא שהוא פנימיות המדות הכולל ג' מדות אלו חג\"ת כנ\"ל. וז\"ש ונתתי עשב בשדך לבהמתך שמשה רועה ומשפיע בחי' דעת הכולל ג' קוין חג\"ת בבחי' שדה העליונה בשביל בהמתך המה זרע בהמה הנשמות דבי\"ע שינקו משם ויקבלו חיותם שיוכלו לברר ולהפוך המדות כנ\"ל שהכל נשפע מבחי' משה דעת עליון דאצי' כנ\"ל וד\"ל.\n[ח<sup data-n=\"1514\">68</sup> ] וז\"ש שש שנים יעבוד וגו' כמשנ\"ת בתו[רה] ע\"פ ואברהם זקן<sup data-n=\"1515\">69</sup> בא בימים באינון יומין כו' <span data-k=\"pg\">830</span> ּ הם הלבושים דתומ\"צ אך הם נתלבשו בענינים גשמיים לכך צריך לזכך את הלבושים דתומ\"צ ולכבס אותם במים עליונים כמ\"ש כעדר הרחלים<sup data-n=\"1516\">70</sup> שעלו מן הרחצה כו' רוחצות בחלב<sup data-n=\"1517\">71</sup> וגו' דהיינו בחי' ליבון הלכתא שמלבן את התומ\"צ בלובן העליון כו' וכ\"ז עושה מרע\"ה רע\"מ שרוחץ הרחלים במים עליונים וגם נותן מרעה טוב הוא עשב העליון כמ\"ש ונתתי עשב בשדך וגו'.\n<b>ביאור</b> הענין הוא, דהנה כתיב והיתה נפש אדוני<sup data-n=\"1518\">72</sup> צרורה בצרור החיים את ה' אלקיך כו' שכל ניצוץ אלק[ות מ]ישראל מוכרח להתעלות ולצרור בצרור החיים להשיג נועם ה' ית' בג\"ע ולהתענג על ה' ולהשיג זיו השכינה ב\"ה שהוא נועם ה' אשר הוא קדמון ונצחי אין לו תחלה ואין לו תכלה<sup data-n=\"1519\">73</sup> כו', שלא יוכל הנברא להסתכל ולהשיג נועם ה' ית' מרוב האור הנשפע מן הבורא ית' אשר אין ערוך ביניהם כלל, ע\"ז מוכרח הזיו להתלבש בלבוש וכלי שהלבוש מלביש את האור ומסתיר[ו] וע\"י אותו הלבוש יוכל להשיגו ולהתענג ממנו והיינו שהלבוש נעשה מבחי' תומ\"צ שקיים בעוה\"ז, שהתומ\"צ הם חכמתו ורצונו ית' שנמשכו מבחי' אחוריים של החכמה ורצה\"ע שהוא בחי' תחתונה של המאציל ב\"ה שירדו למטה בסתר המדרגות להתלבש בענינים גשמיים של עוה\"ז, ולזאת הם הלבושים המסתירים ומלבישים את זיו השכינה ב\"ה שיוכלו הנבראי' להשיגו דרך",[["1511","65","<b>לעולם ירגיז אדם</b>: ראה לעיל פ' בשלח רכו, ב. וש\"נ."],["1512","66","<b>בלק\"א</b>: פכ\"ט."],["1513","67","<b>מכאיבו</b>: אהו: מרגיש מכאובו."],["1514","68","<b>ח</b>: ב: לא נסמן. דו: פ\"ה(!)."],["1515","69","<b>ואברהם זקן</b>: נסמן לקמן רפה, ב."],["1516","70","<b>כעדר הרחלים</b>: שה\"ש ו, ו."],["1517","71","<b>רוחצות בחלב</b>: שם ה, יב."],["1518","72","<b>והיתה נפש אדוני</b>: ראה גם לקמן רפה, ב. וש\"נ."],["1519","73","<b>אין לו תחלה ואין לו תכלה</b>: ראה חובת הלבבות שער היחוד פ\"ה. המשך תרס\"ו ע' כ."]]],[2300550271,"הלבוש ההוא כו'. וכמו עד\"מ למטה באור הנר הגשמי המאיר מאד עד שלא יוכל העין להסתכל בעצם אור מחמת רוב הבהירות של המאור עצמו זולת ע\"י מסך מבדיל ומסתיר עצם המסך<sup data-n=\"1520\">74</sup> והאור מאיר דרך המסך אז יוכל העין לראות או כמו באור השמש כו', כך עד\"מ למעלה ממש שהנבראים אינם יכולים להשיג ולהסתכל בנועם ה' ית' הוא זיו השכינה ב\"ה בעצמו זולת ע\"י לבוש ומסך עב המלבישו ומסתירו והאור הזורח דרך המסך העב יכולים הם להסתכל בו ולהשיגו, והיינו בחי' הלבושים דתומ\"צ [ש]נעשים בחי' מסך עב לגבי זיו השכינה ב\"ה להסתירו ולהלבישו בהיות הם נמשכים מאחוריי' דחכ' ורצון של המאציל ית' מבחי' תחתונה שבו ונתלבשו למטה בענינים גשמיים, [ל]כך הם יכולים להלביש את זיו השכינה ולהסתירו כמסך המבדיל ומסתיר על אור הנר או השמש או כדומה עד שהאור השופע דרך המלבוש והמסך יכולים הנבראים להסתכל בו ולהשיגו ממש ליהנות ממנו בבחי' הנאה ממש וד\"ל. וזהו בחי' יומין שנק' לבושי' דתומ\"צ שעשה האדם בחיותו ע\"פ האדמה ע' שנה שלזאת ניתנה לו במדה ושיעור הימים שיחי' על פני האדמה ע' שנה או פ' שנה בשיעור זו שצריך לעשות לו לבושין לקבל העונג העליון בג\"ע כו' כידוע. ובהיות ידוע שהימים הוא בחי' זמן שנמשכו מבחי' שלמעלה מן הזמן [כו'] והיינו שהזיו העליון שלמעלה מהזמן א\"א להנבראים להשיגו זולת כאשר ירד למטה להתלבש בבחי' כלי ולבוש במקום וזמן ממש והם הם התומ\"צ שהם הל[בושים] והכלים של זיו העליון <span data-k=\"pg\">תטו</span> ּ שנתלבש בהם שהם נעשי' תחת הזמן במשך ימים ושנים ע\"ש כדומה כנ\"ל ולכך נק' תומ\"צ בחי' יומין שהן בחי' הלבושי' כנ\"ל שהכל א' שהזיו העליון מתלבש בכלי ולבוש בזמן ומקום וד\"ל (וכמ\"ש במ\"א ע\"ד [רז\"ל] עתיד הקב\"ה להנחיל לכל צדיק ש\"י עולמות<sup data-n=\"1521\">75</sup> דוקא ע\"ש ודוק היטב).\n[ט] <b>וז\"ש</b> שש שנים יעבוד וגו', פי' שמשרע\"ה בחי' הדעת עליון דאצי' משפיע מוח הדעת למטה לברר את המדות ולזכך בחי' התו\"מ שהם לבושים שעשה בעוה\"ז תחת הזמן והיינו כעדר הרחלים שעלו מן הרחצה שמשה הוא רע\"מ כרועה עדרו ירעה במרעה הטוב של עשב השדה וגם רוחץ עדרו במים כו', כך עד\"מ משה רע\"מ הנמשך ממים עליונים שבעה\"נ עליון הידוע שנמשך משמיטה ראשונה שנק' שמיטת החסד כמ\"ש בו כי מן המים משיתיהו וגו' הוא רוחץ עדרו במים עליונים לזכך את הלבושים דתו\"מ והוא בהשפעת[ו] אליהם בחי' מוח הדעת בזמן התפלה שאז הוא בחי' ההתגלות וההמשכה מוחין דגדלות לכנ\"י כו' שע\"י בחי' מוח הדעת יזככו את הלבושי' דתו\"מ ללבן ההלכות וע\"ז נאמר רוחצות בחלב וד\"ל. והנה תפלה היא מדרבנן<sup data-n=\"1522\">76</sup> ורמ\"ח מ\"ע הם מדאורייתא מפני",[["1520","74","<b>המסך</b>: אהו: המאור."],["1521","75","<b>עתיד. . ש\"י עולמות</b>: ראה עוקצי' בסופה. לקו\"ת בהעלותך לג, ד."],["1522","76","<b>תפלה היא מדרבנן</b>: ראה שו\"ע אדה\"ז הל' תפלה סק\"ו, ס\"ב. הנסמן לעיל פ' בא קכ, ג."]]],[2300550299,"שהעיקר המה המצות מעשיות שבקיומו המצות מעשיות עושה לעצמו לבושים לקבל הזיו השכינה ב\"ה כנ\"ל רק שהמצות נתלבשו בעניני' גשמיי' וצריך לזכך אותו שהזיכוך שלהם הוא ע\"י מוח הדעת המתגלה בזמן התפלה כנ\"ל וד\"ל.\n<b>והנה</b> נת' בתו' שע\"י ג\"פ קדוש שאו' המלאכים ממשיכים [אליהם] בחי' מוח הדעת ואין מקדשין אותו מלמעלה עד שיקדישו אותו מלמטה כו' וע\"ז נא' כולם כא' עונים כו' וכמ\"ש בזהר דכולהו מקדשין לי' כחדא<sup data-n=\"1523\">77</sup> לעילא ולתתא כו' שהמלאכים [דלעילא] מחכים וממתינים על ישראל שלמטה לאמר קדוש כאחד ביחד כו'. והענין הוא דהנה המלאכים שלמעלה [ש]במרכבה העליונה נק' ג\"כ בחי' בהמות<sup data-n=\"1524\">78</sup> לגבי בחי' עולם האצי' כמ\"ש פני ארי' אל הימין ופ\"ש מהשמאל<sup data-n=\"1525\">79</sup> כו', שאף שיש להם דעת גדול אעפ\"כ לגבי הדעת [עליון] דאצי' נמשל כבהמות נדמו<sup data-n=\"1526\">80</sup> כאלו אין להם דעת כלל, וע\"ז צריכים להמשיך אליהם הדעת [עליון] מאחר שהן נקראים בע\"ג ותכלית ונפרדים ממש אשר אין להם ערך ויחוס אל הבורא ית' כו'. ואף שנאמר בזהר בכמה דוכתי דבאתעדל\"ת אתעדל\"ע<sup data-n=\"1527\">81</sup> דרוח אייתי רוח<sup data-n=\"1528\">82</sup> ואמשיך רוח שלפ\"ע ההעלאת מ\"ן שהוא בחי' אתדל\"ת כך ערך אופן המשכת מ\"ד שהוא בחי' אתעדל\"ע ממש, אעפ\"כ אין המלאכים העליונים יכולים בעצמן להמשיך המ\"ד כו' בחי' ד\"ע הנ\"ל אליהם מפני שאין בהם הכח ביכולתם<sup data-n=\"1529\">83</sup> להתעורר בעצמן בהעלאת מ\"ן<sup data-n=\"1530\">84</sup> כמ\"ש בע\"ח שאף לצורך ההעלאת מ\"ן מוכרח לישפע מלמעלה לסייעה לעוררה בהעלאת מ\"ן כו', והיינו שנשפע מלמעלה מבחי' אתעדל\"ע שמתעורר מצד עצמו בלתי אתעדל\"ת כלל לעורר בהעלאת מ\"ן<sup data-n=\"1531\">85</sup> שיהי' בה הכח והיכולת להעלות מ\"ן ואח\"כ כשמעלה מ\"ן ממשכת מ\"ד כאופן המ\"ן כך הוא המשכת המ\"ד שהוא בחי' <span data-k=\"pg\">832</span> ּ אתעדל\"ע הנמשך ע\"י אתעדל\"ת כו'. וההפרש בין המ\"ד הנמשך ע\"י העלאת מ\"ן שלמטה ובין המ\"ד הנשפע מעצמ[ו] וממילא לעוררה בהעלאת מ\"ן כו', הוא שהמ\"ד הנמשך ע\"י העלאת מ\"ן הוא בדרך וסדר הדרגת השתלשלו' עו\"ע כו', והמ\"ד היורד בעצמו לעורר בהעלאת מ\"ן הוא נמשך מבחי' שלמעלה מהשתלשלות מבחי' העיגולים והמקיפי' שלמעלה דהיינו מבחי' ומדרגת משרע\"ה שנמשך מבחי' עבר הנהר העליון הידוע לעוררה בהעלאת מ\"ן כו'. והמשל לזה הוא כמו באדם שלמטה שמתעורר בתשובה פתאום יפלו לו הרהורי תשובה להתעורר על ריחוקו מאור פני מלך חיים כו' שזה לא באה מצד עבודתו שלמטה שהרי לא עשה עדיין כלום ומאין באה לו התעוררות בתשובה, והיינו בחי' אתעדל\"ע שלמעלה מהשתלשלו' שמשפיעים לו הרהורי תשובה לעורר[ו] בתשובה ואח\"כ כשישים אל לבו להתפלל ויתפלל",[["1523","77","<b>כולם כא'. . מקדשין לי' כחדא</b>: ברכת יוצר. ראה זהר ויחי רלא, א."],["1524","78","<b>המלאכים. . בהמות</b>: ראה גם לעיל פ' בשלח קסח, ג. וש\"נ."],["1525","79","<b>פני' ארי'. . מהשמאל</b>: יחזקאל א, י [ושם: ופני. בדילוג]."],["1526","80","<b>נמשל כבהמות נדמו</b>: תהלים מט, יג. כא."],["1527","81","<b>דבאתעדל\"ת אתעדל\"ע</b>: נסמן לעיל פ' יתרו רנט, ב."],["1528","82","<b>דרוח אייתי רוח</b>: נסמן לעיל בפ' יתרו רנא, א."],["1529","83","<b>ביכולתם</b>: אהו: ו[ה]יכולת."],["1530","84","<b>שאין בהם הכח. . בהעלאת מ\"ן</b>: ראה פע\"ח (שער הברכות) ש\"ב, פ\"א."],["1531","85","<b>אתעדל\"ע. . לעורר בהעלאת מ\"ן</b>: ראה סידור שער התפלה יט, ב."]]],[2300550325,"בכוונה בצעקת לבו אל ה' ית' דהיינו אתעדל\"ת ימשיך כיוצא בו [בחי'] אתעדל\"ע כו' (אבל טרם שנתעורר בתפלה בהעלאת מ\"ן שלא התפלל כלל ופתאום נפלו בלבו הרהורי תשובה זהו מבחי' המ\"ד היורד מעצמו מבחי' שלמעלה מהשתלשלו' לעוררו בתשובה כנ\"ל). ולזאת אין ביכולתם של המלאכים להתעורר בהעלאת מ\"ן מעצמם בלתי שיושפע אליהם מההשתלשלו' הנ\"ל מעבר הנהר עליון הנ\"ל לסייע אותם לעוררם בהעלאת מ\"ן, ולכן אין מקדשין אותו מלמעלה עד שמקדשי' אותו ישראל מלמטה בהיות ישראל עלו במחשבה<sup data-n=\"1532\">86</sup> קדומה ע\"ז ממשיכים משרשם בחי' מחשבה קדומה אל בחי' דבור העליון מקור המלאכים שלמעלה שנמשכו מדבר ה' ורוח פיו ית', ואז יוכלו המלאכים לומר שירה שכבר נשפע בהם בחי' הדעת ואח\"כ משפיעים המלאכים את הדעת למטה לישראל שלמטה שנתלבשו בגופים גשמי' דעשי', ולכך כולם מקדשין לעילא ותתא כולם כאחד<sup data-n=\"1533\">87</sup> כנ\"ל שכמו שבזמן השירה של המלאכים שאומרים קדוש קדוש קדוש כו' נשפע [בהם] בחי' הדעת עליון בחי' מוחין דגדלות [משא\"כ בכל היום כולו נשארים בבחי' מוחין דקטנות רק בזמן ההוא שאומרים שירה נשפע בהם בחי' ד\"ע בחי' מוחין דגדלות] כך בישראל בזמן התפלה בלבד נשפעים בהם בחי' הדעת שהוא בחי' מוחין דגדלות משא\"כ בכל היום כו' כנודע.\n<b>וז\"ש</b> משה משה לא פסיק טעמא בגווייהו<sup data-n=\"1534\">88</sup> כו' מפני שהכל נשפע מבחי' משה הן בחי' הדעת הנשפע להמלאכים ונשמות דבי\"ע שנק' זרע בהמה והן בחי' הדעת הנשפע לזרע אדם דאצי' המה הנשמות דאצי' כמו רשב\"י וחביריו, שגם המה מצטרכים להשפעת הדעת דמשה שנמשך מן המים עליונים שבעבר הנהר העליון שלפני האצי', שאף שהם זרע אדם העליון דאצי' וא\"צ לברר כו' כנ\"ל רק עבודתם להוסיף אורות באצי' כנ\"ל אעפ\"כ מצטרכי' להשפעת הדעת מבחי' משה שמן המים משיתיהו שלפני האצי' כנ\"ל. ולכך אמר משה משה לא פסיק טעמא פי' שמאחר שמשה משפיע בחי' פנימי' האור והחיות דהיינו בחי' דעת עליון שהוא פנימי' המדות לכך לא פסקא טעמא שאין שינוי בין האור והשפע הנשפע מבחי' משה ובחי' עולם האצי' אל בחי' זרע אדם עליון דאצי' ובין בחי' השפע היורד לבי\"ע לבחי' זרע בהמה מאחר שהוא השפעת החיות <span data-k=\"pg\">תטז</span> ּ והאור הפנימי לכך לא ישתנה כלל ושוה במהות[ו] בין באצי' בין בבי\"ע, דבשלמא בבחי' חיצוניות דהיינו בבחי' הכלים יש חילוק והפרש גדול בין הכלים דאצי' לכלים דבי\"ע ששונים זמ\"ז בהשתנות המהות ממש, משא\"כ בהאורות הפנימי' אין שינוי כלל כמ\"ש ואתה מחי' את כולם<sup data-n=\"1535\">89</sup> בשוה ממש כנ\"ל וזהו לא פסקא טעמא וד\"ל.",[["1532","86","<b>ישראל עלו במחשבה</b>: ראה ב\"ר פ\"א, ד. הנסמן לעיל פ' שמות לב, ב."],["1533","87","<b>כולם כאחד</b>: אהו: כחדא."],["1534","88","<b>משה משה. . בגווייהו</b>: נסמן לקמן רפג, ג."],["1535","89","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."]]],[2300550350,"[י] <b>ובשביעית</b> יצא לחפשי חנם, פי' חנם שעתה בכל משך הגלות שית אלפי שנין דהוה עלמא הוא זמן העבודה הוא הבירורים דעבד עברי בחי' משה שהוא ש[ם] מ\"ה המברר כמ\"ש שש שנים יעבוד<sup data-n=\"1536\">90</sup> שמזכך התומ\"צ ע\"י התפלה שהוא המשכת המוחין בחי' דעת עליון וכאשר מעלה מ\"ן ממשיך מ\"ד כיוצא בו [מ]למעלה שלפי ערך העלאת מ\"ן דתפלה כך ערך המשכת מ\"ד אליו ואז נשפע בו מ\"ד של מ\"ע<sup data-n=\"1537\">91</sup> לעוררו בהעלאת מ\"ן בעילוי יותר כו', וכמו\"כ מתעלה בעילוי אחר עילוי עד רום המעלות שכ\"ז נק' בחי' עליות העולמות, אבל לע\"ל באלף השביעי דוקא בגמר ותכלית כל הבירורים אז יהי' מנוחה לחיי העולמים שיגיע לבחי' עבה\"נ עצמו שלמעלה מבחי' העלאת מ\"ן דמעשה המצות וז\"ש ובשביעית יצא לחפשי חנם כדרז\"ל חנם בלא מצות כנ\"ל והיינו שהמצות הן בחי' לבושים והכלים והברכות דתפלה היא בחי' המשכת האורות מן הכלים כו', אבל לע\"ל יתאחדו האורות והכלים בתכלית היחוד ולזאת<sup data-n=\"1538\">92</sup> יצא לחפשי חנם כנ\"ל וד\"ל, משא\"כ בתחה\"מ וימוהמ\"ש יהי' עיקר העבודה כמ\"ש ביחזקאל שער הפונה קדים<sup data-n=\"1539\">93</sup> ביום השבת יפתח כו'<sup data-n=\"1540\">94</sup>, וזהו ובשביעית יצא לחפשי חנם וד\"ל.",[["1536","90","<b>שית אלפי שנין. . שש שנים יעבוד</b>: נסמן לעיל רעח, ד."],["1537","91","<b>של מ\"ע</b>: אהו: שלמעלה."],["1538","92","<b>ולזאת</b>: שם: ולזה א'."],["1539","93","<b>שער הפונה. . יפתח</b>: יחזקאל מו, א [ושם: בדילוג. וביום]."],["1540","94","<b>כו'</b>: אהו: ניתוסף: וביום החדש יפתח כו'."]]],[2300550049,"<b>בעז\"ה פ' משפטים</b>\n<span data-k=\"pg\">תה</span> ּ<b>ואלה</b> המשפטים<sup data-n=\"1541\">1</sup> אשר תשים לפניהם<sup data-n=\"1542\">2</sup> כו', כתי' וזרעתי את בנ\"י<sup data-n=\"1543\">3</sup> זרע אדם וזרע בהמה, פי' וזרעתי הוא אור זרוע לצדיק<sup data-n=\"1544\">4</sup> עליון שמשם מקור מחצב כל הנשמות כידוע, וכמ\"ש נשמה שנתת בי<sup data-n=\"1545\">5</sup> אתה בראת כו' ויש בזריעה זו ב' מדרגות א' זרע אדם והב' זרע בהמה. ויש להבין דהלא מקור הנשמות הוא מבחי' פני אדם שבמרכבה ושרש הראשון הוא בבחי' אדם שעל",[["1541","1","<b>ואלה המשפטים</b>: מאמר זה וכן המשכו מאמר ד\"ה כי תקנה עבד עברי הנדפס לאח\"ז שניהם מיוסדים על מאמר ד\"ה ואלה המשפטים שנאמר ע\"י כ\"ק אדה\"ז בשבת פ' משפטים תקס\"ה, אלא שמאמר דידן מיוסד על חלקו הראשון של דרוש הנ\"ל והמאמר שנדפס לאח\"ז ד\"ה כי תקנה מיוסד על חלקו השני. הדרוש דתקס\"ה הנה הנחת כ\"ק אדה\"א נדפסה במאמרי אדה\"ז תקס\"ה ח\"א ע' רמז (נוסחא שני'). והנחת הר\"מ בן כ\"ק אדה\"ז נדפסה ג\"כ שם. ונדפסה גם לעיל רעז, א. ובשינויים בתו\"א משפטים עד, ג. וראה בהנסמן במ\"מ לשם. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["1542","2","<b>ואלה המשפטים. . לפניהם</b>: משפטים כא, א."],["1543","3","<b>וזרעתי את בנ\"י</b>: ירמי' לא, כו [ושם: בית ישראל ואת בית יהודה — ראה הנסמן לעיל פ' שמות יד, א. במאמרים שבהערה 1 וכן אג: ב\"י]."],["1544","4","<b>אור זרוע לצדיק</b>: תהלים צז, יא. ראה גם לעיל פ' בשלח רמ, ג."],["1545","5","<b>נשמה שנתת בי</b>: ברכת אלקי נשמה (ברכות ס, ב) בדילוג."]]],[2300550081,"הכסא<sup data-n=\"1546\">6</sup> כו', ואיך א' וזרעתי זרע בהמה כו' איך יזרע [ה]אדם בהמה כו', אך הנה ידוע דאדם ובהמה הוא בחי' מ\"ה וב\"ן דאדם גימט' מ\"ה<sup data-n=\"1547\">7</sup> ובהמה גימט' ב\"ן<sup data-n=\"1548\">8</sup> וז\"ש אדם ובהמה תושיע ה'<sup data-n=\"1549\">9</sup>. והענין הוא שיש ב' מדרגות בנשמות א' מה שהנשמה האלקי' נק' ניצוץ כמו הניצוץ שנמשך אחר השלהבת מאליו, כך נר ה' נשמת אדם<sup data-n=\"1550\">10</sup> שמתפעל שכלו ומדותיו <span data-k=\"pg\">812</span> ּ באוי\"ר ממילא בהתפעלות אלקי' כמו משכני<sup data-n=\"1551\">11</sup> כו' וזהו בחי' נוק' בחי' מקבל שנמשך אחר המשפיע כמו אחרי ה' תלכו<sup data-n=\"1552\">12</sup>, ואעפ\"י שמתפעל ע\"י השגה דוקא אך זהו האות שאינה מרגשת כלל בחי' גילוי אור האלקי אשר בהשגתה רק מרגיש ההתפעלות לבדה והוא ההתלהבות לה' לבד, אבל בהארת אור האלקי שבהשגה זו שמחמתה נתפעל בלתי מורגש אצלה כלל בבחי' דעת והכרה. וכמו התפעלות המלאכים כשאומרים שירה אעפ\"י שמשיגים אלקות ומן ההשגה יבאו להתפעלות אוי\"ר מ\"מ לא בא האור האלקי בהשגתם בבחי' הרגשה והכרה בדעת רק מתפעלי' באוי\"ר לבד כפני ארי' ששואג<sup data-n=\"1553\">13</sup> כו' (וכמו שיש הרבה שמתפעלי' באהבה אלקי' מצד הטעם והדעת כי הוא חייך<sup data-n=\"1554\">14</sup> וכה\"ג מפני שמחיה את הכל כו', אבל אין מרגיש חיות התפעלות שלו רק באהבה לבד ולא מרגיש חיות בהשגתו כלל). וכמו הבהמה גשמי' [ש]מפני שאין בה בחי' הדעת דאדם אין בה בחי' [ה]הרגשה וההכרה לידע מחיי נפשה ולא [ת]רג[י]ש כלל מה ה[י]א אם חי או צומח וכה\"ג לא תרגיש בזה שתתפעל נפשה למאכל עשב מהו העשב ואיך שנתפעלה רק עצם ההתפעלות לבד וגם ההתפעלות לא תרגיש כו'. אבל האדם שהוא בר דעת והכרה ע\"כ יש בו בחי' ההרגשה בעצמו במה שמתפעל באיזה דבר מאכל בטעם טוב שבו כמו שיודע ומרגיש ומכיר היטב בחיי נפשו איך שהוא חי כו', ולא שזהו רק ידיעה בשכל לבד אלא הכח המרגיש ממש כמו שאנו רואים בצער כמו בהכאת מכה שהאדם מרגיש יותר מן הבהמה כמו יוסיף דעת יוסיף מכאוב<sup data-n=\"1555\">15</sup> כו' והבהמה לא תרגיש כ\"כ (וגם באדם עצמו בפנים ירגיש הכאב יותר מבאחוריו כו' וכמ\"ש במ\"א), וכן בהתפעלו' המדות ירגיש האדם בנפשו יותר וכ\"ש התפעלות השכל והרצון והתענוג מרגיש ביותר כו'. וזהו עיקר בחי' הדעת שאינו הידיעה בשכל לבד אלא בחי' ההרגשה<sup data-n=\"1556\">16</sup> וההכרה<sup data-n=\"1557\">17</sup> כמ\"ש במ\"א",[["1546","6","<b>מקור הנשמות. . אדם שעל הכסא</b>: ראה גם מאמרי אדה\"א בראשית ע' קנה. וש\"נ."],["1547","7","<b>דאדם גימט' מ\"ה</b>: ראה ע\"ח (שער התיקון) ש\"י, פ\"ג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. תו\"ח בראשית ט, א בהערה 14."],["1548","8","<b>ובהמה גימט' ב\"ן</b>: ראה תניא ספמ\"ו. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ."],["1549","9","<b>אדם ובהמה תושיע ה'</b>: תהלים לו, ז. ראה גם תו\"ח בראשית ט, סע\"א ובהערה 20."],["1550","10","<b>נר ה' נשמת אדם</b>: משלי כ, כז."],["1551","11","<b>משכני</b>: שה\"ש א, ד."],["1552","12","<b>אחרי ה' תלכו</b>: פ' ראה יג, ה [ושם: ה\"א]."],["1553","13","<b>כפני ארי' ששואג</b>: יחזקאל א, י. הושע יא, י. ראה גם מאמרי אדה\"א דברים ח\"א ס\"ע שא. וש\"נ."],["1554","14","<b>כי הוא חייך</b>: נצבים ל, כ."],["1555","15","<b>יוסיף דעת יוסיף מכאוב</b>: קהלת א, יח [ושם: ויוסיף — נסמן בסמוך]. ראה לעיל פ' בא קד, ב. וש\"נ."],["1556","16","<b>הדעת. . ההרגשה</b>: ראה תניא ספמ\"ו. לעיל פ' בא קד, ב. וש\"נ."],["1557","17","<b>הדעת. . וההכרה</b>: ראה לקו\"ת ואתחנן ד, א. שע\"ת פא, א ובהערה 19. לקמן פ' תצוה שעח, סע\"ב ואילך. ויקהל תלח, א."]]],[2300550113,"שאעפ\"י שאין האדם רואה בעין באיכות מהות רוחני' חיות נפשו<sup data-n=\"1558\">18</sup> כלל מ\"מ הרי יודע ומרגיש מציאות נפשו באמיתתה כמו שהיא ממש כאלו רואה בעין ממש דהיינו שנתאמת אצלו אמיתית מהותה כמו שהיא חיי גופו ובלעדה מיד ימות, וא\"כ ידיעה זו אע\"פ שאינה ע\"י ראיה בעין ממש זהו כראי' ממש מצד בחי' ההכרה ו[ה]הרגשה שמרגיש לחיות נפשו. משא\"כ הבהמה אעפ\"י שתחי' גם היא מחיי נפשה הבהמית כמו האדם שנק' חי גם הוא כבהמה אך אין בה בחי' ההרגשה וההכרה במציאות חיי נפשה מפני שאין בה בחי' הדעת כלל. וכמו\"כ בהרגשה דהתפעלו' המדות נבדל ערך אדם מן הבהמה שהאדם ירגיש ויודע במהות ההתפעלו' וכ\"ש בהתפעלו' שכלו ובמהות השגת שכלו יש בו הכרה והרגשה ממש והוא ע\"י כח הדעת וכ\"ש בעונג או צער או רצון ובחירה לבחור בטוב ולמאוס ברע הכל ע\"י הדעת שמרגיש ויודע יותר בטוב [ו]רע (הגם שהבהמה בורחת מדבר המזיק זהו בחי' טבעיות לבד), וראי' מן התינוק בטרם ידע לבחור בטוב ולמאוס ברע מפני חסרון דעתו כו'. וזהו הנק' בעל בחירה <span data-k=\"pg\">תו</span> ּ שאין זה רק באדם ולא בבהמה מצד בחי' הדעת ולא מצד השכל דגם שנתאמת הדבר אצלו עפ\"י השכל אין זה נק' דעת רק ידיעה בשכל לבד כמו שנתאמת הדבר שהאש שורף והמים מכבה האש שזהו נק' ידיעה בחוץ ממנו אבל בידיעה והכרה בין טו\"ר הוא בבחי' ידיעה והרגשה כמו שמרגיש א\"ע כנ\"ל וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן ג\"כ בנשמות שנק' זרע אדם וזרע בהמה דנשמות שהתפעלותן באלקות באוי\"ר טבעיות בלתי טעם ודעת היינו שבלתי מרגיש[י'] כלל בגילוי אור האלקי שמחיה נפשם ואינם יודעים ומרגישים בחיי אלקי' כלל כמו [ש]הבהמה לא תרגיש בחיי נפשה וא\"י<sup data-n=\"1559\">19</sup> מעצמותה כלל, והגם שמתפעלים מצד ההשגה אלקי' אבל בלתי מרגישים ויודעי' מזה כלל ועכ\"ז נק' התפעלות אלקות ממש והן חיים מחיות האור אלקי ממש רק שהן אינן יודעי' ומרגישי' בזה כו', וע\"כ זהו נק' למטה מן הדעת כבהמה וכמו הניצוץ הנמשך למקורו שאין בזה בחירה כלל וכמו התפעלו' המלאכים כנ\"ל. אבל נשמות שנק' זרע אדם הוא אשר יש בהם כח הדעת לידע ולהרגיש באור האלקי שבנפשם כמו שאדם שיודע ומרגיש בחיי נפשו אעפ\"י שאינו רואה בעין ממש כך הוא בבחי' הכרה והרגשה דנשמות שנק' זרע אדם כמו שהוא בעצם אור האלקי ממש, וע\"כ בנקל מאד לנשמות הללו להתפעל בהשגת אלקות בלי יגיעה כלל מפני שבא להם ההשגה האלקי' בבחי' הרגשה והכרה (בל\"א ער דער הערט דאס תיכף באיי זיך כו') וד\"ל.",[["1558","18","<b>שאין האדם רואה. . נפשו</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשכט."],["1559","19","<b>וא\"י</b>: א: ואינה יודעת."]]],[2300550145,"<b>וזהו</b> וזרעתי את בנ\"י כו' שהוא בחי' ב' מדרגות דנשמות הנ\"ל שאע\"פ שמקור הנשמות הוא מבחי' פני אדם כו', אבל ידוע דאדם כלול מדכר ונוק'<sup data-n=\"1560\">20</sup> ובחי' ב\"ן שבמ\"ה נק' בהמה שבאדם והוא בחי' זרע בהמה הזרוע מאור ומקור כל הנשמות וכמ\"ש דוד<sup data-n=\"1561\">21</sup> ואני בהמו\"ת הייתי עמך<sup data-n=\"1562\">22</sup> בחי' בהמה שלמטה מן הדעת ששרשו למעלה מן הדעת דאדם (והוא בחי' בהמה רבה שלפני האצי' דאדם כו'), וכמו שמבואר למעלה דנשמות שהתפעלותם באלקות טבעי' ועצמי' ממילא כניצוץ הנמשך שאין בזה בחירה ה\"ז למעלה מבחי' הבחירה דאדם ובזה יתרון מעלה לזרע בהמה על זרע אדם, אבל מה שבאדם יש בו בחי' הדע\"ת וההכר\"ה וההרגש\"ה כנ\"ל הרי בזה נבדל ערך זרע אדם על זרע בהמה (וגם בזה יש יתרון מעלה לבהמה במה שביטול שלה לאין האלקי בלתי הרגשה בעצמה כלל שזהו למעלה מביטול המורגש<sup data-n=\"1563\">23</sup> כמ\"ש במ\"א, אך עיקר אד\"ם הוא אדמ\"ה לעליו\"ן<sup data-n=\"1564\">24</sup> והוא במה שכולל הכל כו', וזהו מה שהוא בעל בחירה ברצון ושכל ומדות בזה נק' אד\"ם למשול על הכל כו', ולזאת מה שיש בדעת זה המרגיש בחי' יש נפרד זהו מפני שדומה לאד\"ם העליון וע\"כ טבעו להתנשאו' על הכל וכמ\"ש וירדו בדגת הים<sup data-n=\"1565\">25</sup> כו' וכך הן אותן נשמות שנק' זר\"ע אדם שהן בצל\"ם אד\"ם העליון ממש וד\"ל).\n[ב] <b>והנה</b> ידוע בענין ז' רועים<sup data-n=\"1566\">26</sup> דמשה נק' רעיא מהימנא<sup data-n=\"1567\">27</sup> ביתרון מעלה על שאר הרועי' והוא במה שמשפיע וממשיך בחי' כח הדעת הנ\"ל בנש\"י <span data-k=\"pg\">814</span> ּ בכל דו\"ד<sup data-n=\"1568\">28</sup> שהוא נשמות שנק' זרע אד\"ם בצלם אד\"ם העליון שיהי' כאו\"א מישראל מרגיש ומכיר את בוראו בבחי' הדעת כאלו הוא חייו ממש כמ\"ש לאהבה את ה'<sup data-n=\"1569\">29</sup> [כו'] כי הוא חייך ממש וכמו ש[ה]אדם מרגיש חיי נפשו (ולא כאותן שמדמין בנפשם שמרגישין כח וחיות אלקות בלבם ובנפשם ומטעי' א\"ע בזה ביותר, כי הרגשה זו רק בהתפעלות שלו שמרגיש א\"ע שהוא נתפעל בהתלהבות אבל הוא דמיון שוא כי עיקר מעלת ההרגשה הוא ההכרה בטוב בבחי' ההשגה האלקי' שבמוחו כשנתפעל בה עצמה בהרגשה (שנק' דער הערט טיף כו'). והנה האבות נק' רועים<sup data-n=\"1570\">30</sup> כידוע דאברהם ממשיך ומשפיע בכל ניצוץ קטן אור אהבה אלקי' והוא מה שכאו\"א יוכל להתפעל באהבה בלבו בכל יום בעת הכושר כמו בק\"ש מפני שמאיר על נפשו משרשו הראשון שהוא אהבה דאברהם, וכן נמשך ונשפע בכל יום בכל נשמה פחד אלקי' להיות סור מרע מבחי' פחד יצחק וכן יעקב ממשיך רחמים שיוכל כל ניצוץ אלקי' לעורר עליו ר\"ר העליוני' לשוב לה' כו', וכל זה למטה מבחי' אד\"ם שהוא בחי' הדעת שנמשך ע\"י משה",[["1560","20","<b>דאדם כלול מדכר ונוק'</b>: ראה זהר בהקדמה יג, ב. ראה הנסמן לעיל פ' בשלח ריט, ד."],["1561","21","<b>וכמ\"ש דוד</b>: בתניא פמ\"ו (סו, סע\"א) אסף. ראה מאמרי אדה\"א ויקרא ח\"א ע' י. וש\"נ. ש\"א ט, ב. שה\"א קו, א ובהערה 7."],["1562","22","<b>ואני בהמו\"ת הייתי עמך</b>: תהלים עג, כב [בדילוג]. ראה תניא פמ\"ו. מאמרי אדה\"א קונטרסים ע' תיג. וש\"נ."],["1563","23","<b>שביטול. . בלתי הרגשה. . למעלה מביטול המורגש</b>: ראה גם מאמרי אדה\"ז אתהלך לאזניא ס\"ע ח ואילך."],["1564","24","<b>אד\"ם הוא אדמ\"ה לעליו\"ן</b>: נסמן לעיל פ' יתרו רסב, א."],["1565","25","<b>וירדו בדגת היום</b>: בראשית א, כו. א: ורדו — שם, א, כח. ראה גם מאמרי אדה\"א קונטרסים ע' שיד. וש\"נ. שעה\"י קמב, ב ובהערה 41."],["1566","26","<b>ז' רועים</b>: ראה מיכה ה, ד. סוכה נב, ב. תו\"ח מקץ ריז, ב ובהנסמן במ\"מ לשם."],["1567","27","<b>דמשה נק' רעיא מהימנא</b>: ראה זהר וירא קו, א. לעיל פ' וארא עז, ב. וש\"נ."],["1568","28","<b>דו\"ד</b>: ג: דור ודור."],["1569","29","<b>לאהבה את ה'</b>: נצבים ל, כ."],["1570","30","<b>האבות נק' רועים</b>: ראה סוכה נב, ב. לעיל פ' בשלח קנה, ד. וש\"נ."]]],[2300550177,"שנק' רעיא מהימנא שלמעלה מן האבות כמ\"ש וארא אל אברהם כו' ושמי הוי' לא נודעתי<sup data-n=\"1571\">31</sup> כו' שהוא בחי' פנימי' המדות ומקורן ונק' דעת המתפשט במדות להחיותן<sup data-n=\"1572\">32</sup> כידוע, ובלעדי הדעת אין למדות אהוי\"ר קיום וחיות כלל לפי שהדעת הוא המעמיד ומקיים את המדות שבלב, והיינו מטעם הנ\"ל שהדעת הוא בחי' ההרגשה במוח בהשגה [ה]אלק[י]' עד שנכנסת בקרב ולב עמוק ששם משכן המדות אהוי\"ר ע\"כ הרגשה זו שבלב נק' דעת המתפשט במדות שבלב להיות להם קיום וחיות חזק וכמו לאהבה כי הוא חייך הרי כאשר ירגיש בטוב טעם זה כי הוא חייך ממש גם בלבו אז ממילא יתקיים אור התפעלו' האהבה שבלבו כו', ואם אין כח הרגשה זו מתפשט במוח ולב ונמצא הגם שמתפעל באהבה ע\"י ההתבוננו' יפול במעט רגע וצריך לחזור ולהתייגע בהתבוננו' כו' וד\"ל.\n<b>ונמצא</b> ששפע אור וכח הדעת שבמשה<sup data-n=\"1573\">33</sup> הוא בחי' פנימי' ומקור לחיות התפעלו' המדות אהוי\"ר שע\"י האבות וזאת היא עבודת משה שנק' רעיא מהימנא ביותר מן האבות, כי גם המדות אוי\"ר שנמשך לכ\"א ע\"י האבות הוא רק בבחי' אמונה שלמטה מן הדעת שכבר<sup data-n=\"1574\">34</sup> ירושה היא מאבותינו נטוע בכל אחד מישראל מתולדתו מרגיש<sup data-n=\"1575\">35</sup> חיי נפשו מאלקי' חיים אבל<sup data-n=\"1576\">36</sup> בחי' הדעת הנ\"ל הוא למעלה מן האמונה (ומבואר במ\"א (בס' שער האמונה<sup data-n=\"1577\">37</sup> ) שיש לאמונה שרש גבוה שהוא למעלה מן הדעת וכמ\"ש<sup data-n=\"1578\">38</sup> כולם ידעו אותי<sup data-n=\"1579\">39</sup> זהו גילוי כח האמונה לבד). וזהו שלמד משה לבנ\"י במצרים שיהיו מכירים ויודעים את בוראם וגם באותות ומופתים שעשה א' וידעתם כי אני הוי'<sup data-n=\"1580\">40</sup> כו' דהיינו שיהי' להם בחי' הדעת בשם הוי' (וכמ\"ש ויאמינו בהוי'<sup data-n=\"1581\">41</sup> כו' וכן א' ויאמן העם<sup data-n=\"1582\">42</sup> זה הי' בתחלת יציאתם ממצרים יצאו בכח האמונה לבד וכמ\"ש וארשתיך לי באמונה<sup data-n=\"1583\">43</sup> <span data-k=\"pg\">תז</span> ּ כו'<sup data-n=\"1584\">44</sup> ואח\"כ וידעת את הוי'<sup data-n=\"1585\">45</sup> כו' ע\"י משה שהמשיך בהם בחי' הדעת להיות נק' זרע אדם כדי שיוכלו לקבל את התורה פב\"פ שהוא בבחי' אדם דוקא וד\"ל). והנה ידוע דמשה נק' גואל ראשון וגואל אחרון<sup data-n=\"1586\">46</sup> וכמ\"ש שלח נא ביד תשלח<sup data-n=\"1587\">47</sup> דוקא<sup data-n=\"1588\">48</sup> דקאי במשיח שהוא משה כו' וכמארז\"ל יבא טוב<sup data-n=\"1589\">49</sup> זה משה ויקבל טוב כו' והיינו לע\"ל שנאמר ומלאה הארץ דיעה את ה'<sup data-n=\"1590\">50</sup> ממש, ודיעה זו היא בבחי' ראיה ממש וכמ\"ש ולא",[["1571","31","<b>וארא. . לא נודעתי</b>: וארא ו, ג."],["1572","32","<b>דעת. . במדות להחיותן</b>: ראה תניא פ\"ג. וראה גם לקמן פ' ויקהל תלח, ב."],["1573","33","<b>שבמשה</b>: אב: (ש)ע\"י משה."],["1574","34","<b>שכבר</b>: אבג: (ש)כמו."],["1575","35","<b>מרגיש</b>: אב: כו', אבל שיכיר וירגיש. ג: כו'. (והניח מקום פנוי) מרגיש."],["1576","36","<b>אבל</b>: שם: ע\"י."],["1577","37","<b>בס' שער האמונה</b>: ראה שם ח, ב ואילך."],["1578","38","<b>וכמ\"ש</b>: אבג: ומ\"ש."],["1579","39","<b>כולם ידעו אותי</b>: ירמי' לא, לג."],["1580","40","<b>וידעתם כי אני הוי'</b>: וארא ו, ז."],["1581","41","<b>ויאמינו בהוי'</b>: בשלח יד, לא."],["1582","42","<b>ויאמן העם</b>: שמות ד, לא."],["1583","43","<b>וארשתיך לי באמונה</b>: הושע ב, כב."],["1584","44","<b>כו'</b>: אבג: ליתא."],["1585","45","<b>את הוי'</b>: שם ליתא."],["1586","46","<b>דמשה נק' גואל ראשון וגואל אחרון</b>: ראה שמו\"ר פ\"ב, ד. הנסמן לעיל פ' בא קיח, ג."],["1587","47","<b>שלח נא ביד תשלח</b>: שמות ד, יג. ראה גם לעיל פ' שמות מד, ב. וש\"נ."],["1588","48","<b>דוקא</b>: אג: ליתא."],["1589","49","<b>יבא טוב</b>: מנחות נג, ב. ראה גם לעיל פ' שמות מג, ד. וש\"נ"],["1590","50","<b>ומלאה הארץ דיעה את ה'</b>: ישעי' יא, ט [ושם: כי מלאה — נסמן לעיל פ' בשלח קס, ד]."]]],[2300550209,"ילמדו עוד<sup data-n=\"1591\">51</sup> כו' כי כולם ידעו אותי פי' ידעו ויכירו אותי כמו שאדם מכיר לרעהו כו' וכמ\"ש וא' ביום ההוא<sup data-n=\"1592\">52</sup> הנה אלקינו זה לנוכח כו', ועכשיו הדעת הוא רק בהרגשה והכרה שמרגיש לאור האלקי כמו שמרגיש חיי נפשו כנ\"ל ולע\"ל יהי' הדעת זה עצמו בבחי' ראיה ממש ולכך משה דוקא יהי' גואל אחרון בהמשכת הדעת שבבחי' ראי' ממש מפני שהי' גואל ראשון בהמשכת הדעת להרגיש ולהכיר את בוראו משום דהא בהא תליא וד\"ל.\n[ג] <b>ובכ\"ז</b> יובן מ\"ש ונתתי עשב בשדך לבהמתך<sup data-n=\"1593\">53</sup>, דהנה ארז\"ל אסור לאדם לאכול עד שיתן מאכל לבהמתו<sup data-n=\"1594\">54</sup> שנא' ונתתי עשב בשדך כו' והדר ואכלת ושבעת. והענין הוא כנ\"ל בב' מיני נשמות דזרע אדם וזרע בהמה דנק' בהמה שבאדם בהתפעלות אלקי' בטבעי[ו]', וזהו שיתן מאכל לבהמתו תחלה כו' דהיינו שימשיך בחי' הדעת אלק[י]' בהרגשה והכרה באלקות גם בנפשו הטבעי' שתכיר ותרגיש גם היא בחי'<sup data-n=\"1595\">55</sup> אלקות בבחי' השגה אלקי' שנק' מוח הדעת. וכמו שאנו רואים בחוש שיוכל אדם להתפעל בהשגה אלקי' בכלי מוחו ולבו הגשמי' כמו שנתפעל בגופני' וכמו שא' לבי ובשרי ירננו<sup data-n=\"1596\">56</sup> כו' לבי ובשרי ממש וכן כלה שארי<sup data-n=\"1597\">57</sup> כו', וראי' לזה ממה שמצינו במלאכים שנק' בהמות וחיות<sup data-n=\"1598\">58</sup> כפני ארי' ופני שור<sup data-n=\"1599\">59</sup> כו' שאו' שירה מצד בחי' הדעת דוקא וכמ\"ש ולילה ללילה יחוה דעת<sup data-n=\"1600\">60</sup> וא' בזהר דאינון דרגין תתאין דמדת לילה שהן המלאכים שאו' שירה בלילה<sup data-n=\"1601\">61</sup>, ושיר שלהם הוא בבחי' התכללו' וביטול באימה ויראה לגבי בחי' מל' דמל[כותך] מל[כו'] כ\"ע<sup data-n=\"1602\">62</sup> כמשל אימת מלך שמתפשט על אנשיו וכמ\"ש ואימתך עליהם<sup data-n=\"1603\">63</sup>, והוא גילוי הארה בעלמא עליהם משם כבוד מלכותו ית' שמתפשט עליהם בבחי' שם בלבד רק מה ששמו נק' וכמ\"ש וכולם משבחים ומפארים את שם המלך<sup data-n=\"1604\">64</sup> כו', ובשיר זה שהוא בחי' העלא' ע\"י השגה אלקי' שלהם במקור חוצבם שהוא שם אד' כמ\"ש אדנ\"י בם<sup data-n=\"1605\">65</sup> כו' הן ממשיכים עליהם מבחי' הדעת האלקי שיכירו וירגישו יותר בחיות אלקות ששופע בהם וזהו ולילה ללילה יחוה דע\"ת כו' וד\"ל.\n<b>וזהו</b> ונתתי עשב בשדך<sup data-n=\"1606\">66</sup> עש\"ב שי\"ן באמצע השם דע\"ב<sup data-n=\"1607\">67</sup> דחכמה<sup data-n=\"1608\">68</sup> והיינו ענין ירידת אור [ה]שפע וה[ה]משכה",[["1591","51","<b>ולא ילמדו עוד</b>: ירמי' לא, לג."],["1592","52","<b>וא' ביום ההוא</b>: ישעי' כה, ט."],["1593","53","<b>ונתתי עשב בשדך לבהמתך</b>: עקב יא, טו."],["1594","54","<b>אסור לאדם. . מאכל לבהמתו</b>: ראה ברכות מ, א. וראה גם לקו\"ת בחוקותי מט, ב. מאמרי אדה\"א ויקרא ח\"א ע' יב. הנחות תקע\"ז ע' רלד, ובהנסמן בהנ\"ל."],["1595","55","<b>בחי'</b>: אג: בחיות."],["1596","56","<b>לבי ובשרי ירננו</b>: תהלים פד, ג."],["1597","57","<b>כלה שארי</b>: תהלים עג, כו."],["1598","58","<b>במלאכים שנק' בהמות וחיות</b>: ראה גם לעיל פ' בשלח קסח, ג. וש\"נ."],["1599","59","<b>כפני ארי' ופני שור</b>: יחזקאל א, י."],["1600","60","<b>ולילה ללילה יחוה דעת</b>: תהלים יט, ג. ראה זהר תרומה קלז, א."],["1601","61","<b>המלאכים שאו' שירה בלילה</b>: ראה חגיגה יב, ב. זהר וישב קפח, סע\"ב ואילך. לקוטי הש\"ס להאריז\"ל ברכות ג, א (ד\"ה תניא ר\"א). ביאוה\"ז פינחס קיא, ד. מאמרי אדה\"ז על מארז\"ל ר\"ע קלב. תקס\"ז ע' שמח. ש\"א כט, א ובהנסמן במ\"מ לשם. סה\"מ תרס\"ד ע' שנז."],["1602","62","<b>דמל[כותך] מל[כו'] כ\"ע</b>: תהלים קמה, יג."],["1603","63","<b>ואימתך עליהם</b>: ראה גם לעיל פ' וארא עה, ב. וש\"נ."],["1604","64","<b>וכולם משבחים ומפארים את שם המלך</b>: ראה ברכת יוצר."],["1605","65","<b>אדנ\"י בם</b>: תהלים סח, יח."],["1606","66","<b>בשדך</b>: אג: ליתא."],["1607","67","<b>עש\"ב שי\"ן. . דע\"ב</b>: באוה\"ת משפטים כאן (ע' א'קיד) מציין: בת\"ז תיקון נא דפ\"ט ע\"ב [ובדפו\"א פו, ב]. ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתקיד. וש\"נ."],["1608","68","<b>השם דע\"ב דחכמה</b>: ראה לעיל פ' וארא פד, ד."]]],[2300550241,"דדעת<sup data-n=\"1609\">69</sup> לג' קוין דשי\"ן שהן ג' חללי גלגלתא<sup data-n=\"1610\">70</sup> [דנוק'] שנק' שד\"ך<sup data-n=\"1611\">71</sup> והוא שדה חקל תפוחין<sup data-n=\"1612\">72</sup> כו', וכמ\"ש מצמיח חציר<sup data-n=\"1613\">73</sup> לבהמה ועשב לעבודת האדם שזהו בחי' המשכת הדעת מאד\"ם שהוא משה רעיא מהימנא לבחי' המל' תחלה שזה נק' עשב שי\"ן דע\"ב שנמשך למל' שנק' עבודת האדם העליון, וז\"ש ונתתי עש\"ב בשד\"ך אבל עשב זה בשד\"ך הוא בשביל המשכת מוחין ודעת למלאכים כו' שבמרכבה דפני שור. וכמו\"כ תחלה נמשך הדעת לכנ\"י שהוא מזון ועש\"ב<sup data-n=\"1614\">74</sup> העליון ואח\"כ <span data-k=\"pg\">816</span> ּ לנשמות שנק' זרע בהמה להיות גם הם בבחי' זר\"ע אד\"ם כנ\"ל שהוא מה שגם נה\"ט יש בה בחי' הדעת וההרגשה להכיר בוראו, וזהו שא' בשדך תחלה ואח\"כ לבהמתך משום דהשפעת מוחין דדעת הבאה מלמעלה ראשית הגילוי הוא בשדך שהוא המל' ומשם נמשך לבהמתך כו' וד\"ל. ולא עוד אלא שאסור לאדם לאכול דמאכל אדם הוא הדגן ולחם דחכמה ממש עד שיתן מאכל לבהמתו שהוא בחי' העש\"ב הנ\"ל וז\"ש והדר ואכלת ושבעת אכילת אדם בלחמה של תורה, ולכך התפלה קדמה לתורה<sup data-n=\"1615\">75</sup> כידוע שהתפלה במקום קרבן<sup data-n=\"1616\">76</sup> דבהמה כו', ובק\"ש נמשך בחי' עשב לבהמתך ואח\"כ ישבע לחם בתורה כו' וד\"ל.\n<b>והנה</b> לפי המבואר למעלה בשרש ענין הדעת שהוא בחי' ההרגשה וההכרה בטוב באור האלקי א\"כ ודאי ה\"ז בא בגילוי אור האלקי מקרוב דוקא וכנ\"ל בבחי' הדעת שדומה לבחי' ראיה בעין אע\"פ שאינה בבחי' ראי' ממש, אבל עכ\"ז בבחי' ראיה במקצת ובדומה לה יש בכח הדעת המרגיש כנ\"ל מאחר שע\"י בחי' ההרגשה הרי הוא עומד מקרוב מאד כמו ע\"י ראיי' מאחר שהדבר מורגש אצלו ממש, וכנ\"ל בענין לאהבה את ה' כי הוא חייך ממש כמו שיודע ומרגיש חיי נפשו כמו\"כ יודע ומרגיש בחיי אלקו' שבנפשו האלקי' איך שהוא חייו ממש כנ\"ל. ומובן מזה [דבחי' דעת כזה שבא ונמשך גילוי אור מקרוב ביותר אז ודאי גם התפעלות האוי\"ר שנולדים מזה הוא] בבחי' הפנימית מקרב ולב עמוק ביותר משום דזהו הכלל בכל מקום דאין האהבה באה רק מקרוב<sup data-n=\"1617\">77</sup> דוקא דהיינו כשרואה את דבר האהוב מקרוב, משא\"כ כשהדבר מרחוק תפול האהבה לגמרי כי מצד הראי' וההתקרבות באה המשכת התפעלות האהבה (וראי' ממה שא[מרו] כשלא דיבר עם חבירו<sup data-n=\"1618\">78</sup> ג' ימים נק' שונא) כי ראי' מקרוב מוליד אהבה וכמו במ\"ת שדיבר עמהם פב\"פ<sup data-n=\"1619\">79</sup> על כל דבור<sup data-n=\"1620\">80</sup> כו' מרוב אהבה בתענוגי' כו'. וכן מדת הפחד אינו אלא",[["1609","69","<b>דע\"ב דחכמה. . דדעת</b>: ראה תו\"א כאן עה, ב."],["1610","70","<b>ג' חללי גלגלתא</b>: ראה זהר ואתחנן רסב, א. (אד\"ר) נשא קמ, א."],["1611","71","<b>[דנוק'] שנק' שד\"ך</b>: ראה זהר בראשית לו, ב. ת\"ז תס\"ט (קיג, א)."],["1612","72","<b>[דנוק']. . שדה חקל תפוחין</b>: ראה זהר ויחי רכד, ב."],["1613","73","<b>מצמיח חציר לבהמה</b>: תהלים קד, יד."],["1614","74","<b>ועש\"ב</b>: אג: עש\"ב."],["1615","75","<b>התפלה קדמה לתורה</b>: ראה ברכות ה, ב. מאמרי אדה\"א שמות ח\"א ע' קפד. וש\"נ. ח\"ב ע' תקעא ואילך. תו\"ח נח נד, ב."],["1616","76","<b>שהתפלה במקום קרבן</b>: נסמן לעיל פ' יתרו רסח, ב."],["1617","77","<b>דאין האהבה באה רק מקרוב</b>: ראה גם לעיל פ' בשלח רכד, ד. וש\"נ."],["1618","78","<b>כשלא דיבר עם חבירו </b>[אג: רעהו]: ראה סנהדרין כז, ב (במשנה)."],["1619","79","<b>במ\"ת. . פב\"פ</b>: ואתחנן ה, ד."],["1620","80","<b>על כל דבור</b>: שבת פח, ב."]]],[2300550272,"מקרוב<sup data-n=\"1621\">81</sup> דוקא שכאשר המלך סגור בהיכלו לא יפול פחדו כלל, אבל כשבא בהתגלות מקרוב תפול אימתו ופחדו כו'. וכך יובן כאן דע\"י בחי' הדעת אלקי הנ\"ל שבא בבחי' קירוב לאלקות כ\"כ עד שנרגש אצלו כמו חיי נפשו ממש כנ\"ל וה\"ז כמו בחי' ראי' קצת שהוא מקרוב שאז ודאי האוי\"ר שנולדו מזה הן ג\"כ בבחי' הפנימי' בעומק הלב יותר כטבע האוי\"ר שמתפעלות מקירוב ביותר כנ\"ל וד\"ל, משא\"כ בלא בחי' דעת והרגשה רק מרחוק ה' נראה לו<sup data-n=\"1622\">82</sup> אין התפעלות אוי\"ר שנולדי'<sup data-n=\"1623\">83</sup> רק בבחי' החיצוני' בלבד ותומ\"י יפול מעבודתו כידוע ליודעי' טעמי'<sup data-n=\"1624\">84</sup> בטוב טעם ודעת האלקי הנ\"ל וד\"ל (ומבואר למעלה בענין הטעם דכי הוא חייך שאהבה דמס\"נ גדולה מזו והוא מ\"ש ואהבת בכל נפשך אפי' נוטל<sup data-n=\"1625\">85</sup> כו', ואמנם גם בהרגשת חיות אלק[י'] דדעת הנ\"ל יש ג\"כ כלות הנפש ממש כמ\"ש כלה שארי ולבבי כו' כי כל אשר לאיש יתן בעד חיי נפשו<sup data-n=\"1626\">86</sup> מאחר דהוא חייך ממש וכל חפצ[י]ו לא ישוו בה כלל וע\"כ א[מר] מי לי בשמים<sup data-n=\"1627\">87</sup> כו' וכן צמאה לך נפשי<sup data-n=\"1628\">88</sup> כמה לך כו' וד\"ל). וזהו ג\"כ ענין שיר שהמלאכים אומרים בכל יום שהוא להמשיך בהם בחי' הדעת כנ\"ל בענין ולילה ללילה יחוה דעת כנ\"ל היינו שיומשך עליהם בחי' גילוי אור האלקי מקרוב יותר ע\"י בחי' הרגשה <span data-k=\"pg\">תח</span> ּ והדעת<sup data-n=\"1629\">89</sup> מטעם הנ\"ל וממילא גם בחי' אוי\"ר שלהם בא בבחי' הפנימי' ביותר עד שנתבטלי' ממש וכמו והאופנים וחיות הקדש<sup data-n=\"1630\">90</sup> ברעש גדול כו' וזהו [מ]טעם הנ\"ל וד\"ל. וזהו כל עיקר הקדושה שהמלאכי' או[מרים] והוא ג\"פ קדו\"ש שהשרפי' או[מרים]<sup data-n=\"1631\">91</sup> לפי שקדש הוא מובדל ומרומם ומאיר רק בבחי' מקיף וסובב עליהם בלבד אבל אות הוי\"ו דקדו\"ש המורה בחי' ההמשכה והירידה<sup data-n=\"1632\">92</sup> מלמעלה למטה כידוע דכל וי\"ו הוא ציור המשכה<sup data-n=\"1633\">93</sup> קצרה מגבוה לנמוך והוא בחי' ההמשכה של בחי' הדעת והרגשה שבא מקרוב בגילוי אור מקדש העליון שזהו גילוי אור דסובב כו', וזהו יחוה דעת בוי\"ו וכמ\"ש בזהר יחוה יחי' מיבעי' לי'<sup data-n=\"1634\">94</sup> אלא הוי\"ו הוא המשכת הדעת להיות האור דסובב בא בבחי' גילוי אור ממש וד\"ל.\n[ד] <b>והנה</b> ידוע דמה שהמלאכים או' ג\"פ קדוש הוא לנגד ג' מדרגות דמחשבה דו\"מ והן ג' עולמות דבי\"ע<sup data-n=\"1635\">95</sup>, וידוע בהפרש שבין נשמות למלאכי'<sup data-n=\"1636\">96</sup> דשורש הנשמות נמשך מן המחשבה שבמוח וכמא' ישראל עלה במח'<sup data-n=\"1637\">97</sup> (וכמ\"ש אחור וקדם צרתני<sup data-n=\"1638\">98</sup> קדם למע\"ב שנאמרו בדיבור והוא במחשבה הפנימי' שלמעלה ממח' שבדיבור כמ\"ש במ\"א), ושרש המלאכים נמשך",[["1621","81","<b>הפחד אינו אלא מקרוב</b>: ראה גם לעיל פ' בשלח קמט, ד. וש\"נ."],["1622","82","<b>מרחוק ה' נראה לו</b>: ע\"פ ירמי' לא, ב."],["1623","83","<b>שנולדי'</b>: א: שלו."],["1624","84","<b>טעמי'</b>: א: ולטעמי'."],["1625","85","<b>ואהבת. . אפי' נוטל</b>: ואתחנן ו, ה [בדילוג]. ראה ספרי שם. ברכות נד, א (במשנה)."],["1626","86","<b>כי כל. . חיי נפשו</b>: איוב ב, ד [ושם: וכל. . בעד נפשו]."],["1627","87","<b>מי לי בשמים</b>: תהלים עג, כה."],["1628","88","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["1629","89","<b>הרגשה והדעת</b>: אג: הדעת וההרגשה."],["1630","90","<b>והאופנים וחיות הקדש</b>: ברכת יוצר."],["1631","91","<b>ג\"פ קדו\"ש שהשרפי' או[מרים]</b>: ישעי' ו, ב-ג."],["1632","92","<b>הוי\"ו דקדו\"ש. . ההמשכה והירידה</b>: ראה גם לקמן פ' תשא שפב, ב. וש\"נ."],["1633","93","<b>וי\"ו הוא ציור המשכה</b>: ראה גם לעיל פ' וארא עא, ג. בשלח קנ, ג. אגה\"ת פ\"ד."],["1634","94","<b>יחוה יחי' מיבעי' לי'</b>: ראה זהר תרומה קלז, א."],["1635","95","<b>ג\"פ קדוש. . דמחשבה דו\"מ. . דבי\"ע</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תכב. וש\"נ."],["1636","96","<b>בהפרש שבין נשמות למלאכי'</b>: ראה גם לעיל פ' שמות לט, ד. וש\"נ."],["1637","97","<b>ישראל עלה במח'</b>: ראה ב\"ר פ\"א, ד. הנסמן לעיל לב, ב."],["1638","98","<b>אחור וקדם צרתני</b>: תהלים קלט, ה. ראה ב\"ר פ\"ח, א. מאמרי אדה\"א דברים ח\"ג ע' תתקא. ח\"ב ע' תרנג."]]],[2300550300,"מבחי' דיבור העליון כמ\"ש בדבר ה' כו' וברוח פיו כל צבאם<sup data-n=\"1639\">99</sup> ואין ערך לדבור עם המח'. ואעפ\"י שאין דיבור בלא מחשבה היינו כשמדבר מה שחושב וחושב מה שמדבר שנק' דיבור שבמח' ומח' שבדבור כידוע, אבל בחי' הפנימי' המחשבה העצמי' שא\"א לבא בדבור משם מקור הנשמות שהן בבחי' עלמא דאתכסי'. וזהו ג\"פ קדו\"ש קדוש הראשון היינו להמשיך מקדש העליון שבפנימי' המח' העצמי' להיות נמשך בחי' הדעת הנ\"ל במחשבה העליונה שקדמה לדבור, ואח\"כ קדוש הב' יורדת השפע דדעת ממח' עליונה לדבור העליון דמשם שרש המלאכים מרוח פיו ית'. וזהו יום ליום יביע אומ\"ר<sup data-n=\"1640\">100</sup> (שהוא הדעת דז\"א דרוח<sup data-n=\"1641\">102</sup> הוא ממוצע בין אש למים כמ\"ש בזהר<sup data-n=\"1642\">103</sup> שם<sup data-n=\"1643\">101</sup> ) מן המדות דז\"א שנק' יום יביע למח' ואח\"כ לילה ללילה נמשך אל דרגין תתאין לדיבור ומעשה יחוה דעת מן בחי' המח' כו' וד\"ל. ובזה יובן מארז\"ל שאין המלאכי' יכולים לומר קדושה<sup data-n=\"1644\">104</sup> למעלה עד שישראל או' למטה, כי ישראל עלו במחשבה שקדם לדיבור כנ\"ל ע\"כ ע\"י קדושה שישראל או' למטה נמשך הדעת למח' העליונה ואז יוכל להיות המשכ' קדוש\"ה לדיבור מן המחשבה והוא קדוש שאו' המלאכי' שממשיכי' בחי' הדעת לדבור העליון שהוא שרשם ומקורם, ומן הדבור יורד עוד ונמשך למטה בעולם העשי' עד צבא השמים דעשי' שאו' קדוש הג' והוא קדוש ה' צבאות ממש עד סוף כל המדריגות דע' שרים<sup data-n=\"1645\">105</sup> שגם הם מקבלים מן המלאכים דעשי' והיינו מסוף מדרגות האופני'<sup data-n=\"1646\">106</sup> כידוע, וזהו ג\"פ קדוש נגד מחדו\"מ שהן ג' עולמות בי\"ע וכל זה הוא המשכת הדעת העליון למחדו\"מ עד שקדוש הג' הוא ה' צבאות מלא כה\"כ וד\"ל.\n<b>אך</b> מי הוא הממשיך כח הדעת בג' עולמות שהן ג\"פ קדוש הרי הוא ע\"י משה שנק' רועה שזן ומפרנס לכנס\"י למעלה בהמשכת הדעת ומשם יורד למטה במלאכי' כו' כנ\"ל בענין ונתתי עשב בשדך כו', ואמנם הנה אמרו בזהר דמשה משה לא פסיק טעמא<sup data-n=\"1647\">107</sup> <span data-k=\"pg\">818</span> ּ כו', פי' משה הוא בחי' הרועה הנאמן להמשיך דעת לכנס\"י שזהו בבחי' המח' העליונה ששם מקור נש\"י. ומ\"ש ב\"פ משה להיות כי מן המחשבה נמשך הדעת לדו\"מ ודרך כלל נק' המח' מדרגה עליונה בפ\"ע ודו\"מ מדרגה תחתונה בפ\"ע כי אין ערוך ביניהם כלל כי המחשבה שרשה בפנימי' ועצמי' הנפש ומתאחדת גם ברצון ותענוג ושכל כו', אבל הדו\"מ נבדלי' בבחי' חיצוני' כמו הבל הדבור היוצא לחוץ. וזהו עיקר ההפרש בין",[["1639","99","<b>בדבר ה'. . צבאם</b>: תהלים לג, ו."],["1640","100","<b>יום ליום יביע אומ\"ר</b>: תהלים יט, ג."],["1641","102","<b>דרוח</b>: אג: דרי\"ש."],["1642","103","<b>דרוח הוא ממוצע. . בזהר שם</b>: ראה זהר תרומה שם. פיה\"מ שם. לעיל פ' בשלח ריב, ב. וש\"נ."],["1643","101","<b>הדעת דז\"א. . בזהר שם</b>: תרומה קלו, ב. ראה סידור שחרית לשבת קפ, ב. פירוש המלות פ\"ל."],["1644","104","<b>שאין המלאכי'. . קדושה</b>: ראה חולין צא, ב."],["1645","105","<b>דע' שרים</b>: ראה זהר בראשית מו, סע\"ב. שע\"ת עד, א הערה 2."],["1646","106","<b>דע' שרים. . האופני'</b>: ראה גם לעיל פ' בא קכו, ד. וש\"נ."],["1647","107","<b>דמשה משה לא פסיק טעמא</b>: שמות ג, ד. זהר וירא קכ, ב. נשא (אד\"ר) קלח, א. בלק קפז, ב. קרבן אהרן לתו\"כ ויקרא א, א ספ\"א. מאמרי אדה\"ז תקס\"ה כאן (ע' רנג וס\"ע ערה ואילך. שם ע' רנו נוסח א'. לעיל רעח, ב. רפא, ב). תקס\"ו ע' ריט. תו\"א כאן (עה, ג. עו, ג). לקו\"ת מטות פז, ג. לקו\"ש משפטים (כרך כו) ס\"ע 359 ואילך."]]],[2300550326,"שרש הנשמות לשרש המלאכי' שהנשמ[ו'] מבחי' המח' שנק' פנימי' הכלים והמלאכים הם מחיצוני' הכלים דו\"מ כמו ברוח פיו כו', והיינו שהנשמות נק' מהלכים והמלאכים נק' עומדים<sup data-n=\"1648\">108</sup> וכמ\"ש במ\"א באריכות וד\"ל. וזהו משה משה לא פסיק טעמא דהגם שאין ערך לדבור ומעשה לגבי המח' עכ\"ז לגבי משה שניהם שוים והמשיך הדעת למח' וממח' לדו\"מ ולא פסיק טעמא בין ב' המשכות הללו, דב\"פ משה הוא לנגד ב' המשכות הללו תחלה המשיך הדעת במח' מדרגה הראשונה ואח\"כ ממח' לדו\"מ ולא יש חילוק מדרגות כלל ביניהם לגבי משה, משום דשרש מדרגת משה ששרשו מאד נעלה בבחי' ומדרגה שלמעלה משניהם וכמ\"ש בו כי מן המים משיתיהו<sup data-n=\"1649\">109</sup> (וכמשי\"ת<sup data-n=\"1650\">110</sup> ) ע\"כ אין הפרש אצלו כלל וכלל בין פנימי' המח' שרש נש\"י ובין חיצוני' הדבור דמלאכים הנ\"ל וע\"כ לא פסיק טעמא בין ב\"פ משה הללו וד\"ל.\n[ה] <b>וזהו</b> ואלה המשפטים אשר תשים לפניהם, פי' משפטים לשון הליכה כתרגום כמשפט הראשון כהלכתא קדמייתא<sup data-n=\"1651\">111</sup>, והענין הוא כידוע שבחי' המשפט הוא [ב]בחי' הדעת שכולל חו\"ג<sup data-n=\"1652\">112</sup> כמו ושפטו העדה<sup data-n=\"1653\">113</sup> כו' שיש מטה המשפט כלפי חסד ויש מטה כלפי הדין וכאשר יהי' הכרע בדבר נק' משפט צדק שנשפט בקו היושר, ונמצא שהמשפט הוא בבחי' הדעת שהוא הנק' דעת נוטה<sup data-n=\"1654\">114</sup> להכריע כידוע. וגם כאן בענין בחי' הדעת הנ\"ל בבחי' הכרה והרגשה שהוא לאמיתת הדבר כמו שהוא שכולל ב' הקוין דאוי\"ר ממילא כנ\"ל והילוך זה הוא מראשית הגילוי דבחי' משה למחשבה דו\"מ שהן ג' עולמות בי\"ע כנ\"ל. וזהו ואלה המשפטים בחי' הדעת שממשיך משה רועה הנאמן לכנ\"י מלמעלה למטה בדרך הילוך ולכך נק' משפטים. וזהו אשר תשים לפניהם לפניהם דוקא לפנימי' המדות כו' שהדעת הוא עיקר חיות כו' שהוא בחי' פני אדם שיהי' גם בחי' זרע בהמה בבחי' זרע אדם ע\"י הדעת אשר תשי\"ם אתה דוקא לפי ששרש משה מאד נעלה עד שיוכל להמשיך הדעת עד הקטן כמו בגדול כנ\"ל (ועוד יתפרש פי' משפטי' בענין מדת יעקב שהוא בחי' הרחמים<sup data-n=\"1655\">115</sup> דמשפט איהו רחמי<sup data-n=\"1656\">116</sup> שהוא בחי' הדעת כידוע דמשה מלגאו בבחי' הדעת ויעקב מלבר<sup data-n=\"1657\">117</sup> בבחי' הרחמי' דכמו שהדעת כולל חו\"ג בפנימי' שלהן כנ\"ל, כך הרחמים כלול מחו\"ג<sup data-n=\"1658\">118</sup> בחיצוניות שלהם. וראי' ממ\"ש כל מי שאין בו דעה<sup data-n=\"1659\">119</sup> אסור לרחם עליו לפי שבחי' ההרגשה והכרה בדעת הנ\"ל הוא",[["1648","108","<b>שהנשמות נק' מהלכים והמלאכים נק' עומדים</b>: ראה לעיל פ' בשלח קסד, ב. וש\"נ."],["1649","109","<b>כי מן המים משיתיהו</b>: שמות ב, י."],["1650","110","<b>וכמשי\"ת</b>: ראה לקמן רפה, א. וברשימת הכת\"י כאן."],["1651","111","<b>כמשפט הראשון כהלכתא קדמייתא</b>: ת\"א וישב מ, יג. ראה סה\"מ מלוקט ח\"א ע' קס הערה 4. אוה\"ת כאן (ע' א'קיט)."],["1652","112","<b>הדעת שכולל חו\"ג</b>: ראה גם לעיל פ' וארא נז, ד. וש\"נ."],["1653","113","<b>ושפטו העדה</b>: מסעי לה, כד."],["1654","114","<b>דעת נוטה</b>: ראה גם לעיל פ' שמות מב, א. וש\"נ."],["1655","115","<b>יעקב שהוא בחי' הרחמים</b>: ראה זהר לך פז, ב. הנסמן במאמרי אדה\"א בראשית ע' קנו."],["1656","116","<b>דמשפט איהו רחמי</b>: ראה ת\"ז בהקדמה (יז, ב). מאמרי אדה\"א דברים ח\"א ע' קח. וש\"נ."],["1657","117","<b>דמשה מלגאו. . ויעקב מלבר</b>: ראה ת\"ז תי\"ג (כט, א). לעיל פ' וארא פה, ד."],["1658","118","<b>הרחמים כלול מחו\"ג</b>: ראה גם לעיל פ' וארא פה, ד. וש\"נ."],["1659","119","<b>כל מי שאין בו דעה</b>: ראה ברכות לג, א. לעיל פ' וארא שם הערה 864."]]],[2300550351,"המביא לבחי' הרחמים שהתינוק שאין בו דעת אינו מרחם כלל, וכן לחוס ולרחם על עני מדוכא הוא לפי ערך ההרגשה שמרגיש בצערו כו'. וגם בעבודת ה' לחוס ולרחם על נפשו שנתרחקה מאד מאור פני מלך עד שיתמרמר מאד בנפשו על עוצם ריחוקו ופירודו כו' זהו לפי ערך הדעת והרגשה דוקא, וע\"כ כל מי שאין בו דעה אסור לרחם עליו. <span data-k=\"pg\">תט</span> ּ ולזה אנו מבקשים אתה חונן לאד\"ם דעת<sup data-n=\"1660\">120</sup> שיהי' מרגיש בחי' אלקות כו' ואז ממילא יתעורר רחמים וירגיז על הרע כמאמר לעולם ירגיז<sup data-n=\"1661\">121</sup> כו' והוא המרירות העצומה ביותר כנ\"ל וישוב בתשובה וזהו השיבנו<sup data-n=\"1662\">122</sup> שאחר אתה חונן כו' וד\"ל. ונמצא שהרחמים כלול מחו\"ג הגבורה הוא שמרגיז כו' והחסדי' הוא שמחמת האהבה המוסתרת שאהב לדבקה בו ית' והוא נתרחק כ\"כ יצר לו ביותר כו', וא\"כ הרחמים פשוטי' שמעורר על נפשו כלול משניהם כו' והוא השי\"ן שבעשב שכלול מג' קוין שנמשך עד סוף העשי' גם לבהמתך כו' כנ\"ל. וזהו המשפטי' שהוא הדעת והרחמים שתשים לפניהם לפנימיות המדות וגם לחיצוני' בבחי' הרחמים לבד שהוא לפניהם בחיצוניות כו'.",[["1660","120","<b>אתה חונן לאד\"ם דעת</b>: תפלת שמו\"ע."],["1661","121","<b>לעולם ירגיז</b>: ראה לעיל פ' בשלח רכו, ב. וש\"נ."],["1662","122","<b>השיבנו</b>: תפלת שמו\"ע. ראה גם שע\"ת ב, א. פא, א."]]]]});
